    def insert_process(self, process: AgentProcess) -> None:
        with self.transaction() as cur:
            cur.execute(
                """
                INSERT INTO processes (
                    pid, parent_pid, image_id, status, goal_oid, memory_view_json,
                    capabilities_json, loaded_skills_json, tool_table_json, model_tool_table_json, event_cursor,
                    checkpoint_head, status_message, wait_state_json, outcome_json,
                    state_generation, resource_budget_json, resource_usage_json,
                    working_directory, llm_profile_id, revision, execution_generation,
                    execution_owner_id, execution_lease_id, task_run_id,
                    task_run_epoch, task_run_role, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                self._process_params(process),
            )
            self._replace_process_tool_bindings(
                cur,
                process.pid,
                process.tool_table,
                process.model_tool_table,
            )
            self._ensure_process_terminal_cleanup_intent(
                cur,
                pid=process.pid,
                status=process.status,
            )
            self.observe_process_concurrency(
                process.pid,
                revision=process.revision,
                execution_generation=process.execution_generation,
                state_generation=process.state_generation,
                cursor=cur,
            )

    @staticmethod
    def _ensure_process_terminal_cleanup_intent(
        cursor: Any,
        *,
        pid: str,
        status: ProcessStatus | str,
    ) -> None:
        selected = ProcessStatus(status)
        if selected not in {
            ProcessStatus.EXITED,
            ProcessStatus.FAILED,
            ProcessStatus.KILLED,
        }:
            return
        now = utc_now()
        cursor.execute(
            """
            INSERT INTO process_terminal_cleanups (
                pid, terminal_status, state, completed_phases_json,
                attempt_count, owner_id, lease_id, failed_phase,
                last_error_json, created_at, updated_at
            ) VALUES (?, ?, 'pending', '[]', 0, NULL, NULL, NULL, NULL, ?, ?)
            ON CONFLICT(pid) DO NOTHING
            """,
            (pid, selected.value, now, now),
        )

    def ensure_process_terminal_cleanup_intent(
        self,
        pid: str,
        status: ProcessStatus | str,
    ) -> None:
        """Create the lifecycle receipt when a typed bulk path publishes terminal state."""

        with self.transaction() as cursor:
            self._ensure_process_terminal_cleanup_intent(
                cursor,
                pid=pid,
                status=status,
            )

    @staticmethod
    def _replace_process_tool_bindings(
        cursor: Any,
        pid: str,
        tool_table: Mapping[str, str],
        model_tool_table: Mapping[str, str],
    ) -> None:
        """Replace the indexed reverse projection of one process's tool maps."""

        if not isinstance(pid, str) or not pid or "\x00" in pid:
            raise ValidationError("process tool bindings require a valid process ID")
        rows: list[tuple[str, str, str, str]] = []
        for binding_kind, bindings in (
            ("callable", tool_table),
            ("model", model_tool_table),
        ):
            if not isinstance(bindings, Mapping):
                raise ValidationError("process tool bindings require object mappings")
            for tool_name, tool_id in bindings.items():
                if (
                    not isinstance(tool_name, str)
                    or not tool_name
                    or "\x00" in tool_name
                    or not isinstance(tool_id, str)
                    or not tool_id
                    or "\x00" in tool_id
                ):
                    raise ValidationError(
                        "process tool bindings require non-empty string names and identities"
                    )
                rows.append((pid, binding_kind, tool_name, tool_id))
        cursor.execute("DELETE FROM process_tool_bindings WHERE pid = ?", (pid,))
        if rows:
            cursor.executemany(
                "INSERT INTO process_tool_bindings "
                "(pid, binding_kind, tool_name, tool_id, "
                "jit_rehydration_eligible) VALUES (?, ?, ?, ?, ?)",
                ((*row, 0) for row in rows),
            )
            SQLRuntimeStore._refresh_process_binding_jit_eligibility(
                cursor,
                pid=pid,
            )

    @staticmethod
    def _refresh_process_binding_jit_eligibility(
        cursor: Any,
        *,
        pid: str | None = None,
        tool_id: str | None = None,
    ) -> None:
        """Synchronize the indexed JIT projection with durable Tool metadata."""

        if (pid is None) == (tool_id is None):
            raise ValueError(
                "JIT binding eligibility refresh requires exactly one identity"
            )
        where_column = "pid" if pid is not None else "tool_id"
        where_value = pid if pid is not None else tool_id
        cursor.execute(
            "UPDATE process_tool_bindings "
            "SET jit_rehydration_eligible = CASE "
            "WHEN binding_kind = ? AND EXISTS ("
            "SELECT 1 FROM tools "
            "WHERE tools.tool_id = process_tool_bindings.tool_id "
            "AND tools.ephemeral = 1"
            ") THEN 1 ELSE 0 END "
            f"WHERE {where_column} = ?",
            ("callable", where_value),
        )

    def tool_id_referenced_outside_process(
        self,
        tool_id: str,
        *,
        excluding_pid: str,
    ) -> bool:
        if (
            not isinstance(tool_id, str)
            or not tool_id
            or "\x00" in tool_id
            or not isinstance(excluding_pid, str)
            or not excluding_pid
            or "\x00" in excluding_pid
        ):
            raise ValidationError(
                "process tool reverse lookup requires valid tool and process identities"
            )
        rows = self._query(
            "SELECT 1 FROM process_tool_bindings "
            "WHERE tool_id = ? AND pid <> ? LIMIT 1",
            (tool_id, excluding_pid),
        )
        return bool(rows)

    def tool_id_referenced_outside_scope(
        self,
        tool_id: str,
        *,
        scoped_pids: Iterable[str],
    ) -> bool:
        if not isinstance(tool_id, str) or not tool_id or "\x00" in tool_id:
            raise ValidationError(
                "process tool reverse lookup requires a valid tool identity"
            )
        if isinstance(scoped_pids, (str, bytes, bytearray)):
            raise ValidationError("process tool scope must be an iterable of identities")
        selected_pids: set[str] = set()
        for pid in scoped_pids:
            if not isinstance(pid, str) or not pid or "\x00" in pid:
                raise ValidationError(
                    "process tool scope requires valid process identities"
                )
            selected_pids.add(pid)
        with self.transaction() as cursor:
            cursor.execute(
                "SELECT DISTINCT pid FROM process_tool_bindings WHERE tool_id = ?",
                (tool_id,),
            )
            while True:
                row = cursor.fetchone()
                if row is None:
                    return False
                pid = row["pid"]
                if not isinstance(pid, str) or not pid or "\x00" in pid:
                    raise ValidationError(
                        "process tool reverse lookup returned an invalid process identity"
                    )
                if pid not in selected_pids:
                    return True

    def delete_tool_if_unreferenced(
        self,
        tool_id: str,
        *,
        excluding_pid: str,
    ) -> bool:
        if (
            not isinstance(tool_id, str)
            or not tool_id
            or "\x00" in tool_id
            or not isinstance(excluding_pid, str)
            or not excluding_pid
            or "\x00" in excluding_pid
        ):
            raise ValidationError(
                "tool deletion requires valid tool and process identities"
            )
        with self.transaction() as cursor:
            referenced = cursor.execute(
                "SELECT 1 FROM process_tool_bindings "
                "WHERE tool_id = ? AND pid <> ? LIMIT 1",
                (tool_id, excluding_pid),
            ).fetchone()
            if referenced is not None:
                return False
            cursor.execute("DELETE FROM tools WHERE tool_id = ?", (tool_id,))
            self._refresh_process_binding_jit_eligibility(
                cursor,
                tool_id=tool_id,
            )
            return True

    @staticmethod
    def _process_concurrency_counter_names(pid: str) -> tuple[str, str, str]:
        return (
            f"{_PROCESS_REVISION_COUNTER_PREFIX}{pid}",
            f"{_PROCESS_EXECUTION_COUNTER_PREFIX}{pid}",
            f"{_PROCESS_STATE_COUNTER_PREFIX}{pid}",
        )

    @staticmethod
    def _raise_runtime_counter_floor(cur: Any, counter_name: str, floor: int) -> None:
        selected_floor = max(0, int(floor))
        cur.execute(
            """
            INSERT INTO runtime_counters (counter_name, value)
            VALUES (?, ?)
            ON CONFLICT(counter_name) DO NOTHING
            """,
            (counter_name, selected_floor),
        )
        cur.execute(
            """
            UPDATE runtime_counters
               SET value = CASE WHEN value < ? THEN ? ELSE value END
             WHERE counter_name = ?
            """,
            (selected_floor, selected_floor, counter_name),
        )

    def observe_process_concurrency(
        self,
        pid: str,
        *,
        revision: int,
        execution_generation: int,
        state_generation: int | None = None,
        cursor: Any | None = None,
    ) -> None:
        """Persist monotonic process concurrency high-water marks."""

        if cursor is None:
            with self.transaction() as cur:
                self.observe_process_concurrency(
                    pid,
                    revision=revision,
                    execution_generation=execution_generation,
                    state_generation=state_generation,
                    cursor=cur,
                )
            return
        revision_counter, execution_counter, state_counter = (
            self._process_concurrency_counter_names(pid)
        )
        self._raise_runtime_counter_floor(cursor, revision_counter, revision)
        self._raise_runtime_counter_floor(
            cursor,
            execution_counter,
            execution_generation,
        )
        if state_generation is not None:
            self._raise_runtime_counter_floor(
                cursor,
                state_counter,
                state_generation,
            )

    def reserve_process_restore_epoch(
        self,
        pid: str,
        *,
        revision_floor: int,
        execution_generation_floor: int,
        state_generation_floor: int,
        cursor: Any | None = None,
    ) -> tuple[int, int, int]:
        """Allocate concurrency values newer than every previously observed value."""

        floor = ProcessRestoreEpoch(
            pid=pid,
            revision=max(0, int(revision_floor)),
            execution_generation=max(0, int(execution_generation_floor)),
            state_generation=max(0, int(state_generation_floor)),
        )
        reserved = self.reserve_process_restore_epochs((floor,), cursor=cursor)[0]
        return (
            reserved.revision,
            reserved.execution_generation,
            reserved.state_generation,
        )

    def reserve_process_restore_epochs(
        self,
        floors: Iterable[ProcessRestoreEpoch],
        *,
        cursor: Any | None = None,
    ) -> tuple[ProcessRestoreEpoch, ...]:
        """Reserve a deterministic, atomic batch of monotonic process epochs.

        Each PID is floored and incremented exactly once. Sorting identities
        before taking counter-row locks prevents overlapping PostgreSQL restores
        from acquiring them in conflicting orders.
        """

        selected = tuple(floors)
        if any(not isinstance(item, ProcessRestoreEpoch) for item in selected):
            raise ValidationError(
                "process restore epoch batch requires typed floor values"
            )
        selected_pids = [str(item.pid) for item in selected]
        if len(selected_pids) != len(set(selected_pids)):
            raise ValidationError(
                "process restore epoch batch must not contain duplicate PIDs"
            )
        if not selected:
            return ()
        if cursor is None:
            with self.transaction() as cur:
                return self.reserve_process_restore_epochs(
                    selected,
                    cursor=cur,
                )

        ordered = tuple(sorted(selected, key=lambda item: str(item.pid)))
        reserved_by_pid: dict[str, ProcessRestoreEpoch] = {}
        for offset in range(
            0,
            len(ordered),
            _PROCESS_RESTORE_EPOCH_PID_BATCH_SIZE,
        ):
            batch = ordered[
                offset : offset + _PROCESS_RESTORE_EPOCH_PID_BATCH_SIZE
            ]
            counter_rows: list[tuple[str, int]] = []
            counters_by_pid: dict[str, tuple[str, str, str]] = {}
            for floor in batch:
                counters = self._process_concurrency_counter_names(str(floor.pid))
                counters_by_pid[str(floor.pid)] = counters
                counter_rows.extend(
                    (
                        (counters[0], floor.revision),
                        (counters[1], floor.execution_generation),
                        (counters[2], floor.state_generation),
                    )
                )

            value_placeholders = ", ".join("(?, ?)" for _ in counter_rows)
            cursor.execute(
                "INSERT INTO runtime_counters (counter_name, value) VALUES "
                f"{value_placeholders} "
                "ON CONFLICT(counter_name) DO UPDATE SET value = CASE "
                "WHEN runtime_counters.value < excluded.value "
                "THEN excluded.value ELSE runtime_counters.value END",
                tuple(
                    value
                    for counter_name, counter_value in counter_rows
                    for value in (counter_name, counter_value)
                ),
            )
            counter_names = tuple(counter_name for counter_name, _ in counter_rows)
            name_placeholders = ", ".join("?" for _ in counter_names)
            cursor.execute(
                "UPDATE runtime_counters SET value = value + 1 "
                f"WHERE counter_name IN ({name_placeholders})",
                counter_names,
            )
            rows = list(
                cursor.execute(
                    "SELECT counter_name, value FROM runtime_counters "
                    f"WHERE counter_name IN ({name_placeholders}) "
                    "ORDER BY counter_name",
                    counter_names,
                )
            )
            values = {
                str(row["counter_name"]): int(row["value"])
                for row in rows
            }
            if len(values) != len(counter_names) or set(values) != set(counter_names):
                raise ValidationError(
                    "process restore epoch reservation returned an incomplete "
                    "or unexpected counter set"
                )
            for floor in batch:
                pid = str(floor.pid)
                revision_counter, execution_counter, state_counter = (
                    counters_by_pid[pid]
                )
                reserved_by_pid[pid] = ProcessRestoreEpoch(
                    pid=pid,
                    revision=values[revision_counter],
                    execution_generation=values[execution_counter],
                    state_generation=values[state_counter],
                )

        if set(reserved_by_pid) != set(selected_pids):
            raise ValidationError(
                "process restore epoch reservation returned an incomplete or "
                "unexpected process set"
            )
        return tuple(reserved_by_pid[pid] for pid in sorted(reserved_by_pid))

    def update_process(
        self,
        process: AgentProcess,
    ) -> None:
        """Compatibility CAS for callers not yet expressed as a domain patch.

        The revision carried by ``process`` is the expected revision.  A stale
        object can no longer overwrite a concurrent mutation, and an ordinary
        update can never move a terminal process to another state.
        """

        self._update_process(process, allow_state_transition=False)

    def _update_process(
        self,
        process: AgentProcess,
        *,
        allow_state_transition: bool,
    ) -> None:
        expected_revision = int(process.revision)
        with self.transaction() as cur:
            rows = list(cur.execute("SELECT * FROM processes WHERE pid = ?", (process.pid,)))
            if not rows:
                raise ProcessRevisionConflict(f"process no longer exists: {process.pid}")
            current = rows[0]
            generation, owner_id, lease_id, worker_clause, worker_params = (
                self._process_update_fence(
                    current,
                    process,
                    expected_revision=expected_revision,
                    cursor=cur,
                )
            )
            persisted = self._row_to_process(current)
            self._validate_process_state_write(
                process,
                persisted=persisted,
                allow_state_transition=allow_state_transition,
            )

            updated = cur.execute(
                f"""
                UPDATE processes
                   SET parent_pid = ?, image_id = ?, status = ?, goal_oid = ?,
                       memory_view_json = ?, capabilities_json = ?, loaded_skills_json = ?,
                       tool_table_json = ?, model_tool_table_json = ?, event_cursor = ?, checkpoint_head = ?,
                       status_message = ?, wait_state_json = ?, outcome_json = ?, state_generation = ?,
                       resource_budget_json = ?, resource_usage_json = ?,
                       working_directory = ?, llm_profile_id = ?, created_at = ?, updated_at = ?,
                       revision = revision + 1, execution_generation = ?,
                       execution_owner_id = ?, execution_lease_id = ?
                 WHERE pid = ? AND revision = ?{worker_clause}
                """,
                (
                    process.parent_pid,
                    process.image_id,
                    process.status.value,
                    process.goal_oid,
                    dumps(process.memory_view) if process.memory_view else None,
                    dumps(process.capabilities),
                    dumps(process.loaded_skills),
                    dumps(process.tool_table),
                    dumps(process.model_tool_table),
                    process.event_cursor,
                    process.checkpoint_head,
                    process.status_message,
                    dumps(process_wait_state_to_mapping(process.wait_state)),
                    dumps(process_outcome_to_mapping(process.outcome)),
                    process.state_generation,
                    dumps(process.resource_budget),
                    dumps(process.resource_usage),
                    process.working_directory,
                    process.llm_profile_id,
                    process.created_at,
                    process.updated_at,
                    generation,
                    owner_id,
                    lease_id,
                    process.pid,
                    expected_revision,
                    *worker_params,
                ),
            )
            if updated.rowcount != 1:
                raise ProcessRevisionConflict(f"process revision conflict for {process.pid}")
            self._ensure_process_terminal_cleanup_intent(
                cur,
                pid=process.pid,
                status=process.status,
            )
            self._replace_process_tool_bindings(
                cur,
                process.pid,
                process.tool_table,
                process.model_tool_table,
            )
            self.observe_process_concurrency(
                process.pid,
                revision=expected_revision + 1,
                execution_generation=generation,
                state_generation=process.state_generation,
                cursor=cur,
            )
        process.revision = expected_revision + 1
        process.execution_generation = generation
        process.execution_owner_id = owner_id
        process.execution_lease_id = lease_id

    @staticmethod
    def _validate_process_state_write(
        process: AgentProcess,
        *,
        persisted: AgentProcess | None = None,
        allow_state_transition: bool,
    ) -> None:
        validate_process_state_fields(
            process.status.value,
            process.wait_state,
            process.outcome,
        )
        if isinstance(process.wait_state, StaleExecutionProcessWait) and (
            persisted is None or process.wait_state != persisted.wait_state
        ):
            raise ValidationError(
                "stale-execution recovery receipts are reserved for Store recovery"
            )
        if (
            not isinstance(process.state_generation, int)
            or isinstance(process.state_generation, bool)
            or process.state_generation < 0
        ):
            raise ValidationError(
                "process state_generation must be a non-negative integer"
            )
        if persisted is None:
            return
        semantic_changed = (
            process.status != persisted.status
            or process.wait_state != persisted.wait_state
            or process.outcome != persisted.outcome
            or process.state_generation != persisted.state_generation
        )
        if semantic_changed and not allow_state_transition:
            raise ValidationError(
                "process semantic state must use ProcessTransitionService"
            )
        if allow_state_transition and (
            process.state_generation != persisted.state_generation + 1
        ):
            raise ProcessRevisionConflict(
                f"process state generation conflict for {process.pid}: "
                f"expected {persisted.state_generation + 1}, "
                f"found {process.state_generation}"
            )

    def _process_update_fence(
        self,
        current: Any,
        process: AgentProcess,
        *,
        expected_revision: int,
        cursor: Any,
    ) -> tuple[int, Any, Any, str, tuple[Any, ...]]:
        terminal = {
            ProcessStatus.EXITED.value,
            ProcessStatus.FAILED.value,
            ProcessStatus.KILLED.value,
        }
        current_revision = int(current["revision"])
        current_status = str(current["status"])
        if current_revision != expected_revision:
            raise ProcessRevisionConflict(
                f"process revision conflict for {process.pid}: "
                f"expected {expected_revision}, found {current_revision}"
            )
        terminal_mutation = current_terminal_process_mutation()
        post_exec_mutation = current_post_exec_completion_mutation()
        if current_status in terminal:
            self._assert_terminal_mutation_allowed(
                terminal_mutation,
                process=process,
                current=current,
                expected_revision=expected_revision,
            )
        if current_status in terminal and process.status.value != current_status:
            raise ProcessRevisionConflict(
                f"terminal process {process.pid} cannot transition from "
                f"{current_status} to {process.status.value}"
            )

        generation = int(current["execution_generation"])
        owner_id = current["execution_owner_id"]
        lease_id = current["execution_lease_id"]
        if process.status.value in terminal or (
            current_status == ProcessStatus.RUNNING.value
            and process.status.value != ProcessStatus.RUNNING.value
        ):
            generation += 1
            owner_id = None
            lease_id = None

        execution_token = current_process_execution_token()
        self._assert_execution_target_allowed(
            execution_token,
            target_pid=process.pid,
            current_status=current_status,
        )
        self._assert_process_exec_admission_update_owner(
            cursor,
            current=current,
            process=process,
            execution_token=execution_token,
        )
        post_exec_fence = post_exec_mutation is not None
        if post_exec_fence:
            self._assert_post_exec_completion_allowed(
                post_exec_mutation,
                process=process,
                current=current,
                expected_revision=expected_revision,
            )
        worker_fence = (
            execution_token is not None
            and execution_token.pid == process.pid
            and current_status not in terminal
            and not post_exec_fence
        )
        if worker_fence and (
            current_status != ProcessStatus.RUNNING.value
            or int(current["execution_generation"]) != execution_token.generation
            or current["execution_owner_id"] != execution_token.owner_id
            or current["execution_lease_id"] != execution_token.lease_id
        ):
            raise ProcessRevisionConflict(
                f"stale process execution token cannot mutate {process.pid}"
            )
        if post_exec_fence:
            mutation_clause = (
                " AND status = ? AND execution_generation = ? "
                "AND execution_owner_id IS NULL AND execution_lease_id IS NULL"
            )
            mutation_params = (
                ProcessStatus.RUNNABLE.value,
                post_exec_mutation.expected_generation,
            )
        elif worker_fence:
            mutation_clause = (
                " AND status = ? AND execution_generation = ? "
                "AND execution_owner_id = ? AND execution_lease_id = ?"
            )
            mutation_params: tuple[Any, ...] = (
                ProcessStatus.RUNNING.value,
                execution_token.generation,
                execution_token.owner_id,
                execution_token.lease_id,
            )
        elif current_status in terminal:
            mutation_clause = (
                " AND status = ? AND execution_generation = ? "
                "AND execution_owner_id IS NULL AND execution_lease_id IS NULL"
            )
            mutation_params = (current_status, int(current["execution_generation"]))
        else:
            mutation_clause = ""
            mutation_params = ()
        return generation, owner_id, lease_id, mutation_clause, mutation_params

    def _assert_process_exec_admission_update_owner(
        self,
        cur: Any,
        *,
        current: Any,
        process: AgentProcess,
        execution_token: ProcessExecutionToken | None,
    ) -> None:
        """Fence an admitted exec while preserving explicit emergency control."""

        if str(current["status"]) != ProcessStatus.RUNNING.value:
            return
        pid = process.pid
        generation = int(current["execution_generation"])
        owner_id = current["execution_owner_id"]
        lease_id = current["execution_lease_id"]
        if owner_id is None or lease_id is None:
            return
        current_token = ProcessExecutionToken(
            pid=pid,
            generation=generation,
            owner_id=str(owner_id),
            lease_id=str(lease_id),
            task_run_epoch=(
                int(current["task_run_epoch"])
                if current["task_run_epoch"] is not None
                else None
            ),
        )
        takeover_intent = current_process_execution_takeover_intent()
        if takeover_intent is None and execution_token == current_token:
            return
        takeover_write = self._process_exec_takeover_write_allowed(
            current,
            process,
            current_token,
        )
        if takeover_intent is not None and not takeover_write:
            raise ProcessRevisionConflict(
                f"process execution takeover write is outside its exact intent: {pid}"
            )
        publications = list(
            cur.execute(
                """
                SELECT publication_id, plan_json
                  FROM runtime_publications
                 WHERE kind = 'process_exec' AND pid = ?
                   AND state IN ('planning', 'applying', 'rollback_pending',
                                 'failed', 'manual')
                 ORDER BY created_at, publication_id
                """,
                (pid,),
            )
        )
        for publication in publications:
            try:
                plan = loads(publication["plan_json"], {})
            except (TypeError, ValueError):
                raise ProcessRevisionConflict(
                    "active process exec publication plan is invalid: "
                    f"{publication['publication_id']}"
                ) from None
            if not isinstance(plan, Mapping):
                raise ProcessRevisionConflict(
                    "active process exec publication plan is invalid: "
                    f"{publication['publication_id']}"
                )
            publication_token = (
                plan.get("admission_execution_generation"),
                plan.get("admission_execution_owner_id"),
                plan.get("admission_execution_lease_id"),
            )
            if publication_token == (generation, owner_id, lease_id):
                if takeover_write:
                    return
                raise ProcessRevisionConflict(
                    "process exec admission rejects a non-owner process write: "
                    f"{pid} ({publication['publication_id']})"
                )

    def _process_exec_takeover_write_allowed(
        self,
        current: Any,
        process: AgentProcess,
        current_token: ProcessExecutionToken,
    ) -> bool:
        intent = current_process_execution_takeover_intent()
        if (
            intent is None
            or intent.target_pid != process.pid
            or intent.source_execution_token != current_token
            or intent.source_state_generation != int(current["state_generation"])
        ):
            return False
        if process.status == ProcessStatus.RUNNING:
            if intent.stage == 0:
                return self._record_takeover_reason_capability(
                    current,
                    process,
                    intent,
                )
            if intent.stage == 1:
                return self._record_takeover_reason_root(current, process, intent)
            return False
        return self._validate_takeover_state_transition(current, process, intent)

    def _record_takeover_reason_capability(
        self,
        current: Any,
        process: AgentProcess,
        intent: Any,
    ) -> bool:
        current_process = self._row_to_process(current)
        if (
            intent.reason_text is None
            or intent.reason_action is None
            or int(current["revision"]) != intent.source_revision
            or process.capabilities[:-1] != current_process.capabilities
            or len(process.capabilities) != len(current_process.capabilities) + 1
        ):
            return False
        expected = deepcopy(current_process)
        expected.capabilities = list(process.capabilities)
        expected.updated_at = process.updated_at
        if expected != process:
            return False
        capability = self.get_capability(process.capabilities[-1])
        oid = (
            capability.resource.removeprefix("object:")
            if capability is not None
            else ""
        )
        obj = self.get_object(oid) if oid else None
        valid = self._takeover_reason_artifacts_match(
            capability,
            obj,
            process=process,
            oid=oid,
            intent=intent,
        )
        if valid:
            assert capability is not None
            intent.reason_capability_id = capability.cap_id
            intent.reason_oid = oid
            intent.stage = 1
        return valid

    @staticmethod
    def _takeover_reason_artifacts_match(
        capability: Capability | None,
        obj: AgentObject | None,
        *,
        process: AgentProcess,
        oid: str,
        intent: Any,
    ) -> bool:
        return bool(
            capability is not None
            and capability.active
            and capability.subject == process.pid
            and capability.issued_by == "memory"
            and capability.metadata.get("object_handle") is True
            and capability.resource == f"object:{oid}"
            and obj is not None
            and obj.type == ObjectType.MESSAGE
            and obj.created_by == process.pid
            and obj.owner_kind == ObjectOwnerKind.PROCESS
            and obj.owner_id == process.pid
            and obj.payload == {"reason": intent.reason_text}
            and obj.provenance.created_from_action == intent.reason_action
        )

    def _record_takeover_reason_root(
        self,
        current: Any,
        process: AgentProcess,
        intent: Any,
    ) -> bool:
        if int(current["revision"]) != intent.source_revision + 1:
            return False
        current_process = self._row_to_process(current)
        expected = deepcopy(current_process)
        expected.memory_view = deepcopy(process.memory_view)
        expected.updated_at = process.updated_at
        if expected != process or process.memory_view is None:
            return False
        old_roots = (
            current_process.memory_view.roots
            if current_process.memory_view is not None
            else []
        )
        if (
            process.memory_view.roots[:-1] != old_roots
            or len(process.memory_view.roots) != len(old_roots) + 1
        ):
            return False
        root = process.memory_view.roots[-1]
        if current_process.memory_view is None:
            view_valid = bool(
                process.memory_view.view_id
                and process.memory_view.owner_pid == process.pid
                and process.memory_view.filters == []
                and process.memory_view.rights_policy == "attenuate"
                and process.memory_view.created_from is None
                and process.memory_view.mode == ViewMode.READ_ONLY
            )
        else:
            expected_view = deepcopy(current_process.memory_view)
            expected_view.roots.append(root)
            view_valid = process.memory_view == expected_view
        capability = self.get_capability(str(intent.reason_capability_id or ""))
        valid = bool(
            view_valid
            and capability is not None
            and root.oid == intent.reason_oid
            and root.capability_id == capability.cap_id
            and root.rights == capability.rights
            and root.expires_at == capability.expires_at
        )
        if valid:
            intent.stage = 2
        return valid

    def _validate_takeover_state_transition(
        self,
        current: Any,
        process: AgentProcess,
        intent: Any,
    ) -> bool:
        reason_expected = intent.reason_text is not None
        prep_count = 2 if reason_expected else 0
        if (
            int(current["revision"]) != intent.source_revision + prep_count
            or intent.stage != prep_count
            or process.status.value != intent.intended_status
            or process.state_generation != intent.source_state_generation + 1
        ):
            return False
        current_process = self._row_to_process(current)
        expected = deepcopy(current_process)
        expected.status = process.status
        expected.wait_state = process.wait_state
        expected.outcome = process.outcome
        expected.state_generation = process.state_generation
        expected.status_message = process.status_message
        expected.updated_at = process.updated_at
        if expected != process:
            return False
        reason_oid = intent.reason_oid if reason_expected else None
        if process.status == ProcessStatus.PAUSED:
            wait_state = process.wait_state
            valid = bool(
                process.outcome is None
                and isinstance(wait_state, (PausedProcessWait, HostResumeProcessWait))
                and wait_state.kind == intent.wait_kind
                and wait_state.reason_oid == reason_oid
            )
        else:
            outcome = process.outcome
            valid = bool(
                process.wait_state is None
                and isinstance(outcome, KilledProcessOutcome)
                and outcome.reason_oid == reason_oid
                and outcome.code == intent.outcome_code
            )
        if valid:
            intent.stage = 3
        return valid

    def _assert_post_exec_completion_allowed(
        self,
        mutation: Any,
        *,
        process: AgentProcess,
        current: Any,
        expected_revision: int,
    ) -> None:
        current_process = self._row_to_process(current)
        token = current_process_execution_token()
        receipt = self._post_exec_completion_receipt(mutation)
        exact_fence = (
            mutation.target_pid == process.pid
            and mutation.expected_revision == expected_revision
            and mutation.expected_generation == int(current["execution_generation"])
            and mutation.execution_token == token
            and token is not None
            and token.pid == process.pid
            and int(current["execution_generation"]) == token.generation + 1
            and str(current["status"]) == ProcessStatus.RUNNABLE.value
            and current["execution_owner_id"] is None
            and current["execution_lease_id"] is None
            and receipt.get("revision") == expected_revision
            and receipt.get("execution_generation") == mutation.expected_generation
            and receipt.get("prior_execution_generation") == token.generation
            and receipt.get("prior_execution_owner_id") == token.owner_id
            and receipt.get("prior_execution_lease_id") == token.lease_id
        )
        if not exact_fence:
            raise ProcessRevisionConflict(
                f"post-exec completion fence conflict for {process.pid}"
            )
        self._assert_post_exec_tool_result_append(current_process, process)

    def _post_exec_completion_receipt(self, mutation: Any) -> dict[str, Any]:
        publication = self._get_runtime_publication_raw(mutation.publication_id)
        self._assert_post_exec_publication_identity(publication, mutation)
        assert publication is not None
        operation = self.get_operation(mutation.operation_id)
        self._assert_post_exec_operation_identity(operation, publication, mutation)
        phases = list((publication.get("receipt") or {}).get("phases") or [])
        committed = [
            dict(item)
            for item in phases
            if isinstance(item, dict) and item.get("phase") == "committed"
        ]
        if len(committed) != 1:
            raise ProcessRevisionConflict(
                f"post-exec completion receipt conflict for {mutation.target_pid}"
            )
        return committed[0]

    @staticmethod
    def _assert_post_exec_publication_identity(
        publication: dict[str, Any] | None,
        mutation: Any,
    ) -> None:
        if (
            publication is None
            or publication["kind"] != "process_exec"
            or publication["pid"] != mutation.target_pid
            or publication["state"] != "committed"
            or publication["phase"] != "committed"
            or publication["plan"].get("operation_id") != mutation.operation_id
        ):
            raise ProcessRevisionConflict(
                f"post-exec publication fence conflict for {mutation.target_pid}"
            )

    @staticmethod
    def _assert_post_exec_operation_identity(
        operation: Any,
        publication: dict[str, Any],
        mutation: Any,
    ) -> None:
        if (
            operation is None
            or operation.kind.value != "runtime"
            or operation.name != "process.exec"
            or operation.actor != mutation.target_pid
            or operation.pid != mutation.target_pid
            or operation.metadata.get("runtime_publication_id")
            != mutation.publication_id
            or operation.metadata.get("runtime_publication_kind") != "process_exec"
            or operation.metadata.get("runtime_publication_bound") is not True
            or operation.metadata.get("runtime_publication_binding_version") != 1
            or publication["plan"].get("operation_binding_version") != 1
        ):
            raise ProcessRevisionConflict(
                f"post-exec operation fence conflict for {mutation.target_pid}"
            )

    def _assert_post_exec_tool_result_append(
        self,
        current: AgentProcess,
        proposed: AgentProcess,
    ) -> None:
        immutable_fields = (
            "pid", "parent_pid", "image_id", "status", "goal_oid", "memory_view",
            "loaded_skills", "tool_table", "model_tool_table", "event_cursor",
            "checkpoint_head", "status_message", "resource_budget", "resource_usage",
            "wait_state", "outcome", "state_generation", "working_directory",
            "llm_profile_id", "created_at", "revision",
            "execution_generation", "execution_owner_id", "execution_lease_id",
        )
        if any(getattr(current, name) != getattr(proposed, name) for name in immutable_fields):
            raise ProcessRevisionConflict(
                f"post-exec completion may only append a ToolResult handle: {proposed.pid}"
            )
        if (
            proposed.capabilities[:-1] != current.capabilities
            or len(proposed.capabilities) != len(current.capabilities) + 1
        ):
            raise ProcessRevisionConflict(
                f"post-exec completion capability append conflict for {proposed.pid}"
            )
        capability = self.get_capability(proposed.capabilities[-1])
        oid = capability.resource.removeprefix("object:") if capability is not None else ""
        obj = self.get_object(oid) if oid else None
        if (
            capability is None
            or capability.subject != proposed.pid
            or not capability.active
            or not capability.metadata.get("object_handle")
            or capability.issued_by != "memory"
            or not capability.resource.startswith("object:")
            or obj is None
            or obj.type != ObjectType.TOOL_RESULT
            or obj.created_by != proposed.pid
            or obj.owner_kind != ObjectOwnerKind.PROCESS
            or obj.owner_id != proposed.pid
            or obj.provenance.created_from_action != "tool.exec_process"
        ):
            raise ProcessRevisionConflict(
                f"post-exec completion requires its exact ToolResult handle: {proposed.pid}"
            )

    @staticmethod
    def _assert_terminal_mutation_allowed(
        terminal_mutation: Any,
        *,
        process: AgentProcess,
        current: Any,
        expected_revision: int,
    ) -> None:
        current_status = str(current["status"])
        current_generation = int(current["execution_generation"])
        execution_token = current_process_execution_token()
        if terminal_mutation is None:
            raise ProcessRevisionConflict(
                f"terminal process {process.pid} is immutable: {current_status}"
            )
        if (
            terminal_mutation.target_pid != process.pid
            or terminal_mutation.expected_revision != expected_revision
            or terminal_mutation.expected_generation != current_generation
            or current_status not in terminal_mutation.allowed_statuses
            or terminal_mutation.execution_token != execution_token
            or current["execution_owner_id"] is not None
            or current["execution_lease_id"] is not None
        ):
            raise ProcessRevisionConflict(
                f"terminal process mutation fence conflict for {process.pid}"
            )
        if (
            execution_token is not None
            and execution_token.pid == process.pid
            and current_generation != execution_token.generation + 1
        ):
            raise ProcessRevisionConflict(
                f"stale process execution token cannot mutate terminal process {process.pid}"
            )

    @staticmethod
    def _assert_execution_target_allowed(
        execution_token: ProcessExecutionToken | None,
        *,
        target_pid: str,
        current_status: str,
    ) -> None:
        takeover = current_process_execution_takeover_intent()
        if takeover is not None and takeover.target_pid != target_pid:
            raise ProcessRevisionConflict(
                "process execution takeover cannot mutate another process: "
                f"{target_pid}"
            )
        if execution_token is None or execution_token.pid == target_pid:
            return
        control_mutation = current_process_control_mutation()
        if (
            control_mutation is not None
            and control_mutation.target_pid == target_pid
            and current_status in control_mutation.allowed_statuses
        ):
            return
        raise ProcessRevisionConflict(
            "process execution token for "
            f"{execution_token.pid} cannot mutate {target_pid}"
        )

    def patch_process_control(
        self,
        pid: str,
        patch: Mapping[str, Any],
        *,
        expected_revision: int,
        allowed_statuses: Iterable[ProcessStatus | str],
        reason: str,
    ) -> AgentProcess:
        """Apply an explicit Host/control-plane process mutation.

        This is the only compatibility path by which code executing under a
        worker token may intentionally mutate a different PID.  The ordinary
        patch API never silently downgrades a mismatched worker into a Host
        write.
        """

        selected_statuses = frozenset(ProcessStatus(status) for status in allowed_statuses)
        if not selected_statuses:
            raise ValidationError("process control allowed statuses must be non-empty")
        current = self.get_process(pid)
        if current is None:
            raise ProcessRevisionConflict(f"process no longer exists: {pid}")
        if current.revision != int(expected_revision):
            raise ProcessRevisionConflict(
                f"process revision conflict for {pid}: "
                f"expected {expected_revision}, found {current.revision}"
            )
        if current.status not in selected_statuses:
            allowed = ", ".join(sorted(status.value for status in selected_statuses))
            raise ProcessRevisionConflict(
                f"process control status conflict for {pid}: "
                f"expected one of {allowed}, found {current.status.value}"
            )
        with trusted_process_control_mutation(
            pid,
            allowed_statuses=selected_statuses,
            reason=reason,
        ):
            return self.patch_process(
                pid,
                patch,
                expected_revision=expected_revision,
                expected_status=current.status,
            )

    def patch_process(
        self,
        pid: str,
        patch: Mapping[str, Any],
        *,
        expected_revision: int,
        expected_status: ProcessStatus | str | None = None,
    ) -> AgentProcess:
        """Apply a field-level process CAS and return the committed row."""

        allowed = {
            "parent_pid",
            "image_id",
            "goal_oid",
            "memory_view",
            "capabilities",
            "loaded_skills",
            "tool_table",
            "model_tool_table",
            "event_cursor",
            "checkpoint_head",
            "status_message",
            "resource_budget",
            "resource_usage",
            "working_directory",
            "llm_profile_id",
            "updated_at",
        }
        unknown = set(patch) - allowed
        if unknown:
            semantic = unknown & _PROCESS_SEMANTIC_FIELDS
            if semantic:
                raise ValidationError(
                    "process semantic state must use ProcessTransitionService: "
                    f"{', '.join(sorted(semantic))}"
                )
            raise ValidationError(f"unsupported process patch fields: {', '.join(sorted(unknown))}")
        return self._patch_process(
            pid,
            patch,
            expected_revision=expected_revision,
            expected_status=expected_status,
            allow_state_transition=False,
        )

    def _patch_process(
        self,
        pid: str,
        patch: Mapping[str, Any],
        *,
        expected_revision: int,
        expected_status: ProcessStatus | str | None,
        allow_state_transition: bool,
    ) -> AgentProcess:
        with self._lock:
            current = self.get_process(pid)
            if current is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            if current.revision != int(expected_revision):
                raise ProcessRevisionConflict(
                    f"process revision conflict for {pid}: expected {expected_revision}, found {current.revision}"
                )
            if expected_status is not None and current.status != ProcessStatus(expected_status):
                raise ProcessRevisionConflict(
                    f"process status conflict for {pid}: expected {ProcessStatus(expected_status).value}, "
                    f"found {current.status.value}"
                )
            for field_name, value in patch.items():
                if field_name == "status":
                    value = ProcessStatus(value)
                setattr(current, field_name, deepcopy(value))
            if "updated_at" not in patch:
                current.updated_at = utc_now()
            self._update_process(
                current,
                allow_state_transition=allow_state_transition,
            )
            return current

    def apply_process_state_transition(
        self,
        pid: str,
        status: ProcessStatus | str,
        *,
        expected_revision: int,
        expected_status: ProcessStatus | str | None = None,
        expected_state_generation: int | None = None,
        wait_state: ProcessWaitState | None = None,
        outcome: ProcessOutcome | None = None,
        status_message: str | None = None,
        control: bool = False,
        allowed_statuses: Iterable[ProcessStatus | str] | None = None,
        reason: str | None = None,
    ) -> AgentProcess:
        selected_status = ProcessStatus(status)
        validate_process_state_fields(
            selected_status.value,
            wait_state,
            outcome,
        )
        if isinstance(wait_state, StaleExecutionProcessWait):
            raise ValidationError(
                "stale-execution recovery receipts are reserved for Store recovery"
            )
        with self._lock:
            current = self.get_process(pid)
            if current is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            if (
                expected_state_generation is not None
                and current.state_generation != int(expected_state_generation)
            ):
                raise ProcessRevisionConflict(
                    f"process state generation conflict for {pid}: "
                    f"expected {expected_state_generation}, "
                    f"found {current.state_generation}"
                )
            patch = {
                "status": selected_status,
                "wait_state": wait_state,
                "outcome": outcome,
                "state_generation": current.state_generation + 1,
                "status_message": legacy_status_message(
                    wait_state,
                    outcome,
                    status_message,
                ),
            }
            if not control:
                return self._patch_process(
                    pid,
                    patch,
                    expected_revision=expected_revision,
                    expected_status=expected_status,
                    allow_state_transition=True,
                )
            selected_allowed = frozenset(
                ProcessStatus(item) for item in (allowed_statuses or ())
            )
            if not selected_allowed:
                raise ValidationError(
                    "control process transition requires allowed statuses"
                )
            if current.status not in selected_allowed:
                allowed = ", ".join(
                    sorted(item.value for item in selected_allowed)
                )
                raise ProcessRevisionConflict(
                    f"process control status conflict for {pid}: "
                    f"expected one of {allowed}, found {current.status.value}"
                )
            with trusted_process_control_mutation(
                pid,
                allowed_statuses=selected_allowed,
                reason=reason or "semantic process state transition",
            ):
                return self._patch_process(
                    pid,
                    patch,
                    expected_revision=expected_revision,
                    expected_status=current.status,
                    allow_state_transition=True,
                )

    def append_process_memory_roots(
        self,
        pid: str,
        roots: Iterable[ObjectHandle],
    ) -> AgentProcess:
        """Commutatively append roots while holding the store serialization lock."""

        additions = [deepcopy(root) for root in roots]
        with self._lock:
            process = self.get_process(pid)
            if process is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            if process.memory_view is None:
                raise ValidationError(f"process has no memory view: {pid}")
            known = {root.oid for root in process.memory_view.roots}
            process.memory_view.roots.extend(root for root in additions if root.oid not in known)
            process.updated_at = utc_now()
            self.update_process(process)
            return process

    def remove_process_memory_roots(
        self,
        pid: str,
        oids: Iterable[str],
    ) -> AgentProcess:
        """Commutatively remove selected roots while preserving concurrent additions."""

        removals = {str(oid) for oid in oids}
        with self._lock:
            process = self.get_process(pid)
            if process is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            if process.memory_view is None:
                return process
            retained = [root for root in process.memory_view.roots if root.oid not in removals]
            if len(retained) == len(process.memory_view.roots):
                return process
            process.memory_view.roots = retained
            process.updated_at = utc_now()
            self.update_process(process)
            return process

    def append_process_capability_ids(
        self,
        pid: str,
        capability_ids: Iterable[str],
    ) -> AgentProcess:
        """Commutatively attach capability identifiers to a process row."""

        additions = [str(cap_id) for cap_id in capability_ids]
        with self._lock:
            process = self.get_process(pid)
            if process is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            known = set(process.capabilities)
            selected = [cap_id for cap_id in additions if cap_id not in known]
            if not selected:
                return process
            process.capabilities.extend(selected)
            process.updated_at = utc_now()
            self.update_process(process)
            return process

    def patch_process_tool_tables(
        self,
        pid: str,
        *,
        tool_table: Mapping[str, str] | None = None,
        model_tool_table: Mapping[str, str] | None = None,
    ) -> AgentProcess:
        """Commutatively merge tool mappings under the store lock."""

        with self._lock:
            process = self.get_process(pid)
            if process is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            if tool_table:
                process.tool_table.update({str(key): str(value) for key, value in tool_table.items()})
            if model_tool_table:
                process.model_tool_table.update(
                    {str(key): str(value) for key, value in model_tool_table.items()}
                )
            process.updated_at = utc_now()
            self.update_process(process)
            return process

    def remove_process_tool_bindings(
        self,
        pid: str,
        bindings: Mapping[str, str],
    ) -> AgentProcess:
        """Remove only bindings that still point at the supplied tool IDs."""

        expected = {str(name): str(tool_id) for name, tool_id in bindings.items()}
        with self._lock:
            process = self.get_process(pid)
            if process is None:
                raise ProcessRevisionConflict(f"process no longer exists: {pid}")
            changed = False
            for name, tool_id in expected.items():
                if process.tool_table.get(name) == tool_id:
                    process.tool_table.pop(name, None)
                    changed = True
                if process.model_tool_table.get(name) == tool_id:
                    process.model_tool_table.pop(name, None)
                    changed = True
            if not changed:
                return process
            process.updated_at = utc_now()
            self.update_process(process)
            return process

    def replace_process_for_restore(self, process: AgentProcess) -> None:
        """Controlled snapshot-only replacement, deliberately outside normal CAS."""

        with self.transaction() as cur:
            existing = self.get_process(process.pid)
            (
                process.revision,
                process.execution_generation,
                process.state_generation,
            ) = self.reserve_process_restore_epoch(
                process.pid,
                revision_floor=max(
                    int(process.revision),
                    int(existing.revision) if existing is not None else 0,
                ),
                execution_generation_floor=max(
                    int(process.execution_generation),
                    int(existing.execution_generation) if existing is not None else 0,
                ),
                state_generation_floor=max(
                    int(process.state_generation),
                    int(existing.state_generation) if existing is not None else 0,
                ),
                cursor=cur,
            )
            process.execution_owner_id = None
            process.execution_lease_id = None
            if existing is not None:
                cur.execute(
                    """
                    DELETE FROM processes WHERE pid = ?
                    """,
                    (process.pid,),
                )
            self.insert_process(process)

    def restore_process_for_exec(
        self,
        before_row: Mapping[str, Any],
        *,
        expected_revision: int,
        publication_id: str | None = None,
        capability_ids: Iterable[str] | None = None,
        fence_execution: bool = True,
    ) -> bool:
        """Restore only the exact process-exec admission owned by a publication."""

        pid = str(before_row["pid"])
        restored, columns = self._prepare_process_exec_restore(
            before_row,
            capability_ids=capability_ids,
            fence_execution=fence_execution,
        )
        assignments = ", ".join(f"{column} = ?" for column in columns)
        execution_assignment = (
            "execution_generation = execution_generation + 1, "
            "execution_owner_id = NULL, execution_lease_id = NULL"
            if fence_execution
            else "execution_generation = ?, execution_owner_id = ?, execution_lease_id = ?"
        )
        execution_params: tuple[Any, ...] = ()
        if not fence_execution:
            execution_params = (
                int(restored.get("execution_generation") or 0),
                restored.get("execution_owner_id"),
                restored.get("execution_lease_id"),
            )
        with self.transaction() as cur:
            process_fence_clause, process_fence_params = (
                self._process_exec_restore_fence(
                    cur,
                    publication_id=str(publication_id or ""),
                    pid=pid,
                    before_row=before_row,
                    fence_execution=fence_execution,
                )
            )
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET {assignments}, revision = revision + 1,
                       state_generation = state_generation + 1,
                       {execution_assignment}
                 WHERE pid = ? AND revision = ?
                   {process_fence_clause}
                """,
                (
                    *(restored[column] for column in columns),
                    *execution_params,
                    pid,
                    int(expected_revision),
                    *process_fence_params,
                ),
            )
            if updated.rowcount != 1:
                return False
            self._replace_process_tool_bindings(
                cur,
                pid,
                loads(restored["tool_table_json"], {}),
                loads(restored["model_tool_table_json"], {}),
            )
            self._observe_restored_process_concurrency(cur, pid)
            return True

    @staticmethod
    def _prepare_process_exec_restore(
        before_row: Mapping[str, Any],
        *,
        capability_ids: Iterable[str] | None,
        fence_execution: bool,
    ) -> tuple[dict[str, Any], tuple[str, ...]]:
        restored = dict(before_row)
        if fence_execution and restored.get("status") == ProcessStatus.RUNNING.value:
            restored.update(
                status=ProcessStatus.RUNNABLE.value,
                status_message=None,
                wait_state_json="null",
                outcome_json="null",
            )
        if capability_ids is not None:
            restored["capabilities_json"] = dumps(list(dict.fromkeys(capability_ids)))
        return restored, (
            "image_id", "status", "goal_oid", "memory_view_json",
            "capabilities_json", "loaded_skills_json", "tool_table_json",
            "model_tool_table_json", "status_message", "wait_state_json",
            "outcome_json", "working_directory", "llm_profile_id", "updated_at",
        )

    def _process_exec_restore_fence(
        self,
        cur: Any,
        *,
        publication_id: str,
        pid: str,
        before_row: Mapping[str, Any],
        fence_execution: bool,
    ) -> tuple[str, tuple[Any, ...]]:
        if not fence_execution:
            return " AND status NOT IN (?, ?, ?)", (
                ProcessStatus.EXITED.value,
                ProcessStatus.FAILED.value,
                ProcessStatus.KILLED.value,
            )
        token, state_generation = self._process_exec_rollback_admission_fence(
            cur,
            publication_id=publication_id,
            pid=pid,
            before_row=before_row,
        )
        return (
            " AND status = ? AND state_generation = ? "
            "AND execution_generation = ? "
            "AND execution_owner_id = ? AND execution_lease_id = ?",
            (
                ProcessStatus.RUNNING.value,
                state_generation,
                token.generation,
                token.owner_id,
                token.lease_id,
            ),
        )

    def _observe_restored_process_concurrency(self, cur: Any, pid: str) -> None:
        rows = list(
            cur.execute(
                """
                SELECT revision, execution_generation, state_generation
                  FROM processes WHERE pid = ?
                """,
                (pid,),
            )
        )
        self.observe_process_concurrency(
            pid,
            revision=int(rows[0]["revision"]),
            execution_generation=int(rows[0]["execution_generation"]),
            state_generation=int(rows[0]["state_generation"]),
            cursor=cur,
        )

    @staticmethod
    def _process_exec_rollback_admission_fence(
        cur: Any,
        *,
        publication_id: str,
        pid: str,
        before_row: Mapping[str, Any],
    ) -> tuple[ProcessExecutionToken, int]:
        """Authenticate one rollback against its immutable admission plan."""

        plan = SQLRuntimeStore._process_exec_rollback_plan(
            cur,
            publication_id=publication_id,
            pid=pid,
        )
        SQLRuntimeStore._assert_process_exec_rollback_snapshot(
            plan,
            publication_id=publication_id,
            pid=pid,
            before_row=before_row,
        )
        return SQLRuntimeStore._process_exec_rollback_token(
            plan,
            publication_id=publication_id,
            pid=pid,
            before_row=before_row,
        )

    @staticmethod
    def _process_exec_rollback_plan(
        cur: Any,
        *,
        publication_id: str,
        pid: str,
    ) -> Mapping[str, Any]:
        if not publication_id:
            raise ProcessRevisionConflict(
                f"process exec rollback requires its durable publication: {pid}"
            )
        rows = list(
            cur.execute(
                """
                SELECT kind, pid, state, phase, plan_json
                  FROM runtime_publications
                 WHERE publication_id = ?
                """,
                (publication_id,),
            )
        )
        if len(rows) != 1:
            raise ProcessRevisionConflict(
                f"process exec rollback publication is missing: {publication_id}"
            )
        publication = rows[0]
        if (
            publication["kind"] != "process_exec"
            or publication["pid"] != pid
            or publication["state"] != "rollback_pending"
            or publication["phase"] not in {"compensating", "recovery_claimed"}
        ):
            raise ProcessRevisionConflict(
                "process exec rollback publication identity or phase conflict: "
                f"{publication_id}"
            )
        try:
            plan = loads(publication["plan_json"], {})
        except (TypeError, ValueError):
            raise ProcessRevisionConflict(
                f"process exec rollback publication plan is invalid: {publication_id}"
            ) from None
        if not isinstance(plan, Mapping):
            raise ProcessRevisionConflict(
                f"process exec rollback publication plan is invalid: {publication_id}"
            )
        return plan

    @staticmethod
    def _assert_process_exec_rollback_snapshot(
        plan: Mapping[str, Any],
        *,
        publication_id: str,
        pid: str,
        before_row: Mapping[str, Any],
    ) -> None:
        durable_snapshot = (
            plan.get("before_snapshot")
        )
        durable_rows = (
            durable_snapshot.get("rows")
            if isinstance(durable_snapshot, Mapping)
            else None
        )
        durable_processes = (
            durable_rows.get("processes")
            if isinstance(durable_rows, Mapping)
            else None
        )
        if (
            plan.get("pid") != pid
            or not isinstance(durable_processes, list)
            or len(durable_processes) != 1
            or not isinstance(durable_processes[0], Mapping)
            or dict(durable_processes[0]) != dict(before_row)
        ):
            raise ProcessRevisionConflict(
                f"process exec rollback snapshot is invalid: {publication_id}"
            )

    @staticmethod
    def _process_exec_rollback_token(
        plan: Mapping[str, Any],
        *,
        publication_id: str,
        pid: str,
        before_row: Mapping[str, Any],
    ) -> tuple[ProcessExecutionToken, int]:
        generation = plan.get("admission_execution_generation")
        owner_id = plan.get("admission_execution_owner_id")
        lease_id = plan.get("admission_execution_lease_id")
        before_state_generation = before_row.get("state_generation")
        if (
            isinstance(generation, bool)
            or not isinstance(generation, int)
            or generation < 0
            or not isinstance(owner_id, str)
            or not owner_id
            or not isinstance(lease_id, str)
            or not lease_id
            or isinstance(before_state_generation, bool)
            or not isinstance(before_state_generation, int)
            or before_state_generation < 0
        ):
            raise ProcessRevisionConflict(
                f"process exec rollback admission plan is invalid: {publication_id}"
            )
        token = ProcessExecutionToken(
            pid=pid,
            generation=generation,
            owner_id=owner_id,
            lease_id=lease_id,
            task_run_epoch=(
                int(before_row["task_run_epoch"])
                if before_row.get("task_run_epoch") is not None
                else None
            ),
        )
        ambient = current_process_execution_token()
        if ambient is not None and ambient != token:
            raise ProcessRevisionConflict(
                "process exec rollback ambient admission token conflict: "
                f"{publication_id}"
            )
        return token, before_state_generation + 1

    def commit_process_exec_epoch(
        self,
        pid: str,
        *,
        publication_id: str,
        expected_revision: int,
    ) -> AgentProcess:
        """Commit a successful exec admission epoch.

        The helper is designed to run inside the exec publication commit
        transaction under the exact admission execution token recorded by that
        publication.  Admission already rotated the execution generation and
        invalidated the previous image's worker token.  Commit clears the
        internal lease and hands the RUNNING process back to the runnable queue
        without consuming a second execution generation.
        """

        execution_token = current_process_execution_token()
        if execution_token is None:
            raise ProcessRevisionConflict(
                f"process exec epoch commit requires its exact admission token: {pid}"
            )
        now = utc_now()
        with self.transaction() as cur:
            self._assert_process_exec_commit_publication(
                cur,
                publication_id=publication_id,
                pid=pid,
                execution_token=execution_token,
            )
            (
                current_revision,
                worker_clause,
                worker_params,
            ) = self._process_exec_epoch_fence(
                cur,
                pid=pid,
                expected_revision=expected_revision,
                execution_token=execution_token,
            )
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET status = ?, updated_at = ?, revision = revision + 1,
                       status_message = NULL, wait_state_json = 'null',
                       outcome_json = 'null', state_generation = state_generation + 1,
                       execution_owner_id = NULL, execution_lease_id = NULL
                 WHERE pid = ? AND revision = ?{worker_clause}
                """,
                (
                    ProcessStatus.RUNNABLE.value,
                    now,
                    pid,
                    current_revision,
                    *worker_params,
                ),
            )
            if updated.rowcount != 1:
                raise ProcessRevisionConflict(
                    f"process exec epoch conflict for {pid}"
                )
            counters = list(
                cur.execute(
                """
                SELECT revision, execution_generation, state_generation
                  FROM processes WHERE pid = ?
                """,
                    (pid,),
                )
            )
            self.observe_process_concurrency(
                pid,
                revision=int(counters[0]["revision"]),
                execution_generation=int(counters[0]["execution_generation"]),
                state_generation=int(counters[0]["state_generation"]),
                cursor=cur,
            )
        committed = self.get_process(pid)
        if committed is None:
            raise ProcessRevisionConflict(f"process no longer exists: {pid}")
        return committed

    @staticmethod
    def _assert_process_exec_commit_publication(
        cur: Any,
        *,
        publication_id: str,
        pid: str,
        execution_token: ProcessExecutionToken,
    ) -> None:
        rows = list(
            cur.execute(
                """
                SELECT kind, pid, state, phase, plan_json
                  FROM runtime_publications
                 WHERE publication_id = ?
                """,
                (publication_id,),
            )
        )
        if len(rows) != 1:
            raise ProcessRevisionConflict(
                f"process exec commit publication is missing: {publication_id}"
            )
        publication = rows[0]
        if (
            publication["kind"] != "process_exec"
            or publication["pid"] != pid
            or publication["state"] != "applying"
            or publication["phase"] != "skills_configured"
        ):
            raise ProcessRevisionConflict(
                "process exec commit publication identity or phase conflict: "
                f"{publication_id}"
            )
        try:
            plan = loads(publication["plan_json"], {})
        except (TypeError, ValueError):
            raise ProcessRevisionConflict(
                f"process exec commit publication plan is invalid: {publication_id}"
            ) from None
        if not isinstance(plan, Mapping):
            raise ProcessRevisionConflict(
                f"process exec commit publication plan is invalid: {publication_id}"
            )
        generation = plan.get("admission_execution_generation")
        owner_id = plan.get("admission_execution_owner_id")
        lease_id = plan.get("admission_execution_lease_id")
        if (
            isinstance(generation, bool)
            or not isinstance(generation, int)
            or generation < 0
            or not isinstance(owner_id, str)
            or not owner_id
            or not isinstance(lease_id, str)
            or not lease_id
        ):
            raise ProcessRevisionConflict(
                f"process exec commit publication plan is invalid: {publication_id}"
            )
        if (
            execution_token.pid != pid
            or generation != execution_token.generation
            or owner_id != execution_token.owner_id
            or lease_id != execution_token.lease_id
        ):
            raise ProcessRevisionConflict(
                "process exec commit publication admission token conflict: "
                f"{publication_id}"
            )

    @staticmethod
    def _process_exec_epoch_fence(
        cur: Any,
        *,
        pid: str,
        expected_revision: int,
        execution_token: ProcessExecutionToken,
    ) -> tuple[int, str, tuple[Any, ...]]:
        if execution_token.pid != pid:
            raise ProcessRevisionConflict(
                f"process execution token for {execution_token.pid} cannot exec {pid}"
            )
        rows = list(
            cur.execute(
                """
                SELECT status, revision, execution_generation,
                       execution_owner_id, execution_lease_id
                  FROM processes WHERE pid = ?
                """,
                (pid,),
            )
        )
        if not rows:
            raise ProcessRevisionConflict(f"process no longer exists: {pid}")
        row = rows[0]
        current_status = ProcessStatus(str(row["status"]))
        current_revision = int(row["revision"])
        if current_revision != int(expected_revision):
            raise ProcessRevisionConflict(
                f"process revision conflict for {pid}: "
                f"expected {expected_revision}, found {current_revision}"
            )
        if (
            current_status != ProcessStatus.RUNNING
            or int(row["execution_generation"]) != execution_token.generation
            or row["execution_owner_id"] != execution_token.owner_id
            or row["execution_lease_id"] != execution_token.lease_id
        ):
            raise ProcessRevisionConflict(
                f"stale process execution token cannot exec {pid}"
            )
        return (
            current_revision,
            " AND status = ? AND execution_generation = ? "
            "AND execution_owner_id = ? AND execution_lease_id = ?",
            (
                ProcessStatus.RUNNING.value,
                execution_token.generation,
                execution_token.owner_id,
                execution_token.lease_id,
            ),
        )

    def get_process(self, pid: str) -> AgentProcess | None:
        rows = self._query("SELECT * FROM processes WHERE pid = ?", (pid,))
        return self._row_to_process(rows[0]) if rows else None

    def insert_runtime_publication(
        self,
        *,
        publication_id: str,
        kind: RuntimePublicationKind | str,
        pid: str,
        owner_instance_id: str,
        plan: Mapping[str, Any],
        phase: str = "planned",
        _checkpoint_restore_writer_token: object | None = None,
    ) -> dict[str, Any]:
        try:
            selected_kind = parse_runtime_publication_kind(kind)
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        for field_name, value in (
            ("publication_id", publication_id),
            ("pid", pid),
            ("owner_instance_id", owner_instance_id),
            ("phase", phase),
        ):
            if type(value) is not str or not value:
                raise ValidationError(
                    f"runtime publication {field_name} must be non-empty text"
                )
        if not isinstance(plan, Mapping):
            raise ValidationError("runtime publication plan must be a mapping")
        if (
            selected_kind is RuntimePublicationKind.CHECKPOINT_RESTORE
            and _checkpoint_restore_writer_token
            is not self.__checkpoint_restore_writer_token
        ):
            raise ValidationError(
                "checkpoint restore publications require the internal writer"
            )
        now = utc_now()
        self._execute(
            """
            INSERT INTO runtime_publications (
                publication_id, kind, pid, owner_instance_id, state, phase,
                plan_json, receipt_json, error_json, operation_reconciled,
                created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                publication_id,
                selected_kind.value,
                pid,
                owner_instance_id,
                "planning",
                phase,
                dumps(dict(plan)),
                dumps({"phases": [], "artifacts": []}),
                None,
                0,
                now,
                now,
            ),
        )
        publication = self._get_runtime_publication_raw(publication_id)
        assert publication is not None
        return publication

    def get_runtime_publication(self, publication_id: str) -> dict[str, Any] | None:
        publication = self._get_runtime_publication_raw(publication_id)
        if publication is None:
            return None
        publication["receipt"] = redact_initial_goal_recovery_receipt_projection(
            publication["receipt"]
        )
        return publication

    def _get_runtime_publication_raw(
        self,
        publication_id: str,
    ) -> dict[str, Any] | None:
        rows = self._query(
            "SELECT * FROM runtime_publications WHERE publication_id = ?",
            (publication_id,),
        )
        return self._runtime_publication_row(rows[0]) if rows else None

    def list_runtime_publications(
        self,
        *,
        states: Iterable[str] | None = None,
        pid: str | None = None,
    ) -> list[dict[str, Any]]:
        clauses: list[str] = []
        params: list[Any] = []
        try:
            selected_states = [
                parse_runtime_publication_state(state) for state in states or []
            ]
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        if selected_states:
            placeholders = ", ".join("?" for _ in selected_states)
            clauses.append(f"state IN ({placeholders})")
            params.extend(selected_states)
        if pid is not None:
            clauses.append("pid = ?")
            params.append(pid)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = self._query(
            f"SELECT * FROM runtime_publications{where} ORDER BY created_at, publication_id",
            params,
        )
        publications = [self._runtime_publication_row(row) for row in rows]
        for publication in publications:
            publication["receipt"] = redact_initial_goal_recovery_receipt_projection(
                publication["receipt"]
            )
        return publications

    def get_committed_root_spawn_publication(
        self,
        pid: str,
    ) -> dict[str, Any] | None:
        """Resolve the one durable root-spawn launch row without an unbounded scan."""

        if type(pid) is not str or not pid or "\x00" in pid:
            raise ValidationError("root spawn publication pid must be non-empty text")
        rows = self._query(
            "SELECT * FROM runtime_publications "
            "INDEXED BY idx_runtime_publications_pid_kind "
            "WHERE pid = ? AND kind = ? AND state = ? "
            "ORDER BY created_at, publication_id LIMIT 2",
            (pid, RuntimePublicationKind.PROCESS_LAUNCH.value, "committed"),
        )
        if len(rows) > 1:
            raise ValidationError(
                f"multiple committed process launch publications exist for {pid}"
            )
        if not rows:
            return None
        publication = self._runtime_publication_row(rows[0])
        plan = publication["plan"]
        if (
            plan.get("launch_kind") != "spawn"
            or plan.get("pid") != pid
            or plan.get("parent_pid") is not None
        ):
            raise ValidationError(
                f"committed root spawn publication identity changed for {pid}"
            )
        return publication

    @staticmethod
    def _validated_root_spawn_goal_redaction_request(
        publication_id: str,
        *,
        pid: str,
        goal_oid: str,
        expected_payload_sha256: str,
        expected_states: Iterable[str],
    ) -> set[str]:
        for field_name, value in (
            ("publication_id", publication_id),
            ("pid", pid),
            ("goal_oid", goal_oid),
        ):
            if type(value) is not str or not value or "\x00" in value:
                raise ValidationError(
                    f"root spawn initial goal {field_name} must be non-empty text"
                )
        digest_is_valid = (
            type(expected_payload_sha256) is str
            and len(expected_payload_sha256) == 64
            and all(
                character in "0123456789abcdef"
                for character in expected_payload_sha256
            )
        )
        if not digest_is_valid:
            raise ValidationError("root spawn initial goal digest is invalid")
        try:
            selected_states = {
                parse_runtime_publication_state(state) for state in expected_states
            }
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                f"root spawn initial goal redaction states are invalid: {exc}"
            ) from exc
        if not selected_states:
            raise ValidationError(
                "root spawn initial goal redaction requires expected states"
            )
        return selected_states

    @staticmethod
    def _root_spawn_publication_matches_redaction(
        publication: Mapping[str, Any],
        *,
        pid: str,
        expected_states: set[str],
    ) -> bool:
        plan = publication["plan"]
        return (
            publication["kind"] is RuntimePublicationKind.PROCESS_LAUNCH
            and publication["state"] in expected_states
            and publication["pid"] == pid
            and plan.get("launch_kind") == "spawn"
            and plan.get("pid") == pid
            and plan.get("parent_pid") is None
        )

    def _root_spawn_goal_redaction_receipt(
        self,
        publication: Mapping[str, Any],
        *,
        pid: str,
        goal_oid: str,
        expected_payload_sha256: str,
    ) -> tuple[dict[str, Any], bool]:
        receipt = deepcopy(publication["receipt"])
        phases = receipt.get("phases")
        if not isinstance(phases, list):
            raise ValidationError("root spawn publication phases are invalid")
        matches = [
            phase
            for phase in phases
            if isinstance(phase, dict)
            and phase.get("phase") == "goal_created"
            and INITIAL_GOAL_RECOVERY_KEY in phase
        ]
        if len(matches) != 1:
            raise ValidationError(
                "root spawn publication must contain one initial goal envelope"
            )
        phase = matches[0]
        try:
            envelope = decode_initial_goal_recovery_envelope(
                phase[INITIAL_GOAL_RECOVERY_KEY],
                payload_hard_limit_bytes=(
                    self.config.tools.memory_payload_hard_limit_bytes
                ),
            )
        except ValueError as exc:
            raise ValidationError(
                f"invalid root spawn initial goal recovery envelope: {exc}"
            ) from exc
        anchor_matches = (
            phase.get("goal_oid") == goal_oid
            and envelope.pid == pid
            and envelope.goal_oid == goal_oid
            and envelope.payload_sha256 == expected_payload_sha256
        )
        if not anchor_matches:
            raise ValidationError("root spawn initial goal redaction anchor changed")
        if envelope.recoverable:
            phase[INITIAL_GOAL_RECOVERY_KEY] = (
                redact_initial_goal_recovery_envelope(
                    phase[INITIAL_GOAL_RECOVERY_KEY],
                    payload_hard_limit_bytes=(
                        self.config.tools.memory_payload_hard_limit_bytes
                    ),
                )
            )
        return receipt, envelope.recoverable

    def redact_root_spawn_initial_goal(
        self,
        publication_id: str,
        *,
        pid: str,
        goal_oid: str,
        expected_payload_sha256: str,
        expected_states: Iterable[str] = ("committed",),
    ) -> bool:
        """CAS the reversible root launch goal to its hash-only projection."""

        selected_states = self._validated_root_spawn_goal_redaction_request(
            publication_id,
            pid=pid,
            goal_oid=goal_oid,
            expected_payload_sha256=expected_payload_sha256,
            expected_states=expected_states,
        )
        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            if not self._root_spawn_publication_matches_redaction(
                publication,
                pid=pid,
                expected_states=selected_states,
            ):
                return False
            receipt, changed = self._root_spawn_goal_redaction_receipt(
                publication,
                pid=pid,
                goal_oid=goal_oid,
                expected_payload_sha256=expected_payload_sha256,
            )
            if not changed:
                return True
            current_receipt = dumps(publication["receipt"])
            updated = self._execute(
                "UPDATE runtime_publications SET receipt_json = ?, updated_at = ? "
                "WHERE publication_id = ? AND kind = ? AND pid = ? "
                "AND state = ? AND receipt_json = ?",
                (
                    dumps(receipt),
                    utc_now(),
                    publication_id,
                    RuntimePublicationKind.PROCESS_LAUNCH.value,
                    pid,
                    publication["state"],
                    current_receipt,
                ),
            )
            return updated.rowcount == 1

    def query_runtime_publication_operation_reconciliation(
        self,
        *,
        kind: str,
        state: str,
        after: RuntimePublicationCursor | None,
        limit: int,
    ) -> RuntimePublicationPage:
        """Return one indexed page of terminal publications needing repair."""

        try:
            selected_kind = parse_runtime_publication_kind(kind).value
            selected_state = parse_runtime_publication_state(state)
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        terminal_states = {"committed", "rolled_back", "failed", "manual"}
        if selected_state not in terminal_states:
            raise ValidationError(
                f"runtime publication operation reconciliation requires a terminal state: {state}"
            )
        return self._query_runtime_publication_page(
            kind=selected_kind,
            state=selected_state,
            operation_reconciled=False,
            after=after,
            limit=limit,
            purpose="operation-reconciliation",
        )

    def query_runtime_publication_recovery(
        self,
        *,
        kind: str,
        state: str,
        operation_reconciled: bool,
        after: RuntimePublicationCursor | None,
        limit: int,
    ) -> RuntimePublicationPage:
        """Return one indexed page of an exact publication recovery state."""

        try:
            selected_kind = parse_runtime_publication_kind(kind).value
            selected_state = parse_runtime_publication_state(state)
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        recoverable_states = {
            "planning",
            "applying",
            "reconciliation_pending",
            "rollback_pending",
            "failed",
            "manual",
        }
        if selected_state not in recoverable_states:
            raise ValidationError(
                f"runtime publication recovery requires an unresolved state: {state}"
            )
        return self._query_runtime_publication_page(
            kind=selected_kind,
            state=selected_state,
            operation_reconciled=operation_reconciled,
            after=after,
            limit=limit,
            purpose="recovery",
        )

    def _query_runtime_publication_page(
        self,
        *,
        kind: str,
        state: str,
        operation_reconciled: bool,
        after: RuntimePublicationCursor | None,
        limit: int,
        purpose: str,
    ) -> RuntimePublicationPage:
        selected_limit = self._runtime_publication_reconciliation_limit(limit)
        clauses = ["kind = ?", "state = ?"]
        params: list[Any] = [kind, state]
        if purpose == "operation-reconciliation":
            clauses.append("operation_reconciled = 0")
        else:
            clauses.append("operation_reconciled = ?")
            params.append(int(operation_reconciled))
        if after is not None:
            clauses.append("(created_at, publication_id) > (?, ?)")
            params.extend((after.created_at, after.publication_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM runtime_publications "
            f"/* {purpose} */ "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at, publication_id LIMIT ?",
            params,
        )
        records_list = [
            self._runtime_publication_row(row) for row in rows[:selected_limit]
        ]
        for publication in records_list:
            publication["receipt"] = redact_initial_goal_recovery_receipt_projection(
                publication["receipt"]
            )
        records = tuple(records_list)
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = RuntimePublicationCursor(
                last["created_at"],
                last["publication_id"],
            )
        return RuntimePublicationPage(records=records, next_cursor=next_cursor)

    def mark_runtime_publication_operation_reconciled(
        self,
        publication_id: str,
        *,
        expected_kind: str,
        expected_state: str,
        expected_phase: str,
        expected_operation_id: str | None,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        """CAS-mark an exact terminal publication's operation repair complete."""

        terminal_states = {"committed", "rolled_back", "failed", "manual"}
        if expected_state not in terminal_states:
            raise ValidationError(
                "only terminal runtime publications can complete operation reconciliation"
            )
        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            if (
                publication["kind"] == "checkpoint_restore"
                and _checkpoint_restore_writer_token
                is not self.__checkpoint_restore_writer_token
            ):
                raise ValidationError(
                    "checkpoint restore operation reconciliation requires "
                    "the internal writer"
                )
            plan = publication["plan"]
            durable_operation_id = str(plan.get("operation_id") or "")
            selected_operation_id = str(expected_operation_id or "")
            bound_operation_ids = self.list_operation_ids_by_runtime_publication_id(
                publication_id
            )
            binding_matches = (
                durable_operation_id == selected_operation_id
                and (
                    bool(selected_operation_id)
                    == (plan.get("operation_binding_version") == 1)
                )
                and bound_operation_ids
                == ([selected_operation_id] if selected_operation_id else [])
            )
            identity_matches = (
                publication["kind"] == expected_kind
                and publication["state"] == expected_state
                and publication["phase"] == expected_phase
                and binding_matches
            )
            if not identity_matches:
                return False
            if publication["operation_reconciled"]:
                return True
            updated = self._execute(
                "UPDATE runtime_publications SET operation_reconciled = 1, updated_at = ? "
                "WHERE publication_id = ? AND kind = ? AND state = ? AND phase = ? "
                "AND operation_reconciled = 0",
                (
                    utc_now(),
                    publication_id,
                    expected_kind,
                    expected_state,
                    expected_phase,
                ),
            )
            return updated.rowcount == 1

    def query_checkpoint_payload_delivery_attempts(
        self,
        *,
        after: CheckpointPayloadDeliveryAttempt | None,
        limit: int,
    ) -> CheckpointPayloadDeliveryAttemptPage:
        """Return one indexed page of unacknowledged delivery attempts."""

        selected_limit = self._runtime_publication_reconciliation_limit(limit)
        params: list[Any] = []
        cursor_clause = ""
        if after is not None:
            cursor_clause = (
                "AND (started_at COLLATE BINARY, attempt_id COLLATE BINARY) "
                "> (?, ?) "
            )
            params.extend((after.started_at, after.attempt_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT attempt_id, owner_instance_id, started_at "
            "FROM checkpoint_payload_delivery_attempts "
            "INDEXED BY idx_checkpoint_payload_delivery_attempts_state "
            "WHERE state = 'preparing' "
            f"{cursor_clause}"
            "ORDER BY started_at COLLATE BINARY, attempt_id COLLATE BINARY "
            "LIMIT ?",
            params,
        )
        records = tuple(
            CheckpointPayloadDeliveryAttempt(
                started_at=str(row["started_at"]),
                attempt_id=str(row["attempt_id"]),
                owner_instance_id=str(row["owner_instance_id"]),
            )
            for row in rows[:selected_limit]
        )
        next_cursor = records[-1] if len(rows) > selected_limit and records else None
        return CheckpointPayloadDeliveryAttemptPage(
            records=records,
            next_cursor=next_cursor,
        )

    def get_checkpoint_payload_delivery_attempt_state(
        self,
        attempt: CheckpointPayloadDeliveryAttempt,
    ) -> CheckpointPayloadDeliveryAttemptState | None:
        """Read and validate one exact attempt control row through its PK."""

        if not isinstance(attempt, CheckpointPayloadDeliveryAttempt):
            raise ValidationError("checkpoint payload delivery attempt is invalid")
        rows = self._query(
            "SELECT state, acked_at FROM checkpoint_payload_delivery_attempts "
            "WHERE attempt_id = ? AND owner_instance_id = ? AND started_at = ?",
            (
                attempt.attempt_id,
                attempt.owner_instance_id,
                attempt.started_at,
            ),
        )
        if not rows:
            return None
        row = rows[0]
        try:
            state = CheckpointPayloadDeliveryAttemptState(row["state"])
            acked_at = row["acked_at"]
            if state is CheckpointPayloadDeliveryAttemptState.ACKED:
                if not isinstance(acked_at, str) or not acked_at:
                    raise ValueError("acked attempt requires acked_at")
            elif acked_at is not None:
                raise ValueError("open or aborted attempt cannot retain acked_at")
            return state
        except (KeyError, TypeError, ValueError) as exc:
            raise ValidationError(
                f"invalid checkpoint payload delivery attempt state: {exc}"
            ) from exc

    def query_checkpoint_restore_payload_deliveries(
        self,
        *,
        delivery_state: PayloadDeliveryState | str,
        attempt_id: str | None,
        after: RuntimePublicationCursor | None,
        limit: int,
    ) -> RuntimePublicationPage:
        """Return one exact, indexed delivery page for an owner or attempt."""

        if delivery_state not in {"pending", "confirmed", "completed"}:
            raise ValidationError("checkpoint payload delivery state is invalid")
        if attempt_id is None and delivery_state != "pending":
            raise ValidationError(
                "checkpoint payload delivery query requires an attempt"
            )
        selected_limit = self._runtime_publication_reconciliation_limit(limit)
        clauses = [
            "kind = 'checkpoint_restore'",
            "state = 'committed'",
            "phase = 'reconciled'",
            "payload_delivery_state = ?",
        ]
        params: list[Any] = [delivery_state]
        if attempt_id is None:
            index = "idx_runtime_publications_payload_delivery_page"
        else:
            if not isinstance(attempt_id, str) or not attempt_id:
                raise ValidationError("checkpoint payload delivery attempt is invalid")
            index = "idx_runtime_publications_payload_delivery_attempt"
            clauses.append("payload_delivery_attempt_id = ?")
            params.append(attempt_id)
        if after is not None:
            clauses.append(
                "(created_at COLLATE BINARY, publication_id COLLATE BINARY) > (?, ?)"
            )
            params.extend((after.created_at, after.publication_id))
        params.append(selected_limit + 1)
        rows = self._query(
            f"SELECT * FROM runtime_publications INDEXED BY {index} "
            "/* checkpoint-payload-delivery */ "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at COLLATE BINARY, publication_id COLLATE BINARY "
            "LIMIT ?",
            params,
        )
        records = tuple(
            self._runtime_publication_row(row) for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = RuntimePublicationCursor(
                last["created_at"],
                last["publication_id"],
            )
        return RuntimePublicationPage(records=records, next_cursor=next_cursor)

    def begin_checkpoint_payload_delivery_attempt(
        self,
        attempt: CheckpointPayloadDeliveryAttempt,
        *,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        if (
            _checkpoint_restore_writer_token
            is not self.__checkpoint_restore_writer_token
        ):
            raise ValidationError(
                "checkpoint payload delivery attempts require the internal writer"
            )
        if not isinstance(attempt, CheckpointPayloadDeliveryAttempt):
            raise ValidationError("checkpoint payload delivery attempt is invalid")
        with self.transaction() as cursor:
            inserted = cursor.execute(
                "INSERT INTO checkpoint_payload_delivery_attempts ("
                "attempt_id, owner_instance_id, state, started_at, acked_at, updated_at"
                ") VALUES (?, ?, 'preparing', ?, NULL, ?) ON CONFLICT DO NOTHING",
                (
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.started_at,
                    attempt.started_at,
                ),
            )
            if inserted.rowcount != 1:
                return False
            self._require_checkpoint_payload_delivery_attempt_readback(
                cursor,
                attempt,
                expected_state="preparing",
                expected_acked_at=None,
            )
            return True

    def ack_checkpoint_payload_delivery_attempt(
        self,
        attempt: CheckpointPayloadDeliveryAttempt,
        *,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        if (
            _checkpoint_restore_writer_token
            is not self.__checkpoint_restore_writer_token
        ):
            raise ValidationError(
                "checkpoint payload delivery attempts require the internal writer"
            )
        if not isinstance(attempt, CheckpointPayloadDeliveryAttempt):
            raise ValidationError("checkpoint payload delivery attempt is invalid")
        now = utc_now()
        with self.transaction() as cursor:
            updated = cursor.execute(
                "UPDATE checkpoint_payload_delivery_attempts "
                "SET state = 'acked', acked_at = ?, updated_at = ? "
                "WHERE attempt_id = ? AND owner_instance_id = ? "
                "AND state = 'preparing' AND started_at = ? "
                "AND EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? "
                "AND payload_delivery_state = 'completed' "
                "AND owner_instance_id = ? "
                "AND operation_reconciled = 1 LIMIT 1"
                ") AND NOT EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? "
                "AND payload_delivery_state = 'confirmed' LIMIT 1"
                ") AND NOT EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? "
                "AND payload_delivery_state = 'completed' "
                "AND owner_instance_id = ? "
                "AND operation_reconciled = 0 LIMIT 1"
                ") AND NOT EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? "
                "AND payload_delivery_state = 'completed' "
                "AND owner_instance_id < ? LIMIT 1"
                ") AND NOT EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? "
                "AND payload_delivery_state = 'completed' "
                "AND owner_instance_id > ? LIMIT 1"
                ")",
                (
                    now,
                    now,
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.started_at,
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.attempt_id,
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                ),
            )
            if updated.rowcount != 1:
                return False
            self._require_checkpoint_payload_delivery_attempt_readback(
                cursor,
                attempt,
                expected_state="acked",
                expected_acked_at=now,
            )
            return True

    def abort_checkpoint_payload_delivery_attempt(
        self,
        attempt: CheckpointPayloadDeliveryAttempt,
        *,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        if (
            _checkpoint_restore_writer_token
            is not self.__checkpoint_restore_writer_token
        ):
            raise ValidationError(
                "checkpoint payload delivery attempts require the internal writer"
            )
        if not isinstance(attempt, CheckpointPayloadDeliveryAttempt):
            raise ValidationError("checkpoint payload delivery attempt is invalid")
        with self.transaction() as cursor:
            updated = cursor.execute(
                "UPDATE checkpoint_payload_delivery_attempts "
                "SET state = 'aborted', updated_at = ? "
                "WHERE attempt_id = ? AND owner_instance_id = ? "
                "AND state = 'preparing' AND started_at = ? "
                "AND NOT EXISTS ("
                "SELECT 1 FROM runtime_publications "
                "INDEXED BY idx_runtime_publications_payload_delivery_guard "
                "WHERE kind = 'checkpoint_restore' AND state = 'committed' "
                "AND phase = 'reconciled' "
                "AND payload_delivery_attempt_id IS NOT NULL "
                "AND payload_delivery_attempt_id = ? LIMIT 1"
                ")",
                (
                    utc_now(),
                    attempt.attempt_id,
                    attempt.owner_instance_id,
                    attempt.started_at,
                    attempt.attempt_id,
                ),
            )
            if updated.rowcount != 1:
                return False
            self._require_checkpoint_payload_delivery_attempt_readback(
                cursor,
                attempt,
                expected_state="aborted",
                expected_acked_at=None,
            )
            return True

    def _checkpoint_payload_delivery_attempt_row(
        self,
        cursor: Any,
        attempt_id: str,
    ) -> Any | None:
        rows = list(
            cursor.execute(
                "SELECT attempt_id, owner_instance_id, state, started_at, acked_at "
                "FROM checkpoint_payload_delivery_attempts WHERE attempt_id = ?",
                (attempt_id,),
            )
        )
        return rows[0] if rows else None

    def _require_checkpoint_payload_delivery_attempt_readback(
        self,
        cursor: Any,
        attempt: CheckpointPayloadDeliveryAttempt,
        *,
        expected_state: str,
        expected_acked_at: str | None,
    ) -> None:
        row = self._checkpoint_payload_delivery_attempt_row(
            cursor,
            attempt.attempt_id,
        )
        try:
            matches = bool(
                row is not None
                and row["attempt_id"] == attempt.attempt_id
                and row["owner_instance_id"] == attempt.owner_instance_id
                and row["state"] == expected_state
                and row["started_at"] == attempt.started_at
                and row["acked_at"] == expected_acked_at
            )
        except (KeyError, TypeError):
            matches = False
        if not matches:
            raise ValidationError(
                "checkpoint payload delivery attempt readback diverged"
            )

    def _apply_checkpoint_payload_delivery_transition(
        self,
        publication: Mapping[str, Any],
        target: _PayloadDeliveryTransitionTarget,
    ) -> bool:
        control_attempt = target.control_attempt
        requires_attempt = control_attempt is not None
        state_predicate, state_params = _nullable_exact_cas_predicate(
            "payload_delivery_state",
            publication["payload_delivery_state"],
        )
        attempt_predicate, attempt_params = _nullable_exact_cas_predicate(
            "payload_delivery_attempt_id",
            publication["payload_delivery_attempt_id"],
        )
        started_predicate, started_params = _nullable_exact_cas_predicate(
            "payload_delivery_started_at",
            publication["payload_delivery_started_at"],
        )
        updated = self._execute(
            "UPDATE runtime_publications SET receipt_json = ?, "
            "payload_delivery_state = ?, payload_delivery_attempt_id = ?, "
            "payload_delivery_started_at = ?, operation_reconciled = ?, "
            "owner_instance_id = ?, updated_at = ? "
            "WHERE publication_id = ? AND kind = ? AND state = ? "
            "AND phase = ? AND owner_instance_id = ? "
            "AND operation_reconciled = ? AND receipt_json = ? "
            f"AND {state_predicate} "
            f"AND {attempt_predicate} "
            f"AND {started_predicate} "
            "AND (? = 0 OR EXISTS ("
            "SELECT 1 FROM checkpoint_payload_delivery_attempts "
            "WHERE attempt_id = ? AND owner_instance_id = ? "
            "AND started_at = ? AND state = 'preparing'"
            "))",
            (
                dumps(target.receipt),
                target.state,
                target.attempt_id,
                target.started_at,
                int(target.operation_reconciled),
                target.owner_instance_id,
                utc_now(),
                publication["publication_id"],
                "checkpoint_restore",
                "committed",
                "reconciled",
                publication["owner_instance_id"],
                int(publication["operation_reconciled"]),
                dumps(publication["receipt"]),
                *state_params,
                *attempt_params,
                *started_params,
                int(requires_attempt),
                control_attempt.attempt_id if control_attempt is not None else None,
                (
                    control_attempt.owner_instance_id
                    if control_attempt is not None
                    else None
                ),
                control_attempt.started_at if control_attempt is not None else None,
            ),
        )
        return updated.rowcount == 1

    def _require_checkpoint_payload_delivery_readback(
        self,
        publication_id: str,
        target: _PayloadDeliveryTransitionTarget,
    ) -> None:
        readback = self._get_runtime_publication_raw(publication_id)
        if readback is None or (
            readback["payload_delivery_state"] != target.state
            or readback["payload_delivery_attempt_id"] != target.attempt_id
            or readback["payload_delivery_started_at"] != target.started_at
            or readback["receipt"] != target.receipt
            or readback["operation_reconciled"]
            is not target.operation_reconciled
            or readback["owner_instance_id"] != target.owner_instance_id
        ):
            raise ValidationError(
                "checkpoint payload delivery transition readback diverged"
            )

    def transition_checkpoint_restore_payload_delivery(
        self,
        publication_id: str,
        *,
        expected_delivery_state: str | None,
        delivery_state: str,
        expected_attempt: CheckpointPayloadDeliveryAttempt | None = None,
        delivery_attempt: CheckpointPayloadDeliveryAttempt | None = None,
        owner_instance_id: str | None = None,
        recovery_lease_id: str | None = None,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        """CAS the startup delivery handshake for restored volatile payloads."""

        _validate_payload_delivery_transition_request(
            expected_delivery_state=expected_delivery_state,
            delivery_state=delivery_state,
            expected_attempt=expected_attempt,
            delivery_attempt=delivery_attempt,
            owner_instance_id=owner_instance_id,
            recovery_lease_id=recovery_lease_id,
        )
        with self._join_or_begin_transaction():
            if (
                _checkpoint_restore_writer_token
                is not self.__checkpoint_restore_writer_token
            ):
                raise ValidationError(
                    "checkpoint restore payload delivery requires the internal writer"
                )
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            target = _payload_delivery_transition_target(
                publication,
                expected_delivery_state=expected_delivery_state,
                delivery_state=delivery_state,
                expected_attempt=expected_attempt,
                delivery_attempt=delivery_attempt,
                owner_instance_id=owner_instance_id,
                recovery_lease_id=recovery_lease_id,
            )
            if target is None:
                return False
            if not self._apply_checkpoint_payload_delivery_transition(
                publication,
                target,
            ):
                return False
            self._require_checkpoint_payload_delivery_readback(
                publication_id,
                target,
            )
            return True

    def runtime_publication_exists_for_pid(self, pid: str, *, kind: str) -> bool:
        if not isinstance(pid, str) or not pid:
            raise ValidationError("runtime publication PID must not be empty")
        try:
            selected_kind = parse_runtime_publication_kind(kind).value
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        return bool(
            self._query(
                "SELECT 1 AS present FROM runtime_publications "
                "WHERE pid = ? AND kind = ? LIMIT 1",
                (pid, selected_kind),
            )
        )

    def claim_runtime_publication_recovery(
        self,
        publication_id: str,
        *,
        claimant_instance_id: str,
        expected_owner_instance_id: str,
        expected_state: str,
        classification: str,
        max_attempts: int | None = None,
        allow_orphaned_claim_takeover: bool = False,
        claimed_state: str = "rollback_pending",
        _checkpoint_restore_writer_token: object | None = None,
    ) -> dict[str, Any] | None:
        """CAS-claim one incomplete publication and persist its attempt class.

        Callers must use the owner/state read by their recovery scan. A stale
        scanner therefore cannot steal a claim after another runtime wins;
        after a real restart, the newly observed owner becomes the next fenced
        expectation and the durable attempt counter advances.
        """

        if expected_state not in {
            "planning",
            "applying",
            "reconciliation_pending",
            "rollback_pending",
            "failed",
        }:
            return None
        if claimed_state not in {"reconciliation_pending", "rollback_pending"}:
            return None
        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return None
            if (
                publication["kind"] == "checkpoint_restore"
                and _checkpoint_restore_writer_token
                is not self.__checkpoint_restore_writer_token
            ):
                raise ValidationError(
                    "checkpoint restore recovery claims require the internal writer"
                )
            if publication["kind"] == "checkpoint_restore":
                self._validate_checkpoint_restore_recovery_claim(
                    publication,
                    expected_state=expected_state,
                    classification=classification,
                    claimed_state=claimed_state,
                )
            if (
                publication["owner_instance_id"] != str(expected_owner_instance_id)
                or publication["state"] != str(expected_state)
            ):
                return None
            existing_claim = self._existing_publication_recovery_claim_action(
                publication,
                claimed_state=claimed_state,
                claimant_instance_id=claimant_instance_id,
                allow_orphaned_claim_takeover=allow_orphaned_claim_takeover,
            )
            if existing_claim == "resume":
                return publication
            if existing_claim == "reject":
                return None
            receipt = deepcopy(publication["receipt"])
            phases = receipt.setdefault("phases", [])
            if not isinstance(phases, list):
                raise ValidationError("runtime publication receipt phases must be a list")
            attempt = 1 + sum(
                1
                for phase in phases
                if isinstance(phase, dict) and phase.get("phase") == "recovery_claimed"
            )
            lease_id = new_id("publication_recovery")
            recovery = {
                "attempt": attempt,
                "classification": str(classification),
                "claimant_instance_id": str(claimant_instance_id),
                "lease_id": lease_id,
                "disposition": "retryable",
            }
            phases.append(
                {
                    "phase": "recovery_claimed",
                    **recovery,
                }
            )
            receipt["recovery"] = recovery
            exhausted = max_attempts is not None and attempt > int(max_attempts)
            selected_state = "manual" if exhausted else claimed_state
            selected_phase = (
                "recovery_attempts_exhausted" if exhausted else "recovery_claimed"
            )
            if exhausted:
                recovery["disposition"] = "manual"
                phases[-1]["disposition"] = "manual"
            cur = self._execute(
                """
                UPDATE runtime_publications
                   SET owner_instance_id = ?, state = ?, phase = ?, receipt_json = ?,
                       error_json = NULL, operation_reconciled = 0, updated_at = ?
                 WHERE publication_id = ? AND owner_instance_id = ? AND state = ?
                """,
                (
                    str(claimant_instance_id),
                    selected_state,
                    selected_phase,
                    dumps(receipt),
                    utc_now(),
                    publication_id,
                    str(expected_owner_instance_id),
                    str(expected_state),
                ),
            )
            if cur.rowcount != 1:
                return None
            return self.get_runtime_publication(publication_id)

    @classmethod
    def _validate_checkpoint_restore_recovery_claim(
        cls,
        publication: Mapping[str, Any],
        *,
        expected_state: str,
        classification: str,
        claimed_state: str,
    ) -> None:
        cls._checkpoint_restore_transcript(publication)
        if (
            publication["state"] not in {"reconciliation_pending", "failed"}
            or expected_state != publication["state"]
            or classification != "reconcile_checkpoint_restore"
            or claimed_state != "reconciliation_pending"
        ):
            raise ValidationError(
                "invalid checkpoint restore publication recovery claim"
            )

    @staticmethod
    def _existing_publication_recovery_claim_action(
        publication: Mapping[str, Any],
        *,
        claimed_state: str,
        claimant_instance_id: str,
        allow_orphaned_claim_takeover: bool,
    ) -> str:
        recovery = publication["receipt"].get("recovery")
        is_retryable_claim = (
            publication["state"] == claimed_state
            and publication["phase"] == "recovery_claimed"
            and isinstance(recovery, dict)
            and recovery.get("disposition") == "retryable"
        )
        if not is_retryable_claim:
            return "new"
        if recovery.get("claimant_instance_id") == str(claimant_instance_id):
            # Same-runtime retries resume the exact lease without consuming a
            # new durable attempt.
            return "resume"
        # Startup callers hold the backend-wide runtime lease and may opt into
        # taking over a claim orphaned by another Runtime instance.
        return "takeover" if allow_orphaned_claim_takeover else "reject"

    def advance_runtime_publication(
        self,
        publication_id: str,
        *,
        state: str,
        phase: str,
        receipt: Mapping[str, Any] | None = None,
        error: Mapping[str, Any] | None = None,
        expected_states: Iterable[str] | None = None,
        expected_phase: str | None = None,
        recovery_lease_id: str | None = None,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        """Advance a publication with an optional state CAS predicate.

        ``None`` disables the state predicate.  A supplied but empty iterable
        matches no state and therefore rejects the mutation.
        """

        allowed_states = {
            "planning",
            "applying",
            "reconciliation_pending",
            "committed",
            "rollback_pending",
            "rolled_back",
            "failed",
            "manual",
        }
        if state not in allowed_states:
            raise ValidationError(f"invalid runtime publication state: {state}")
        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            if publication["kind"] == "checkpoint_restore":
                if (
                    _checkpoint_restore_writer_token
                    is not self.__checkpoint_restore_writer_token
                ):
                    raise ValidationError(
                        "checkpoint restore publication transitions require "
                        "the internal writer"
                    )
            if expected_states is not None:
                expected = set(expected_states)
                if publication["state"] not in expected:
                    return False
            if publication["kind"] == "checkpoint_restore":
                self._validate_checkpoint_restore_publication_advance(
                    publication,
                    state=state,
                    phase=phase,
                    receipt=receipt,
                    error=error,
                    recovery_lease_id=recovery_lease_id,
                )
            if expected_phase is not None and publication["phase"] != expected_phase:
                return False
            merged_receipt = deepcopy(publication["receipt"])
            if not self._advance_publication_recovery_disposition(
                merged_receipt,
                state=state,
                recovery_lease_id=recovery_lease_id,
            ):
                return False
            if receipt:
                phase_receipts = merged_receipt.setdefault("phases", [])
                if not isinstance(phase_receipts, list):
                    raise ValidationError("runtime publication receipt phases must be a list")
                phase_receipts.append(deepcopy(dict(receipt)))
            selected_error = (
                deepcopy(publication["error"])
                if error is None
                else deepcopy(dict(error))
            )
            phase_clause = " AND phase = ?" if expected_phase is not None else ""
            params: list[Any] = [
                state,
                phase,
                dumps(merged_receipt),
                dumps(selected_error) if selected_error is not None else None,
                utc_now(),
                publication_id,
                publication["state"],
            ]
            if expected_phase is not None:
                params.append(expected_phase)
            cur = self._execute(
                f"""
                UPDATE runtime_publications
                   SET state = ?, phase = ?, receipt_json = ?, error_json = ?,
                       operation_reconciled = 0, updated_at = ?
                 WHERE publication_id = ? AND state = ?{phase_clause}
                """,
                params,
            )
            return cur.rowcount == 1

    @classmethod
    def _validate_checkpoint_restore_publication_advance(
        cls,
        publication: Mapping[str, Any],
        *,
        state: str,
        phase: str,
        receipt: Mapping[str, Any] | None,
        error: Mapping[str, Any] | None,
        recovery_lease_id: str | None,
    ) -> None:
        """Validate the checkpoint transcript before its CAS write."""

        current_state = str(publication["state"])
        selected_receipt = dict(receipt or {})
        phase_order, completed_phases, planned_work_ids, completed_work_ids = (
            cls._checkpoint_restore_transcript(publication)
        )
        if selected_receipt == {"phase": "main_state_committed"}:
            valid = cls._is_checkpoint_restore_main_commit(
                publication,
                state=state,
                phase=phase,
                error=error,
                completed_phases=completed_phases,
                completed_work_ids=completed_work_ids,
            )
        elif selected_receipt.get("phase") == "checkpoint_restore_finalizer_completed":
            valid = cls._is_checkpoint_restore_finalizer_completion(
                selected_receipt,
                current_state=current_state,
                state=state,
                phase=phase,
                error=error,
                phase_order=phase_order,
                completed_phases=completed_phases,
                planned_work_ids=planned_work_ids,
                completed_work_ids=completed_work_ids,
            )
        elif selected_receipt.get("phase") == "checkpoint_restore_phase_completed":
            valid = cls._is_checkpoint_restore_phase_completion(
                selected_receipt,
                current_state=current_state,
                state=state,
                phase=phase,
                error=error,
                phase_order=phase_order,
                completed_phases=completed_phases,
                planned_work_ids=planned_work_ids,
                completed_work_ids=completed_work_ids,
            )
        elif selected_receipt == {"phase": "reconciled"}:
            valid = cls._is_checkpoint_restore_finish(
                current_state=current_state,
                state=state,
                phase=phase,
                error=error,
                phase_order=phase_order,
                completed_phases=completed_phases,
                planned_work_ids=planned_work_ids,
                completed_work_ids=completed_work_ids,
            )
        else:
            valid = cls._is_checkpoint_restore_failure(
                selected_receipt,
                publication=publication,
                current_state=current_state,
                state=state,
                phase=phase,
                error=error,
                recovery_lease_id=recovery_lease_id,
                phase_order=phase_order,
                completed_phases=completed_phases,
            )
        if not valid:
            raise ValidationError(
                "invalid checkpoint restore publication transition: "
                f"{current_state}/{publication['phase']} -> {state}/{phase}"
            )

    @classmethod
    def _checkpoint_restore_transcript(
        cls,
        publication: Mapping[str, Any],
    ) -> tuple[list[str], list[str], list[str], list[str]]:
        phases = publication["receipt"].get("phases")
        if not isinstance(phases, list):
            raise ValidationError("checkpoint restore receipt phases are invalid")
        plan_version = publication["plan"].get("plan_version")
        phase_order = {
            1: [
                "image_reconciliation",
                "jit_source_reconciliation",
                "jit_pruning",
                "object_release_finalizers",
            ],
            2: [
                "object_payload_reconciliation",
                "image_reconciliation",
                "jit_source_reconciliation",
                "jit_pruning",
                "object_release_finalizers",
            ],
        }.get(plan_version)
        if (
            type(plan_version) is not int
            or phase_order is None
            or publication["plan"].get("phase_order") != phase_order
        ):
            raise ValidationError(
                "checkpoint restore publication plan program is invalid"
            )
        completed_phases = cls._checkpoint_restore_phase_markers(phases)
        if completed_phases != phase_order[: len(completed_phases)]:
            raise ValidationError(
                "checkpoint restore phase transcript is out of order"
            )
        planned_work_ids = cls._checkpoint_restore_planned_work_ids(
            publication["plan"]
        )
        cls._validate_checkpoint_restore_causal_transcript(
            publication,
            phases,
            phase_order=phase_order,
            planned_work_ids=planned_work_ids,
        )
        completed_work_ids = cls._checkpoint_restore_work_markers(phases)
        if completed_work_ids != planned_work_ids[: len(completed_work_ids)]:
            raise ValidationError(
                "checkpoint restore finalizer transcript is out of order"
            )
        return phase_order, completed_phases, planned_work_ids, completed_work_ids

    @staticmethod
    def _validate_checkpoint_restore_causal_transcript(
        publication: Mapping[str, Any],
        phases: list[Any],
        *,
        phase_order: list[str],
        planned_work_ids: list[str],
    ) -> None:
        program: list[dict[str, Any]] = [{"phase": "main_state_committed"}]
        program.extend(
            {
                "phase": "checkpoint_restore_phase_completed",
                "name": name,
            }
            for name in phase_order[:-1]
        )
        program.extend(
            {
                "phase": "checkpoint_restore_finalizer_completed",
                "work_id": work_id,
            }
            for work_id in planned_work_ids
        )
        program.append(
            {
                "phase": "checkpoint_restore_phase_completed",
                "name": phase_order[-1],
            }
        )
        program.append({"phase": "reconciled"})
        causal = [
            item
            for item in phases
            if not isinstance(item, dict) or item.get("phase") != "recovery_claimed"
        ]
        if causal != program[: len(causal)]:
            raise ValidationError("checkpoint restore causal transcript is invalid")
        state = str(publication["state"])
        invalid_state_shape = (
            (state == "planning" and bool(causal))
            or (state != "planning" and not causal)
            or (state == "committed" and causal != program)
            or (state != "committed" and causal == program)
        )
        if invalid_state_shape:
            raise ValidationError(
                "checkpoint restore state does not match its causal transcript"
            )
        SQLRuntimeStore._validate_checkpoint_restore_recovery_markers(phases)

    @staticmethod
    def _validate_checkpoint_restore_recovery_markers(phases: list[Any]) -> None:
        expected_attempt = 1
        main_seen = False
        for item in phases:
            if not isinstance(item, dict):
                raise ValidationError("checkpoint restore receipt marker is invalid")
            if item == {"phase": "main_state_committed"}:
                main_seen = True
                continue
            if item.get("phase") != "recovery_claimed":
                continue
            valid = (
                main_seen
                and set(item)
                == {
                    "phase",
                    "attempt",
                    "classification",
                    "claimant_instance_id",
                    "lease_id",
                    "disposition",
                }
                and item.get("attempt") == expected_attempt
                and item.get("classification") == "reconcile_checkpoint_restore"
                and bool(str(item.get("claimant_instance_id") or ""))
                and bool(str(item.get("lease_id") or ""))
                and item.get("disposition") in {"retryable", "manual"}
            )
            if not valid:
                raise ValidationError(
                    "checkpoint restore recovery transcript is invalid"
                )
            expected_attempt += 1

    @staticmethod
    def _checkpoint_restore_phase_markers(
        phases: list[Any],
    ) -> list[str]:
        return [
            str(item.get("name") or "")
            for item in phases
            if isinstance(item, dict)
            and item.get("phase") == "checkpoint_restore_phase_completed"
        ]

    @staticmethod
    def _checkpoint_restore_planned_work_ids(plan: Mapping[str, Any]) -> list[str]:
        work_items = plan.get("finalizer_work_items")
        if not isinstance(work_items, list):
            raise ValidationError("checkpoint restore finalizer plan is invalid")
        planned_work_ids = [
            str(item.get("work_id") or "")
            for item in work_items
            if isinstance(item, dict)
        ]
        if len(planned_work_ids) != len(work_items) or any(
            not work_id for work_id in planned_work_ids
        ):
            raise ValidationError("checkpoint restore finalizer plan is invalid")
        return planned_work_ids

    @staticmethod
    def _checkpoint_restore_work_markers(phases: list[Any]) -> list[str]:
        return [
            str(item.get("work_id") or "")
            for item in phases
            if isinstance(item, dict)
            and item.get("phase") == "checkpoint_restore_finalizer_completed"
        ]

    @staticmethod
    def _is_checkpoint_restore_main_commit(
        publication: Mapping[str, Any],
        *,
        state: str,
        phase: str,
        error: Mapping[str, Any] | None,
        completed_phases: list[str],
        completed_work_ids: list[str],
    ) -> bool:
        return (
            publication["state"] == "planning"
            and publication["phase"] == "planned"
            and state == "reconciliation_pending"
            and phase == "main_state_committed"
            and error is None
            and not completed_phases
            and not completed_work_ids
        )

    @staticmethod
    def _is_checkpoint_restore_finalizer_completion(
        receipt: Mapping[str, Any],
        *,
        current_state: str,
        state: str,
        phase: str,
        error: Mapping[str, Any] | None,
        phase_order: list[str],
        completed_phases: list[str],
        planned_work_ids: list[str],
        completed_work_ids: list[str],
    ) -> bool:
        work_id = str(receipt.get("work_id") or "")
        return (
            set(receipt) == {"phase", "work_id"}
            and current_state == "reconciliation_pending"
            and state == "reconciliation_pending"
            and phase == "object_release_finalizers"
            and len(completed_phases) == len(phase_order) - 1
            and len(completed_work_ids) < len(planned_work_ids)
            and work_id == planned_work_ids[len(completed_work_ids)]
            and error is None
        )

    @staticmethod
    def _is_checkpoint_restore_phase_completion(
        receipt: Mapping[str, Any],
        *,
        current_state: str,
        state: str,
        phase: str,
        error: Mapping[str, Any] | None,
        phase_order: list[str],
        completed_phases: list[str],
        planned_work_ids: list[str],
        completed_work_ids: list[str],
    ) -> bool:
        name = str(receipt.get("name") or "")
        next_index = len(completed_phases)
        finalizer_ready = (
            name != "object_release_finalizers"
            or completed_work_ids == planned_work_ids
        )
        return (
            set(receipt) == {"phase", "name"}
            and current_state == "reconciliation_pending"
            and state == "reconciliation_pending"
            and next_index < len(phase_order)
            and name == phase_order[next_index]
            and phase == f"{name}_completed"
            and error is None
            and finalizer_ready
        )

    @staticmethod
    def _is_checkpoint_restore_finish(
        *,
        current_state: str,
        state: str,
        phase: str,
        error: Mapping[str, Any] | None,
        phase_order: list[str],
        completed_phases: list[str],
        planned_work_ids: list[str],
        completed_work_ids: list[str],
    ) -> bool:
        return (
            current_state == "reconciliation_pending"
            and state == "committed"
            and phase == "reconciled"
            and completed_phases == phase_order
            and completed_work_ids == planned_work_ids
            and error is None
        )

    @staticmethod
    def _is_checkpoint_restore_failure(
        receipt: Mapping[str, Any],
        *,
        publication: Mapping[str, Any],
        current_state: str,
        state: str,
        phase: str,
        error: Mapping[str, Any] | None,
        recovery_lease_id: str | None,
        phase_order: list[str],
        completed_phases: list[str],
    ) -> bool:
        if (
            not receipt
            and current_state == "reconciliation_pending"
            and isinstance(error, Mapping)
            and set(error) == {"code", "error_type"}
            and error.get("code") == "checkpoint_restore_reconciliation_failed"
            and bool(str(error.get("error_type") or ""))
        ):
            recovery = publication["receipt"].get("recovery")
            active_recovery = (
                isinstance(recovery, dict)
                and recovery.get("disposition") == "retryable"
            )
            next_phase = (
                phase_order[len(completed_phases)]
                if len(completed_phases) < len(phase_order)
                else "terminalization"
            )
            if active_recovery:
                exact_lease = str(recovery.get("lease_id") or "") == str(
                    recovery_lease_id or ""
                )
                expected_phase = "startup_reconciliation_failed"
            else:
                exact_lease = recovery_lease_id is None
                expected_phase = f"{next_phase}_failed"
            durable_finalizer_failure = (
                state == "manual"
                and next_phase == "object_release_finalizers"
                and phase == "durable_finalizer_handler_unavailable"
                and error.get("error_type")
                == "DurableObjectFinalizerUnavailable"
            )
            ordinary_failure = state == "failed" and phase == expected_phase
            return exact_lease and (ordinary_failure or durable_finalizer_failure)
        return False

    @staticmethod
    def _advance_publication_recovery_disposition(
        receipt: dict[str, Any],
        *,
        state: str,
        recovery_lease_id: str | None,
    ) -> bool:
        recovery = receipt.get("recovery")
        if not isinstance(recovery, dict):
            return True
        if (
            recovery.get("disposition") == "retryable"
            and str(recovery.get("lease_id") or "")
            != str(recovery_lease_id or "")
        ):
            return False
        disposition = {
            "committed": "terminal",
            "rolled_back": "terminal",
            "failed": "retryable",
            "manual": "manual",
        }.get(state)
        if disposition is not None:
            recovery["disposition"] = disposition
        return True

    def update_runtime_publication_plan(
        self,
        publication_id: str,
        update: Mapping[str, Any],
        *,
        expected_states: Iterable[str] | None = None,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        """Durably add the exact launch boot inputs before their effects.

        Process-exec and checkpoint-restore plans are complete when inserted
        and therefore immutable.  A no-op write remains supported so callers
        can deliberately dirty and revalidate the operation marker.

        ``None`` disables the state predicate.  A supplied but empty iterable
        matches no state and therefore rejects the mutation.
        """

        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            if (
                publication["kind"] == "checkpoint_restore"
                and _checkpoint_restore_writer_token
                is not self.__checkpoint_restore_writer_token
            ):
                raise ValidationError(
                    "checkpoint restore plan updates require the internal writer"
                )
            if expected_states is not None:
                expected = set(expected_states)
                if publication["state"] not in expected:
                    return False
            plan = deepcopy(publication["plan"])
            if plan.get("operation_binding_version") == 1 and (
                (
                    "operation_id" in update
                    and str(update["operation_id"] or "")
                    != str(plan.get("operation_id") or "")
                )
                or (
                    "operation_binding_version" in update
                    and update["operation_binding_version"] != 1
                )
            ):
                return False
            selected_update = deepcopy(dict(update))
            updated_plan = deepcopy(plan)
            updated_plan.update(selected_update)
            if updated_plan != plan:
                if (
                    publication["kind"] != "process_launch"
                    or publication["state"] not in {"planning", "applying"}
                    or set(selected_update)
                    != {"boot_kind", "materialized_workspace_root"}
                ):
                    return False
            cur = self._execute(
                """
                UPDATE runtime_publications
                   SET plan_json = ?, operation_reconciled = 0, updated_at = ?
                 WHERE publication_id = ? AND state = ?
                """,
                (
                    dumps(updated_plan),
                    utc_now(),
                    publication_id,
                    publication["state"],
                ),
            )
            return cur.rowcount == 1

    def record_runtime_publication_artifact(
        self,
        publication_id: str,
        artifact: Mapping[str, Any],
        *,
        expected_states: Iterable[str] | None = None,
        _checkpoint_restore_writer_token: object | None = None,
    ) -> bool:
        """Append one exact, idempotent compensation receipt.

        ``None`` disables the state predicate.  A supplied but empty iterable
        matches no state and therefore rejects the mutation.
        """

        selected = deepcopy(dict(artifact))
        artifact_id = str(selected.get("artifact_id") or "").strip()
        if not artifact_id:
            raise ValidationError("runtime publication artifact requires artifact_id")
        selected["artifact_id"] = artifact_id
        with self._lock:
            publication = self._get_runtime_publication_raw(publication_id)
            if publication is None:
                return False
            if (
                publication["kind"] == "checkpoint_restore"
                and _checkpoint_restore_writer_token
                is not self.__checkpoint_restore_writer_token
            ):
                raise ValidationError(
                    "checkpoint restore artifacts require the internal writer"
                )
            if expected_states is not None:
                expected = set(expected_states)
                if publication["state"] not in expected:
                    return False
            if publication["kind"] == "checkpoint_restore":
                self._validate_checkpoint_restore_plan_anchor(
                    publication,
                    selected,
                )
            receipt = deepcopy(publication["receipt"])
            artifacts = receipt.setdefault("artifacts", [])
            if not isinstance(artifacts, list):
                raise ValidationError("runtime publication receipt artifacts must be a list")
            for current in artifacts:
                if isinstance(current, dict) and current.get("artifact_id") == artifact_id:
                    if current != selected:
                        raise ValidationError(
                            f"runtime publication artifact receipt changed: {artifact_id}"
                        )
                    return True
            artifacts.append(selected)
            cur = self._execute(
                """
                UPDATE runtime_publications
                   SET receipt_json = ?, updated_at = ?
                 WHERE publication_id = ? AND state = ?
                """,
                (
                    dumps(receipt),
                    utc_now(),
                    publication_id,
                    publication["state"],
                ),
            )
            return cur.rowcount == 1

    @staticmethod
    def _validate_checkpoint_restore_plan_anchor(
        publication: Mapping[str, Any],
        artifact: Mapping[str, Any],
    ) -> None:
        publication_id = str(publication["publication_id"])
        plan_version = publication["plan"].get("plan_version")
        if type(plan_version) is not int or plan_version not in {1, 2}:
            raise ValidationError(
                "invalid checkpoint restore publication plan anchor version"
            )
        expected = {
            "artifact_id": (
                f"{publication_id}:checkpoint_restore_plan:v{plan_version}"
            ),
            "artifact_type": "checkpoint_restore_plan_anchor",
            "anchor_version": plan_version,
            "plan_sha256": hashlib.sha256(
                dumps(dict(publication["plan"])).encode("utf-8")
            ).hexdigest(),
        }
        artifacts = publication["receipt"].get("artifacts")
        valid_existing = artifacts in ([], [expected])
        if (
            publication["state"] != "planning"
            or publication["phase"] != "planned"
            or not valid_existing
            or dict(artifact) != expected
        ):
            raise ValidationError(
                "invalid checkpoint restore publication plan anchor"
            )

    @staticmethod
    def _runtime_publication_row(row: Any) -> dict[str, Any]:
        operation_reconciled = row["operation_reconciled"]
        if type(operation_reconciled) not in {int, bool} or operation_reconciled not in {
            0,
            1,
            False,
            True,
        }:
            raise ValidationError(
                "runtime publication operation_reconciled must be stored as 0 or 1"
            )
        publication_id = row["publication_id"]
        try:
            return validate_runtime_publication_record(
                {
                    "publication_id": publication_id,
                    "kind": row["kind"],
                    "pid": row["pid"],
                    "owner_instance_id": row["owner_instance_id"],
                    "state": row["state"],
                    "phase": row["phase"],
                    "plan": loads(row["plan_json"], {}),
                    "receipt": loads(row["receipt_json"], {}),
                    "error": (
                        loads(row["error_json"]) if row["error_json"] else None
                    ),
                    "operation_reconciled": bool(operation_reconciled),
                    "payload_delivery_state": row["payload_delivery_state"],
                    "payload_delivery_attempt_id": row[
                        "payload_delivery_attempt_id"
                    ],
                    "payload_delivery_started_at": row[
                        "payload_delivery_started_at"
                    ],
                    "created_at": row["created_at"],
                    "updated_at": row["updated_at"],
                }
            )
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                f"invalid persisted runtime publication {publication_id!r}: {exc}"
            ) from exc

    def list_processes(self, limit: int | None = None, *, active_first: bool = False) -> list[AgentProcess]:
        params: list[Any] = []
        sql = "SELECT * FROM processes"
        if active_first:
            sql += " ORDER BY CASE WHEN status IN (?, ?, ?) THEN 1 ELSE 0 END, updated_at DESC, pid DESC"
            params.extend(
                [
                    ProcessStatus.EXITED.value,
                    ProcessStatus.FAILED.value,
                    ProcessStatus.KILLED.value,
                ]
            )
        else:
            sql += " ORDER BY created_at, pid"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(max(0, int(limit)))
        return [self._row_to_process(row) for row in self._query(sql, params)]

    def query_processes(
        self,
        *,
        after: ProcessCursor | None,
        limit: int,
    ) -> ProcessPage:
        """Return one stable, hard-bounded process page for startup scans."""

        selected_limit = _validated_jit_rehydration_limit(self.config, limit)
        clauses: list[str] = []
        params: list[Any] = []
        if after is not None:
            if not isinstance(after, ProcessCursor):
                raise ValidationError("process page cursor has an invalid type")
            clauses.append("(created_at, pid) > (?, ?)")
            params.extend((after.created_at, after.pid))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(selected_limit + 1)
        rows = self._query(
            f"SELECT * FROM processes{where} "
            "ORDER BY created_at, pid LIMIT ?",
            params,
        )
        records = tuple(self._row_to_process(row) for row in rows[:selected_limit])
        next_cursor = None
        if len(rows) > selected_limit:
            last = records[-1]
            next_cursor = ProcessCursor(last.created_at, last.pid)
        return ProcessPage(records=records, next_cursor=next_cursor)

    def query_process_tool_bindings(
        self,
        *,
        after: ProcessToolBindingCursor | None,
        limit: int,
    ) -> ProcessToolBindingPage:
        """Read one global, hard-bounded page of durable JIT bindings."""

        selected_limit = _validated_jit_rehydration_limit(self.config, limit)
        clauses = ["binding.jit_rehydration_eligible = 1"]
        params: list[Any] = []
        if after is not None:
            if not isinstance(after, ProcessToolBindingCursor):
                raise ValidationError("process tool binding cursor has an invalid type")
            clauses.append("(binding.pid, binding.tool_name) > (?, ?)")
            params.extend((after.pid, after.tool_name))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT binding.pid, binding.tool_name, binding.tool_id "
            "FROM process_tool_bindings AS binding "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY binding.pid, binding.tool_name LIMIT ?",
            params,
        )
        selected_rows = rows[:selected_limit]
        records = tuple(
            ProcessToolBindingRecord(
                pid=str(row["pid"]),
                tool_name=str(row["tool_name"]),
                tool_id=str(row["tool_id"]),
            )
            for row in selected_rows
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = ProcessToolBindingCursor(
                last.pid,
                last.tool_name,
            )
        return ProcessToolBindingPage(records=records, next_cursor=next_cursor)

    def get_processes_with_ancestors(self, pids: Iterable[str]) -> list[AgentProcess]:
        selected = sorted({str(pid) for pid in pids if str(pid)})
        if not selected:
            return []
        placeholders = ", ".join("?" for _ in selected)
        rows = self._query(
            f"""
            WITH RECURSIVE ancestors(pid) AS (
                SELECT pid FROM processes WHERE pid IN ({placeholders})
                UNION
                SELECT processes.parent_pid
                  FROM processes
                  JOIN ancestors ON processes.pid = ancestors.pid
                 WHERE processes.parent_pid IS NOT NULL
            )
            SELECT processes.*
              FROM processes
              JOIN ancestors ON ancestors.pid = processes.pid
             ORDER BY processes.created_at, processes.pid
            """,
            selected,
        )
        return [self._row_to_process(row) for row in rows]

    def list_processes_by_status(self, status: ProcessStatus | str) -> list[AgentProcess]:
        selected = ProcessStatus(status).value
        rows = self._query(
            "SELECT * FROM processes WHERE status = ? ORDER BY created_at, pid",
            (selected,),
        )
        return [self._row_to_process(row) for row in rows]

    def query_orphaned_created_processes(
        self,
        *,
        after: ProcessCursor | None,
        limit: int,
    ) -> ProcessPage:
        """Return CREATED processes with no durable launch publication."""

        selected_limit = self._runtime_publication_reconciliation_limit(limit)
        clauses = [
            "processes.status = ?",
            "NOT EXISTS ("
            "SELECT 1 FROM runtime_publications "
            "WHERE runtime_publications.pid = processes.pid "
            "AND runtime_publications.kind = ? LIMIT 1 OFFSET 0)",
        ]
        params: list[Any] = [
            ProcessStatus.CREATED.value,
            "process_launch",
        ]
        if after is not None:
            clauses.append("(processes.created_at, processes.pid) > (?, ?)")
            params.extend((after.created_at, after.pid))
        params.append(selected_limit + 1)
        rows = self._query(
            f"SELECT processes.* FROM processes WHERE {' AND '.join(clauses)} "
            "ORDER BY processes.created_at, processes.pid LIMIT ?",
            params,
        )
        records = tuple(
            self._row_to_process(row) for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = ProcessCursor(last.created_at, last.pid)
        return ProcessPage(records=records, next_cursor=next_cursor)

    def list_child_processes(self, parent_pid: str) -> list[AgentProcess]:
        rows = self._query(
            "SELECT * FROM processes WHERE parent_pid = ? ORDER BY created_at, pid",
            (parent_pid,),
        )
        return [self._row_to_process(row) for row in rows]

    # -- Durable TaskRun v1 -------------------------------------------------

    @property
    def runtime_epoch(self) -> int | None:
        return getattr(self, "_task_run_runtime_epoch", None)

    def claim_runtime_epoch(self, instance_id: str) -> int:
        """Advance the global Runtime incarnation fence under the backend lease."""

        if not isinstance(instance_id, str) or not instance_id or "\x00" in instance_id:
            raise ValidationError("runtime epoch claim requires a stable instance id")
        if self._transaction_depth:
            raise ValidationError("runtime epoch must be claimed outside another transaction")
        with self.transaction() as cur:
            changed = cur.execute(
                "UPDATE runtime_counters SET value = value + 1 "
                "WHERE counter_name = ?",
                ("task_run_runtime_epoch",),
            )
            if changed.rowcount != 1:
                raise ValidationError("TaskRun runtime epoch counter is missing")
            row = cur.execute(
                "SELECT value FROM runtime_counters WHERE counter_name = ?",
                ("task_run_runtime_epoch",),
            ).fetchone()
            if row is None:
                raise ValidationError("TaskRun runtime epoch counter is missing")
            epoch = int(row["value"])
        self._task_run_runtime_epoch = epoch
        self._task_run_runtime_instance_id = instance_id
        return epoch

    def insert_task_run(self, run: TaskRunRecord, *, cursor: Any | None = None) -> None:
        if not isinstance(run, TaskRunRecord):
            raise ValidationError("TaskRun insert requires a TaskRunRecord")
        if cursor is None:
            with self.transaction() as cur:
                self.insert_task_run(run, cursor=cur)
            return
        cursor.execute(
            """
            INSERT INTO task_runs (
                run_id, spec_schema_version, display_title, image_id,
                launch_options_json, authority_manifest_id, status, revision,
                runtime_epoch, root_pid, active_pid, pause_generation,
                cancel_generation, binding_hash, deadline_at, retention,
                blockers_json, requirement_count, satisfied_requirement_count,
                step_count, completed_step_count, result_ref, created_at,
                updated_at, started_at, completed_at, finalized_at,
                payloads_purged_at
            ) VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            self._task_run_params(run),
        )

    def get_task_run(self, run_id: str) -> TaskRunRecord | None:
        rows = self._query("SELECT * FROM task_runs WHERE run_id = ?", (run_id,))
        return self._row_to_task_run(rows[0]) if rows else None

    def list_task_runs(
        self,
        *,
        statuses: Iterable[TaskRunStatus | str] | None = None,
        after: TaskRunCursor | None = None,
        limit: int | None = None,
    ) -> TaskRunPage:
        selected_limit = self._task_run_page_limit(
            limit,
            default=self.config.task_runs.list_page_size,
            hard_limit=self.config.task_runs.list_hard_limit,
            label="TaskRun list",
        )
        clauses: list[str] = []
        params: list[Any] = []
        if statuses is not None:
            selected_statuses = tuple(
                dict.fromkeys(TaskRunStatus(status).value for status in statuses)
            )
            if not selected_statuses:
                return TaskRunPage(records=())
            clauses.append(
                f"status IN ({', '.join('?' for _ in selected_statuses)})"
            )
            params.extend(selected_statuses)
        if after is not None:
            if not isinstance(after, TaskRunCursor):
                raise ValidationError("TaskRun list cursor has an invalid type")
            clauses.append("(created_at, run_id) > (?, ?)")
            params.extend((after.created_at, after.run_id))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(selected_limit + 1)
        rows = self._query(
            f"SELECT * FROM task_runs{where} "
            "ORDER BY created_at COLLATE BINARY, run_id COLLATE BINARY LIMIT ?",
            params,
        )
        records = tuple(self._row_to_task_run(row) for row in rows[:selected_limit])
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = TaskRunCursor(last.created_at, last.run_id)
        return TaskRunPage(records=records, next_cursor=next_cursor)

    def list_recoverable_task_runs(
        self,
        *,
        after: TaskRunCursor | None,
        limit: int,
    ) -> TaskRunPage:
        selected_limit = self._task_run_page_limit(
            limit,
            default=self.config.task_runs.recovery_page_size,
            hard_limit=self.config.task_runs.recovery_page_hard_limit,
            label="TaskRun recovery",
        )
        clauses = ["status NOT IN ('succeeded', 'failed', 'cancelled')"]
        params: list[Any] = []
        if after is not None:
            if not isinstance(after, TaskRunCursor):
                raise ValidationError("TaskRun recovery cursor has an invalid type")
            clauses.append("(created_at, run_id) > (?, ?)")
            params.extend((after.created_at, after.run_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM task_runs INDEXED BY idx_task_runs_recovery "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at COLLATE BINARY, run_id COLLATE BINARY LIMIT ?",
            params,
        )
        records = tuple(self._row_to_task_run(row) for row in rows[:selected_limit])
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = TaskRunCursor(last.created_at, last.run_id)
        return TaskRunPage(records=records, next_cursor=next_cursor)

    def update_task_run_cas(
        self,
        run_id: str,
        expected_revision: int,
        *,
        updates: Mapping[str, Any],
        expected_runtime_epoch: int | None = None,
    ) -> TaskRunRecord:
        if type(expected_revision) is not int or expected_revision < 0:
            raise ValidationError("TaskRun expected revision must be non-negative")
        if expected_runtime_epoch is not None and (
            type(expected_runtime_epoch) is not int or expected_runtime_epoch <= 0
        ):
            raise ValidationError("TaskRun expected runtime epoch must be positive")
        allowed = {
            "status",
            "root_pid",
            "active_pid",
            "pause_generation",
            "cancel_generation",
            "binding_hash",
            "blockers",
            "requirement_count",
            "satisfied_requirement_count",
            "step_count",
            "completed_step_count",
            "result_ref",
            "updated_at",
            "started_at",
            "completed_at",
            "finalized_at",
            "payloads_purged_at",
        }
        unknown = sorted(set(updates) - allowed)
        if unknown:
            raise ValidationError(f"immutable or unknown TaskRun fields: {unknown}")
        selected = dict(updates)
        selected.setdefault("updated_at", utc_now())
        encoded: dict[str, Any] = {}
        for name, value in selected.items():
            column = "blockers_json" if name == "blockers" else name
            if name == "status":
                value = TaskRunStatus(value).value
            elif name == "blockers":
                value = canonical_task_run_json(list(value))
            elif name in {
                "pause_generation",
                "cancel_generation",
                "requirement_count",
                "satisfied_requirement_count",
                "step_count",
                "completed_step_count",
            } and (type(value) is not int or value < 0):
                raise ValidationError(f"TaskRun {name} must be non-negative")
            encoded[column] = value
        assignments = [f"{column} = ?" for column in encoded]
        assignments.append("revision = revision + 1")
        params = [*encoded.values(), run_id, expected_revision]
        where = "run_id = ? AND revision = ?"
        if expected_runtime_epoch is not None:
            where += " AND runtime_epoch = ?"
            params.append(expected_runtime_epoch)
        with self.transaction() as cur:
            changed = cur.execute(
                f"UPDATE task_runs SET {', '.join(assignments)} WHERE {where}",
                params,
            )
            if changed.rowcount != 1:
                raise TaskRunRevisionConflict(
                    f"TaskRun revision or epoch conflict for {run_id}"
                )
            row = cur.execute(
                "SELECT * FROM task_runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            if row is None:
                raise TaskRunRevisionConflict(f"TaskRun no longer exists: {run_id}")
            return self._row_to_task_run(row)

    def claim_task_run_epoch(
        self,
        run_id: str,
        expected_revision: int,
        runtime_epoch: int | None = None,
    ) -> TaskRunRecord:
        selected_epoch = runtime_epoch if runtime_epoch is not None else self.runtime_epoch
        if type(selected_epoch) is not int or selected_epoch <= 0:
            raise ValidationError("TaskRun claim requires a claimed Runtime epoch")
        with self.transaction() as cur:
            changed = cur.execute(
                """
                UPDATE task_runs
                   SET runtime_epoch = ?, revision = revision + 1, updated_at = ?
                 WHERE run_id = ? AND revision = ? AND runtime_epoch < ?
                   AND status NOT IN ('succeeded', 'failed', 'cancelled')
                """,
                (
                    selected_epoch,
                    utc_now(),
                    run_id,
                    expected_revision,
                    selected_epoch,
                ),
            )
            if changed.rowcount != 1:
                raise TaskRunRevisionConflict(
                    f"TaskRun epoch claim conflict for {run_id}"
                )
            # Rebind the durable tree in the same commit. A stale Runtime can
            # no longer claim or settle one of these rows after this point.
            cur.execute(
                "UPDATE processes SET task_run_epoch = ? WHERE task_run_id = ?",
                (selected_epoch, run_id),
            )
            row = cur.execute(
                "SELECT * FROM task_runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            if row is None:
                raise TaskRunRevisionConflict(f"TaskRun no longer exists: {run_id}")
            return self._row_to_task_run(row)

    def claim_terminal_task_run_epoch(
        self,
        run_id: str,
        expected_revision: int,
        runtime_epoch: int | None = None,
    ) -> TaskRunRecord:
        """Fence one terminal Run for an on-demand Host mutation.

        Startup recovery deliberately does not claim terminal Runs.  Explicit
        terminal-only mutations therefore use this narrower claim, and callers
        must keep it in the same outer transaction as the mutation and command
        receipt so a failed operation cannot consume the caller's revision.
        """

        selected_epoch = runtime_epoch if runtime_epoch is not None else self.runtime_epoch
        if type(selected_epoch) is not int or selected_epoch <= 0:
            raise ValidationError(
                "terminal TaskRun claim requires a claimed Runtime epoch"
            )
        if selected_epoch != self.runtime_epoch:
            raise TaskRunRevisionConflict(
                f"terminal TaskRun claim used a stale Runtime epoch for {run_id}"
            )
        with self.transaction() as cur:
            changed = cur.execute(
                """
                UPDATE task_runs
                   SET runtime_epoch = ?, revision = revision + 1, updated_at = ?
                 WHERE run_id = ? AND revision = ? AND runtime_epoch < ?
                   AND status IN ('succeeded', 'failed', 'cancelled')
                """,
                (
                    selected_epoch,
                    utc_now(),
                    run_id,
                    expected_revision,
                    selected_epoch,
                ),
            )
            if changed.rowcount != 1:
                raise TaskRunRevisionConflict(
                    f"terminal TaskRun epoch claim conflict for {run_id}"
                )
            cur.execute(
                "UPDATE processes SET task_run_epoch = ? WHERE task_run_id = ?",
                (selected_epoch, run_id),
            )
            row = cur.execute(
                "SELECT * FROM task_runs WHERE run_id = ?", (run_id,)
            ).fetchone()
            if row is None:
                raise TaskRunRevisionConflict(f"TaskRun no longer exists: {run_id}")
            return self._row_to_task_run(row)

    def insert_task_run_requirement(
        self,
        requirement: TaskRunRequirement,
        *,
        cursor: Any | None = None,
    ) -> None:
        if not isinstance(requirement, TaskRunRequirement):
            raise ValidationError("TaskRun requirement insert requires a model")
        if cursor is None:
            with self.transaction() as cur:
                self.insert_task_run_requirement(requirement, cursor=cur)
            return
        cursor.execute(
            """
            INSERT INTO task_run_requirements (
                requirement_id, run_id, ordinal, kind, status, payload_id,
                requirement_sha256, label, created_by, created_at, updated_at,
                started_at, completed_at, waived_by, waiver_reason
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                requirement.requirement_id,
                requirement.run_id,
                requirement.ordinal,
                requirement.kind.value,
                requirement.status.value,
                requirement.payload_id,
                requirement.requirement_sha256,
                requirement.label,
                requirement.created_by,
                requirement.created_at,
                requirement.updated_at,
                requirement.started_at,
                requirement.completed_at,
                requirement.waived_by,
                requirement.waiver_reason,
            ),
        )

    def list_task_run_requirements(
        self,
        run_id: str,
        *,
        after: tuple[int, str] | None = None,
        limit: int | None = None,
    ) -> list[TaskRunRequirement]:
        """Read requirements by the durable ``(ordinal, id)`` keyset."""

        clauses = ["run_id = ?"]
        params: list[Any] = [run_id]
        if after is not None:
            if (
                not isinstance(after, tuple)
                or len(after) != 2
                or type(after[0]) is not int
                or after[0] < 0
                or not isinstance(after[1], str)
                or not after[1]
            ):
                raise ValidationError("TaskRun requirement cursor is invalid")
            clauses.append("(ordinal, requirement_id) > (?, ?)")
            params.extend(after)
        suffix = ""
        if limit is not None:
            # Callers fetch one look-ahead row to derive the opaque next cursor.
            # Runtime recovery and follow-up append integrity checks may need
            # one bounded read up to the recovery ceiling. Public TaskRun
            # pagination applies its smaller list_hard_limit before reaching
            # this Store method.
            hard_limit = max(
                self.config.task_runs.list_hard_limit + 1,
                self.config.task_runs.recovery_page_hard_limit + 1,
            )
            selected_limit = self._task_run_page_limit(
                limit,
                default=self.config.task_runs.list_page_size,
                hard_limit=hard_limit,
                label="TaskRun requirement list",
            )
            suffix = " LIMIT ?"
            params.append(selected_limit)
        rows = self._query(
            "SELECT * FROM task_run_requirements "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY ordinal, requirement_id COLLATE BINARY"
            f"{suffix}",
            params,
        )
        return [self._row_to_task_run_requirement(row) for row in rows]

    def update_task_run_requirement_cas(
        self,
        requirement_id: str,
        *,
        expected_status: TaskRunRequirementStatus | str,
        status: TaskRunRequirementStatus | str,
        updated_at: str,
        started_at: str | None = None,
        completed_at: str | None = None,
        waived_by: str | None = None,
        waiver_reason: str | None = None,
    ) -> TaskRunRequirement | None:
        old = TaskRunRequirementStatus(expected_status)
        new = TaskRunRequirementStatus(status)
        if new is TaskRunRequirementStatus.WAIVED:
            if not waived_by or not waiver_reason:
                raise ValidationError("waiving a TaskRun requirement requires Host evidence")
        elif waived_by is not None or waiver_reason is not None:
            raise ValidationError("only waived TaskRun requirements retain waiver evidence")
        with self.transaction() as cur:
            changed = cur.execute(
                """
                UPDATE task_run_requirements
                   SET status = ?, updated_at = ?, started_at = ?, completed_at = ?,
                       waived_by = ?, waiver_reason = ?
                 WHERE requirement_id = ? AND status = ?
                """,
                (
                    new.value,
                    updated_at,
                    started_at,
                    completed_at,
                    waived_by,
                    waiver_reason,
                    requirement_id,
                    old.value,
                ),
            )
            if changed.rowcount != 1:
                return None
            row = cur.execute(
                "SELECT * FROM task_run_requirements WHERE requirement_id = ?",
                (requirement_id,),
            ).fetchone()
            return self._row_to_task_run_requirement(row) if row is not None else None

    def insert_task_run_payload(
        self,
        payload: TaskRunPayload,
        *,
        cursor: Any | None = None,
    ) -> None:
        if not isinstance(payload, TaskRunPayload):
            raise ValidationError("TaskRun payload insert requires a model")
        if payload.size_bytes > self.config.task_runs.payload_max_bytes:
            raise ValidationError("TaskRun payload exceeds configured maximum")
        if (
            payload.retention_state is TaskRunPayloadRetention.PLAINTEXT
            and not self.config.task_runs.plaintext_payloads_enabled
        ):
            raise ValidationError(
                "durable TaskRun plaintext payloads are disabled; Host must "
                "explicitly enable task_runs.plaintext_payloads_enabled"
            )
        if cursor is None:
            with self.transaction() as cur:
                self.insert_task_run_payload(payload, cursor=cur)
            return
        cursor.execute(
            """
            INSERT INTO task_run_payloads (
                payload_id, run_id, role, label, canonical_json, sha256,
                size_bytes, retention_state, created_at, updated_at, purged_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                payload.payload_id,
                payload.run_id,
                payload.role,
                payload.label,
                payload.canonical_json,
                payload.sha256,
                payload.size_bytes,
                payload.retention_state.value,
                payload.created_at,
                payload.updated_at,
                payload.purged_at,
            ),
        )

    def get_task_run_payload(self, payload_id: str) -> TaskRunPayload | None:
        rows = self._query(
            "SELECT * FROM task_run_payloads WHERE payload_id = ?", (payload_id,)
        )
        return self._row_to_task_run_payload(rows[0]) if rows else None

    def list_task_run_payloads(self, run_id: str) -> list[TaskRunPayload]:
        rows = self._query(
            "SELECT * FROM task_run_payloads WHERE run_id = ? "
            "ORDER BY created_at, payload_id",
            (run_id,),
        )
        return [self._row_to_task_run_payload(row) for row in rows]

    def purge_task_run_payloads(self, run_id: str, *, purged_at: str) -> int:
        """Irreversibly reduce Run payloads to hash-only projections."""

        with self.transaction() as cur:
            changed = cur.execute(
                """
                UPDATE task_run_payloads
                   SET canonical_json = NULL, retention_state = 'hash_only',
                       purged_at = ?, updated_at = ?
                 WHERE run_id = ? AND retention_state = 'plaintext'
                """,
                (purged_at, purged_at, run_id),
            )
            purged_count = int(changed.rowcount)
            cur.execute("DELETE FROM task_run_resume_points WHERE run_id = ?", (run_id,))
            return purged_count

    def upsert_task_run_resume_point(self, point: TaskRunResumePoint) -> None:
        if not isinstance(point, TaskRunResumePoint):
            raise ValidationError("TaskRun resume point upsert requires a model")
        with self.transaction() as cur:
            valid = cur.execute(
                """
                SELECT 1
                  FROM task_runs AS run
                  JOIN processes AS process ON process.pid = ?
                 WHERE run.run_id = ? AND run.runtime_epoch = ?
                   AND process.task_run_id = run.run_id
                   AND process.task_run_epoch = run.runtime_epoch
                   AND process.revision = ?
                   AND EXISTS (
                     SELECT 1 FROM task_run_payloads AS transcript
                      WHERE transcript.payload_id = ?
                        AND transcript.run_id = run.run_id
                        AND transcript.role = 'transcript'
                        AND transcript.retention_state = 'plaintext'
                        AND transcript.canonical_json IS NOT NULL
                   )
                   AND (
                     CAST(? AS TEXT) IS NULL OR EXISTS (
                       SELECT 1 FROM task_run_payloads AS summary
                        WHERE summary.payload_id = ?
                          AND summary.run_id = run.run_id
                          AND summary.role = 'summary'
                          AND summary.retention_state = 'plaintext'
                          AND summary.canonical_json IS NOT NULL
                     )
                   )
                   AND (
                     CAST(? AS TEXT) IS NULL OR EXISTS (
                       SELECT 1 FROM task_run_payloads AS pending
                        WHERE pending.payload_id = ?
                          AND pending.run_id = run.run_id
                          AND pending.role = 'pending_action'
                          AND pending.retention_state = 'plaintext'
                          AND pending.canonical_json IS NOT NULL
                     )
                   )
                """,
                (
                    point.pid,
                    point.run_id,
                    point.task_run_epoch,
                    point.process_revision,
                    point.transcript_payload_id,
                    point.summary_payload_id,
                    point.summary_payload_id,
                    point.pending_action_payload_id,
                    point.pending_action_payload_id,
                ),
            ).fetchone()
            if valid is None:
                raise TaskRunRevisionConflict("TaskRun resume point lost its epoch fence")
            existing_row = cur.execute(
                "SELECT * FROM task_run_resume_points WHERE pid = ?",
                (point.pid,),
            ).fetchone()
            if existing_row is not None:
                existing = self._row_to_task_run_resume_point(existing_row)
                if existing == point:
                    return
                if (
                    existing.run_id != point.run_id
                    or point.task_run_epoch < existing.task_run_epoch
                    or point.safe_point_seq <= existing.safe_point_seq
                ):
                    raise TaskRunRevisionConflict(
                        "TaskRun resume point did not advance its safe-point fence"
                    )
            changed = cur.execute(
                """
                INSERT INTO task_run_resume_points (
                    pid, run_id, task_run_epoch, process_revision,
                    context_generation, safe_point_seq, binding_hash,
                    image_binding_hash, tool_binding_hash, provider_binding_hash,
                    transcript_payload_id, summary_payload_id,
                    pending_action_payload_id, last_effect_seq, integrity_sha256,
                    complete, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                ON CONFLICT(pid) DO UPDATE SET
                    run_id = excluded.run_id,
                    task_run_epoch = excluded.task_run_epoch,
                    process_revision = excluded.process_revision,
                    context_generation = excluded.context_generation,
                    safe_point_seq = excluded.safe_point_seq,
                    binding_hash = excluded.binding_hash,
                    image_binding_hash = excluded.image_binding_hash,
                    tool_binding_hash = excluded.tool_binding_hash,
                    provider_binding_hash = excluded.provider_binding_hash,
                    transcript_payload_id = excluded.transcript_payload_id,
                    summary_payload_id = excluded.summary_payload_id,
                    pending_action_payload_id = excluded.pending_action_payload_id,
                    last_effect_seq = excluded.last_effect_seq,
                    integrity_sha256 = excluded.integrity_sha256,
                    complete = excluded.complete,
                    updated_at = excluded.updated_at
                WHERE task_run_resume_points.run_id = excluded.run_id
                  AND task_run_resume_points.task_run_epoch <= excluded.task_run_epoch
                  AND task_run_resume_points.safe_point_seq < excluded.safe_point_seq
                """,
                self._task_run_resume_point_params(point),
            )
            if changed.rowcount != 1:
                raise TaskRunRevisionConflict(
                    "TaskRun resume point lost its safe-point fence"
                )

    def get_task_run_resume_point(
        self,
        pid: str,
        *,
        complete_only: bool = True,
    ) -> TaskRunResumePoint | None:
        clause = " AND complete = 1" if complete_only else ""
        rows = self._query(
            f"SELECT * FROM task_run_resume_points WHERE pid = ?{clause}",
            (pid,),
        )
        return self._row_to_task_run_resume_point(rows[0]) if rows else None

    def list_task_run_resume_points(
        self,
        run_id: str,
        *,
        complete_only: bool = True,
        limit: int | None = None,
    ) -> list[TaskRunResumePoint]:
        clause = " AND complete = 1" if complete_only else ""
        suffix = ""
        params: list[Any] = [run_id]
        if limit is not None:
            selected_limit = self._task_run_page_limit(
                limit,
                default=self.config.task_runs.recovery_page_size,
                hard_limit=self.config.task_runs.recovery_page_hard_limit + 1,
                label="TaskRun resume-point list",
            )
            suffix = " LIMIT ?"
            params.append(selected_limit)
        rows = self._query(
            "SELECT * FROM task_run_resume_points WHERE run_id = ?"
            f"{clause} ORDER BY pid{suffix}",
            params,
        )
        return [self._row_to_task_run_resume_point(row) for row in rows]

    def delete_task_run_resume_point(self, pid: str) -> bool:
        return self._execute(
            "DELETE FROM task_run_resume_points WHERE pid = ?", (pid,)
        ).rowcount == 1

    def insert_task_run_command(
        self,
        command: TaskRunCommand,
        *,
        cursor: Any | None = None,
        expected_runtime_epoch: int | None = None,
    ) -> TaskRunCommand:
        if not isinstance(command, TaskRunCommand):
            raise ValidationError("TaskRun command insert requires a model")
        if expected_runtime_epoch is not None and (
            type(expected_runtime_epoch) is not int
            or expected_runtime_epoch <= 0
            or expected_runtime_epoch > 2**63 - 1
        ):
            raise ValidationError("TaskRun command runtime epoch is invalid")
        result_json = canonical_task_run_json(command.result)
        if len(result_json.encode("utf-8")) > self.config.task_runs.command_result_max_bytes:
            raise ValidationError("TaskRun command result exceeds configured maximum")
        if cursor is None:
            with self.transaction() as cur:
                return self.insert_task_run_command(
                    command,
                    cursor=cur,
                    expected_runtime_epoch=expected_runtime_epoch,
                )
        if expected_runtime_epoch is not None:
            # A no-op conditional UPDATE is a portable row lock on both
            # SQLite and PostgreSQL. It serializes this command mutation with
            # the Runtime epoch increment instead of merely observing an MVCC
            # snapshot that a concurrent claimant could immediately obsolete.
            fenced = cursor.execute(
                "UPDATE runtime_counters SET value = value "
                "WHERE counter_name = ? AND value = ?",
                ("task_run_runtime_epoch", expected_runtime_epoch),
            )
            if fenced.rowcount != 1:
                raise TaskRunRevisionConflict("TaskRun runtime epoch is stale")
        rows = list(
            cursor.execute(
                "SELECT * FROM task_run_commands WHERE command_id = ? "
                "OR (client_request_id IS NOT NULL AND client_request_id = ?)",
                (command.command_id, command.client_request_id),
            )
        )
        if rows:
            if len(rows) != 1:
                raise TaskRunCommandConflict(
                    "TaskRun command idempotency key was reused with a different request"
                )
            existing = self._row_to_task_run_command(rows[0])
            if (
                existing.command_id != command.command_id
                or existing.client_request_id != command.client_request_id
                or existing.run_id != command.run_id
                or existing.command_kind != command.command_kind
                or existing.request_hash != command.request_hash
            ):
                raise TaskRunCommandConflict(
                    "TaskRun command idempotency key was reused with a different request"
                )
            return existing
        if expected_runtime_epoch is None:
            changed = cursor.execute(
                """
                INSERT INTO task_run_commands (
                    command_id, client_request_id, run_id, command_kind,
                    request_hash, result_json, result_revision, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    command.command_id,
                    command.client_request_id,
                    command.run_id,
                    command.command_kind,
                    command.request_hash,
                    result_json,
                    command.result_revision,
                    command.created_at,
                ),
            )
        else:
            # Fence the mutation itself. A preceding read alone would race a
            # newer Runtime advancing the epoch on PostgreSQL.
            changed = cursor.execute(
                """
                INSERT INTO task_run_commands (
                    command_id, client_request_id, run_id, command_kind,
                    request_hash, result_json, result_revision, created_at
                )
                SELECT ?, ?, ?, ?, ?, ?, ?, ?
                 WHERE EXISTS (
                    SELECT 1 FROM runtime_counters
                     WHERE counter_name = ? AND value = ?
                 )
                """,
                (
                    command.command_id,
                    command.client_request_id,
                    command.run_id,
                    command.command_kind,
                    command.request_hash,
                    result_json,
                    command.result_revision,
                    command.created_at,
                    "task_run_runtime_epoch",
                    expected_runtime_epoch,
                ),
            )
            if changed.rowcount != 1:
                raise TaskRunRevisionConflict("TaskRun runtime epoch is stale")
        return command

    def get_task_run_command(
        self,
        run_id: str,
        command_id: str,
    ) -> TaskRunCommand | None:
        rows = self._query(
            "SELECT * FROM task_run_commands WHERE run_id = ? AND command_id = ?",
            (run_id, command_id),
        )
        return self._row_to_task_run_command(rows[0]) if rows else None

    def list_task_run_commands(
        self,
        run_id: str,
        *,
        limit: int,
    ) -> list[TaskRunCommand]:
        selected_limit = self._task_run_page_limit(
            limit,
            default=self.config.task_runs.recovery_page_size,
            hard_limit=self.config.task_runs.recovery_page_hard_limit + 1,
            label="TaskRun command list",
        )
        rows = self._query(
            "SELECT * FROM task_run_commands "
            "WHERE run_id COLLATE BINARY = ? COLLATE BINARY "
            "ORDER BY created_at COLLATE BINARY, command_id COLLATE BINARY LIMIT ?",
            (run_id, selected_limit),
        )
        return [self._row_to_task_run_command(row) for row in rows]

    def get_task_run_command_by_client_request_id(
        self,
        client_request_id: str,
    ) -> TaskRunCommand | None:
        rows = self._query(
            "SELECT * FROM task_run_commands WHERE client_request_id = ?",
            (client_request_id,),
        )
        return self._row_to_task_run_command(rows[0]) if rows else None

    def update_task_run_command_result(
        self,
        run_id: str,
        command_id: str,
        *,
        expected_result_revision: int,
        result: Mapping[str, Any],
        result_revision: int,
        expected_runtime_epoch: int | None = None,
    ) -> TaskRunCommand:
        if (
            type(expected_result_revision) is not int
            or expected_result_revision < 0
            or expected_result_revision > 2**63 - 1
            or type(result_revision) is not int
            or result_revision < expected_result_revision
            or result_revision > 2**63 - 1
        ):
            raise ValidationError("TaskRun command result revision is invalid")
        if expected_runtime_epoch is not None and (
            type(expected_runtime_epoch) is not int
            or expected_runtime_epoch <= 0
            or expected_runtime_epoch > 2**63 - 1
        ):
            raise ValidationError("TaskRun command runtime epoch is invalid")
        if not isinstance(result, Mapping):
            raise ValidationError("TaskRun command result must be an object")
        selected_result = dict(result)
        result_json = canonical_task_run_json(selected_result)
        if len(result_json.encode("utf-8")) > self.config.task_runs.command_result_max_bytes:
            raise ValidationError("TaskRun command result exceeds configured maximum")
        with self.transaction() as cur:
            if expected_runtime_epoch is not None:
                fenced = cur.execute(
                    "UPDATE runtime_counters SET value = value "
                    "WHERE counter_name = ? AND value = ?",
                    ("task_run_runtime_epoch", expected_runtime_epoch),
                )
                if fenced.rowcount != 1:
                    raise TaskRunRevisionConflict("TaskRun runtime epoch is stale")
            where = "WHERE run_id = ? AND command_id = ? AND result_revision = ?"
            params: list[Any] = [
                result_json,
                result_revision,
                run_id,
                command_id,
                expected_result_revision,
            ]
            if expected_runtime_epoch is not None:
                where += (
                    " AND EXISTS (SELECT 1 FROM runtime_counters "
                    "WHERE counter_name = ? AND value = ?)"
                )
                params.extend(["task_run_runtime_epoch", expected_runtime_epoch])
            changed_count = cur.execute(
                "UPDATE task_run_commands SET result_json = ?, result_revision = ? "
                + where,
                params,
            ).rowcount
            row = cur.execute(
                "SELECT * FROM task_run_commands WHERE run_id = ? AND command_id = ?",
                (run_id, command_id),
            ).fetchone()
            if row is None:
                raise TaskRunRevisionConflict("TaskRun command result target is missing")
            persisted = self._row_to_task_run_command(row)
            if changed_count == 1:
                return persisted
            if persisted.result_revision == result_revision and persisted.result == selected_result:
                return persisted
            raise TaskRunRevisionConflict(
                "TaskRun command result revision conflict"
            )

    def append_task_run_ledger_item(
        self,
        item: TaskRunLedgerItem,
        *,
        cursor: Any | None = None,
    ) -> TaskRunLedgerItem:
        if not isinstance(item, TaskRunLedgerItem):
            raise ValidationError("TaskRun ledger append requires a model")
        if cursor is None:
            with self.transaction() as cur:
                return self.append_task_run_ledger_item(item, cursor=cur)
        existing_row = cursor.execute(
            "SELECT * FROM task_run_ledger WHERE item_id = ?", (item.item_id,)
        ).fetchone()
        if existing_row is not None:
            existing = self._row_to_task_run_ledger_item(existing_row)
            if replace(existing, seq=item.seq) != item:
                raise ValidationError("TaskRun ledger item identity collision")
            return existing
        changed = cursor.execute(
            "UPDATE runtime_counters SET value = value + 1 WHERE counter_name = ?",
            ("task_run_ledger",),
        )
        if changed.rowcount != 1:
            raise ValidationError("TaskRun ledger counter is missing")
        counter = cursor.execute(
            "SELECT value FROM runtime_counters WHERE counter_name = ?",
            ("task_run_ledger",),
        ).fetchone()
        if counter is None:
            raise ValidationError("TaskRun ledger counter is missing")
        persisted = replace(item, seq=int(counter["value"]))
        cursor.execute(
            """
            INSERT INTO task_run_ledger (
                seq, item_id, run_id, kind, status, label, requirement_id, pid,
                operation_id, effect_id, human_request_id, llm_call_id,
                checkpoint_id, object_task_id, payload_id, metadata_json, occurred_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                persisted.seq,
                persisted.item_id,
                persisted.run_id,
                persisted.kind.value,
                persisted.status,
                persisted.label,
                persisted.requirement_id,
                persisted.pid,
                persisted.operation_id,
                persisted.effect_id,
                persisted.human_request_id,
                persisted.llm_call_id,
                persisted.checkpoint_id,
                persisted.object_task_id,
                persisted.payload_id,
                canonical_task_run_json(persisted.metadata),
                persisted.occurred_at,
            ),
        )
        return persisted

    def get_task_run_ledger_item(
        self,
        run_id: str,
        item_id: str,
    ) -> TaskRunLedgerItem | None:
        rows = self._query(
            "SELECT * FROM task_run_ledger WHERE run_id = ? AND item_id = ?",
            (run_id, item_id),
        )
        return self._row_to_task_run_ledger_item(rows[0]) if rows else None

    def list_task_run_ledger(
        self,
        run_id: str,
        *,
        after: TaskRunLedgerCursor | None,
        limit: int,
    ) -> TaskRunLedgerPage:
        selected_limit = self._task_run_page_limit(
            limit,
            default=self.config.task_runs.ledger_page_size,
            hard_limit=self.config.task_runs.ledger_page_hard_limit,
            label="TaskRun ledger",
        )
        clauses = ["run_id = ?"]
        params: list[Any] = [run_id]
        if after is not None:
            if not isinstance(after, TaskRunLedgerCursor):
                raise ValidationError("TaskRun ledger cursor has an invalid type")
            clauses.append("(seq, item_id) > (?, ?)")
            params.extend((after.seq, after.item_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM task_run_ledger INDEXED BY idx_task_run_ledger_run_seq "
            f"WHERE {' AND '.join(clauses)} ORDER BY seq, item_id LIMIT ?",
            params,
        )
        records = tuple(
            self._row_to_task_run_ledger_item(row) for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = TaskRunLedgerCursor(last.seq, last.item_id)
        return TaskRunLedgerPage(records=records, next_cursor=next_cursor)

    def insert_task_run_link(
        self,
        link: TaskRunLink,
        *,
        cursor: Any | None = None,
    ) -> None:
        if not isinstance(link, TaskRunLink):
            raise ValidationError("TaskRun link insert requires a model")
        if cursor is None:
            with self.transaction() as cur:
                self.insert_task_run_link(link, cursor=cur)
            return
        identity_rows = list(
            cursor.execute(
                "SELECT * FROM task_run_links WHERE link_id = ? OR "
                "(run_id = ? AND evidence_type = ? AND evidence_id = ? AND role = ?)",
                (
                    link.link_id,
                    link.run_id,
                    link.evidence_type,
                    link.evidence_id,
                    link.role,
                ),
            )
        )
        if identity_rows:
            persisted = [self._row_to_task_run_link(row) for row in identity_rows]
            if len(persisted) != 1 or persisted[0] != link:
                raise ValidationError("TaskRun link identity collision")
            return
        cursor.execute(
            """
            INSERT INTO task_run_links (
                link_id, run_id, ledger_seq, evidence_type, evidence_id,
                role, metadata_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                link.link_id,
                link.run_id,
                link.ledger_seq,
                link.evidence_type,
                link.evidence_id,
                link.role,
                canonical_task_run_json(link.metadata),
                link.created_at,
            ),
        )

    def list_task_run_links(
        self,
        run_id: str,
        *,
        limit: int | None = None,
    ) -> list[TaskRunLink]:
        if limit is None:
            sql = (
                "SELECT * FROM task_run_links "
                "WHERE run_id COLLATE BINARY = ? COLLATE BINARY "
                "ORDER BY ledger_seq, link_id COLLATE BINARY"
            )
            params: tuple[Any, ...] = (run_id,)
        else:
            selected_limit = self._task_run_page_limit(
                limit,
                default=self.config.task_runs.recovery_page_size,
                hard_limit=self.config.task_runs.recovery_page_hard_limit + 1,
                label="TaskRun link list",
            )
            sql = (
                "SELECT * FROM task_run_links "
                "WHERE run_id COLLATE BINARY = ? COLLATE BINARY "
                "ORDER BY ledger_seq, link_id COLLATE BINARY LIMIT ?"
            )
            params = (run_id, selected_limit)
        rows = self._query(sql, params)
        return [self._row_to_task_run_link(row) for row in rows]

    def list_processes_for_task_run(self, run_id: str) -> list[AgentProcess]:
        rows = self._query(
            "SELECT * FROM processes WHERE task_run_id = ? ORDER BY created_at, pid",
            (run_id,),
        )
        return [self._row_to_process(row) for row in rows]

    def list_task_run_process_ids(self, run_id: str) -> tuple[str, ...]:
        rows = self._query(
            "SELECT pid FROM processes WHERE task_run_id = ? ORDER BY pid", (run_id,)
        )
        return tuple(str(row["pid"]) for row in rows)

    def list_active_capability_use_reservations_for_pids(
        self,
        pids: Iterable[str],
    ) -> list[dict[str, Any]]:
        """Return a bounded, payload-free projection of active reservations."""

        selected = tuple(dict.fromkeys(str(pid) for pid in pids if str(pid)))
        if any(pid != pid.strip() or "\x00" in pid for pid in selected):
            raise ValidationError("TaskRun capability reservation PID scope is invalid")
        if len(selected) > self.config.task_runs.recovery_page_hard_limit:
            raise ValidationError(
                "TaskRun capability reservation PID scope exceeds its hard cap"
            )
        if not selected:
            return []
        hard_limit = (
            self.config.runtime.capability_use_reservation_recovery_page_hard_limit
        )
        rows_by_id: dict[str, Any] = {}
        for offset in range(0, len(selected), 400):
            batch = selected[offset : offset + 400]
            rows = self._query(
                "SELECT reservation.reservation_id, reservation.cap_id, "
                "reservation.count, reservation.status, "
                "reservation.created_at, capability.subject AS pid "
                "FROM capability_use_reservations AS reservation "
                "JOIN capabilities AS capability "
                "ON capability.cap_id = reservation.cap_id "
                "WHERE reservation.status = 'reserved' "
                f"AND capability.subject IN ({', '.join('?' for _ in batch)}) "
                "ORDER BY reservation.created_at COLLATE BINARY, "
                "reservation.reservation_id COLLATE BINARY LIMIT ?",
                (*batch, hard_limit + 1),
            )
            for row in rows:
                rows_by_id[str(row["reservation_id"])] = row
        ordered = sorted(
            rows_by_id.values(),
            key=lambda row: (str(row["created_at"]), str(row["reservation_id"])),
        )
        if len(ordered) > hard_limit:
            raise ValidationError(
                "TaskRun active capability reservations exceed the recovery hard cap"
            )
        records: list[dict[str, Any]] = []
        for row in ordered:
            try:
                count = _positive_capability_use_count(
                    row["count"],
                    label="persisted capability reservation count",
                )
            except ValueError as exc:
                raise ValidationError(str(exc)) from exc
            records.append(
                {
                    "reservation_id": str(row["reservation_id"]),
                    "cap_id": str(row["cap_id"]),
                    "pid": str(row["pid"]),
                    "count": count,
                    "status": "reserved",
                    "created_at": str(row["created_at"]),
                }
            )
        return records

    def purge_task_run_messages(
        self,
        run_id: str,
        linked_pids: Iterable[str],
    ) -> int:
        """Delete only messages with Host-owned metadata for this Run.

        Discovery, deletion, and the zero-row postcondition share the caller's
        transaction.  MessageManager applies ``task_run_id`` to every durable
        inbound message for a Run member, independent of its user channel.
        """

        selected = tuple(dict.fromkeys(str(pid) for pid in linked_pids if str(pid)))
        if any(pid != pid.strip() or "\x00" in pid for pid in selected):
            raise ValidationError("TaskRun message purge PID scope is invalid")
        if len(selected) > self.config.task_runs.recovery_page_hard_limit:
            raise ValidationError("TaskRun message purge PID scope exceeds its hard cap")
        metadata_fragment = f'"task_run_id": {json.dumps(run_id, ensure_ascii=True)}'
        metadata_pattern = f"%{metadata_fragment}%"

        def _is_bound(row: Any) -> bool:
            metadata = loads(row["metadata_json"], {})
            return (
                isinstance(metadata, Mapping)
                and metadata.get("task_run_id") == run_id
            )

        def _candidates(cur: Any) -> list[Any]:
            # Process restore deliberately detaches reconstructed rows from a
            # historical Run.  The Host-owned metadata binding, not the mutable
            # process row, is therefore the durable ownership proof for message
            # purge and its zero-residue postcondition.
            return list(
                cur.execute(
                    "SELECT message_id, metadata_json FROM process_messages "
                    "WHERE metadata_json LIKE ? ORDER BY message_id",
                    (metadata_pattern,),
                )
            )

        with self._join_or_begin_transaction() as cur:
            run = cur.execute(
                "SELECT status FROM task_runs WHERE run_id = ?",
                (run_id,),
            ).fetchone()
            if run is None:
                raise ValidationError("TaskRun message purge requires an existing Run")
            if str(run["status"]) not in {
                "finalizing",
                "succeeded",
                "failed",
                "cancelled",
            }:
                raise ValidationError(
                    "TaskRun messages may only be purged while finalizing or terminal"
                )
            message_ids = [
                str(row["message_id"])
                for row in _candidates(cur)
                if _is_bound(row)
            ]
            deleted = 0
            for offset in range(0, len(message_ids), 400):
                batch = message_ids[offset : offset + 400]
                changed = cur.execute(
                    "DELETE FROM process_messages "
                    f"WHERE message_id IN ({', '.join('?' for _ in batch)})",
                    batch,
                )
                deleted += int(changed.rowcount)
            if any(_is_bound(row) for row in _candidates(cur)):
                raise ValidationError(
                    "TaskRun message purge did not reach its postcondition"
                )
            return deleted

    def purge_task_run_llm_pending_actions(
        self,
        run_id: str,
        linked_pids: Iterable[str],
        *,
        cursor: Any | None = None,
    ) -> int:
        """Delete only pending-action rows owned by a finalizing Run.

        The membership, Run state, deletion, and postcondition are checked in
        one transaction.  When the caller already owns a transaction this
        method joins it, so terminal payload reduction can remain atomic.
        """

        selected = tuple(dict.fromkeys(str(pid) for pid in linked_pids if str(pid)))

        def _purge(cur: Any) -> int:
            run = cur.execute(
                "SELECT status FROM task_runs WHERE run_id = ?",
                (run_id,),
            ).fetchone()
            if run is None:
                raise ValidationError("TaskRun pending-action purge requires an existing Run")
            if str(run["status"]) not in {
                "finalizing",
                "succeeded",
                "failed",
                "cancelled",
            }:
                raise ValidationError(
                    "TaskRun pending actions may only be purged while finalizing or terminal"
                )

            owned_rows = list(
                cur.execute(
                    "SELECT pid FROM processes WHERE task_run_id = ? ORDER BY pid",
                    (run_id,),
                )
            )
            owned = tuple(str(row["pid"]) for row in owned_rows)
            scoped = selected or owned
            if not set(scoped).issubset(owned):
                raise ValidationError(
                    "TaskRun pending-action purge scope contains an unowned PID"
                )
            if not scoped:
                return 0

            deleted = 0
            for offset in range(0, len(scoped), 400):
                batch = scoped[offset : offset + 400]
                placeholders = ", ".join("?" for _ in batch)
                changed = cur.execute(
                    f"DELETE FROM llm_pending_actions WHERE pid IN ({placeholders})",
                    batch,
                )
                deleted += int(changed.rowcount)
                remaining = cur.execute(
                    "SELECT COUNT(*) AS remaining FROM llm_pending_actions "
                    f"WHERE pid IN ({placeholders})",
                    batch,
                ).fetchone()
                if remaining is None or int(remaining["remaining"]) != 0:
                    raise ValidationError(
                        "TaskRun pending-action purge did not reach its postcondition"
                    )
            return deleted

        if cursor is not None:
            return _purge(cursor)
        with self._join_or_begin_transaction() as cur:
            return _purge(cur)

    def list_active_task_run_ids_for_pids(
        self,
        pids: Iterable[str],
    ) -> tuple[str, ...]:
        selected = tuple(dict.fromkeys(str(pid) for pid in pids if str(pid)))
        if not selected:
            return ()
        found: set[str] = set()
        for offset in range(0, len(selected), 400):
            batch = selected[offset : offset + 400]
            rows = self._query(
                "SELECT DISTINCT run.run_id FROM processes AS process "
                "JOIN task_runs AS run ON run.run_id = process.task_run_id "
                f"WHERE process.pid IN ({', '.join('?' for _ in batch)}) "
                "AND run.status NOT IN ('succeeded', 'failed', 'cancelled')",
                batch,
            )
            found.update(str(row["run_id"]) for row in rows)
        return tuple(sorted(found))

    @staticmethod
    def _task_run_page_limit(
        limit: int | None,
        *,
        default: int,
        hard_limit: int,
        label: str,
    ) -> int:
        selected = default if limit is None else limit
        if type(selected) is not int or selected <= 0:
            raise ValidationError(f"{label} limit must be a positive integer")
        if selected > hard_limit:
            raise ValidationError(f"{label} limit exceeds hard cap {hard_limit}")
        return selected

    def insert_authority_manifest(self, manifest: TaskAuthorityManifest) -> None:
        if (
            type(manifest.permitted_effects_policy_schema_version) is not int
            or manifest.permitted_effects_policy_schema_version
            != PERMITTED_EFFECTS_POLICY_SCHEMA_VERSION
            or type(
                manifest.metadata.get(PERMITTED_EFFECTS_POLICY_PROVENANCE_KEY)
            ) is not int
            or manifest.metadata.get(PERMITTED_EFFECTS_POLICY_PROVENANCE_KEY)
            != PERMITTED_EFFECTS_POLICY_SCHEMA_VERSION
        ):
            raise ValidationError(
                "new authority manifests require current effect-policy provenance"
            )
        self._execute(
            """
            INSERT INTO authority_manifests (
                manifest_id, pid, image_id, goal_ref,
                authorized_capabilities_json, required_capabilities_json,
                permitted_effects_json, resource_budget_json,
                approval_policy_json, data_flow_policy_json, expires_at,
                issued_by, parent_manifest_id, manifest_hash, metadata_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                manifest.manifest_id,
                manifest.pid,
                manifest.image_id,
                manifest.goal_ref,
                dumps(manifest.authorized_capabilities),
                dumps(manifest.required_capabilities),
                dumps(encode_permitted_effects_policy(manifest.permitted_effects)),
                dumps(manifest.resource_budget),
                dumps(manifest.approval_policy),
                dumps(manifest.data_flow_policy),
                manifest.expires_at,
                manifest.issued_by,
                manifest.parent_manifest_id,
                manifest.manifest_hash,
                dumps(manifest.metadata),
                manifest.created_at,
            ),
        )

    def get_authority_manifest(self, manifest_id: str) -> TaskAuthorityManifest | None:
        rows = self._query("SELECT * FROM authority_manifests WHERE manifest_id = ?", (manifest_id,))
        return self._row_to_authority_manifest(rows[0]) if rows else None

    def get_authority_manifest_for_process(self, pid: str) -> TaskAuthorityManifest | None:
        rows = self._query("SELECT * FROM authority_manifests WHERE pid = ?", (pid,))
        return self._row_to_authority_manifest(rows[0]) if rows else None

    def list_authority_manifests(
        self,
        *,
        parent_manifest_id: str | None = None,
        limit: int | None = None,
    ) -> list[TaskAuthorityManifest]:
        params: list[Any] = []
        where = ""
        if parent_manifest_id is not None:
            where = " WHERE parent_manifest_id = ?"
            params.append(parent_manifest_id)
        sql = f"SELECT * FROM authority_manifests{where} ORDER BY created_at, manifest_id"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(int(limit))
        return [self._row_to_authority_manifest(row) for row in self._query(sql, params)]

    def claim_runnable_process(self, pid: str) -> AgentProcess | None:
        """Compatibility facade for callers without an execution-owner token."""

        token = self.claim_execution(pid, owner_id="legacy.scheduler")
        if token is None:
            return None
        return self.get_process(pid)

    def claim_execution(
        self,
        pid: str,
        *,
        owner_id: str,
        task_run_epoch: int | None = None,
    ) -> ProcessExecutionToken | None:
        if not owner_id:
            raise ValidationError("execution owner id must be non-empty")
        if task_run_epoch is not None and (
            type(task_run_epoch) is not int or task_run_epoch <= 0
        ):
            raise ValidationError("execution TaskRun epoch must be positive")
        now = utc_now()
        lease_id = new_id("execution_lease")
        # Do not bind a nullable value solely through ``? IS NULL`` here.
        # PostgreSQL cannot infer that placeholder's type, while omitting this
        # optional predicate is exactly the legacy/no-explicit-epoch behavior.
        # A supplied epoch remains compared to the BIGINT process column, and
        # the TaskRun join below always fences a bound process to the current
        # Run epoch.
        task_run_epoch_sql = (
            "" if task_run_epoch is None else "AND task_run_epoch = ?"
        )
        task_run_epoch_params: tuple[int, ...] = (
            () if task_run_epoch is None else (task_run_epoch,)
        )
        with self.transaction() as cur:
            rows = list(
                cur.execute(
                    """
                    SELECT revision, execution_generation, state_generation,
                           task_run_epoch
                      FROM processes
                     WHERE pid = ? AND status = ?
                    """,
                    (pid, ProcessStatus.RUNNABLE.value),
                )
            )
            if not rows:
                return None
            generation = int(rows[0]["execution_generation"]) + 1
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET status = ?, updated_at = ?, revision = revision + 1,
                       status_message = NULL, wait_state_json = 'null',
                       outcome_json = 'null', state_generation = state_generation + 1,
                       execution_generation = ?, execution_owner_id = ?, execution_lease_id = ?
                 WHERE pid = ? AND status = ?
                   AND execution_generation = ?
                   {task_run_epoch_sql}
                   AND (
                     task_run_id IS NULL OR EXISTS (
                       SELECT 1 FROM task_runs AS task_run
                        WHERE task_run.run_id = processes.task_run_id
                          AND task_run.runtime_epoch = processes.task_run_epoch
                          AND task_run.status IN (
                            'queued', 'running', 'waiting_human',
                            'waiting_process', 'waiting_message', 'waiting_tool'
                          )
                          AND (
                            task_run.deadline_at IS NULL OR task_run.deadline_at > ?
                          )
                     )
                   )
                """,
                (
                    ProcessStatus.RUNNING.value,
                    now,
                    generation,
                    owner_id,
                    lease_id,
                    pid,
                    ProcessStatus.RUNNABLE.value,
                    generation - 1,
                    *task_run_epoch_params,
                    now,
                ),
            )
            if updated.rowcount != 1:
                return None
            self.observe_process_concurrency(
                pid,
                revision=int(rows[0]["revision"]) + 1,
                execution_generation=generation,
                state_generation=(
                    int(rows[0]["state_generation"]) + 1
                    if "state_generation" in rows[0].keys()
                    else 1
                ),
                cursor=cur,
            )
            return ProcessExecutionToken(
                pid=pid,
                generation=generation,
                owner_id=owner_id,
                lease_id=lease_id,
                task_run_epoch=(
                    int(rows[0]["task_run_epoch"])
                    if rows[0]["task_run_epoch"] is not None
                    else None
                ),
            )

    def claim_host_process_exec(
        self,
        pid: str,
        *,
        owner_id: str,
        expected_revision: int,
        expected_state_generation: int,
        expected_execution_generation: int,
        task_run_epoch: int | None = None,
    ) -> ProcessExecutionToken | None:
        """Claim a RUNNABLE row for Host exec using its complete concurrency tuple.

        ImageBoot captures the rollback snapshot and invokes this CAS inside one
        transaction.  A scheduler claim or state transition that wins between
        preflight and this boundary therefore prevents publication admission;
        the losing exec never owns a snapshot that it may replay.
        """

        if not owner_id:
            raise ValidationError("process exec owner id must be non-empty")
        expected = (
            expected_revision,
            expected_state_generation,
            expected_execution_generation,
        )
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value < 0
            for value in expected
        ):
            raise ValidationError(
                "process exec concurrency values must be non-negative integers"
            )
        generation = expected_execution_generation + 1
        if task_run_epoch is not None and (
            type(task_run_epoch) is not int or task_run_epoch <= 0
        ):
            raise ValidationError("process exec TaskRun epoch must be positive")
        lease_id = new_id("execution_lease")
        task_run_epoch_sql = (
            "" if task_run_epoch is None else "AND task_run_epoch = ?"
        )
        task_run_epoch_params: tuple[int, ...] = (
            () if task_run_epoch is None else (task_run_epoch,)
        )
        with self.transaction() as cur:
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET status = ?, updated_at = ?, revision = revision + 1,
                       status_message = NULL, wait_state_json = 'null',
                       outcome_json = 'null', state_generation = state_generation + 1,
                       execution_generation = ?, execution_owner_id = ?, execution_lease_id = ?
                 WHERE pid = ? AND status = ? AND revision = ?
                   AND state_generation = ? AND execution_generation = ?
                   AND execution_owner_id IS NULL AND execution_lease_id IS NULL
                   AND wait_state_json = 'null'
                   {task_run_epoch_sql}
                   AND (
                     task_run_id IS NULL OR EXISTS (
                       SELECT 1 FROM task_runs AS task_run
                        WHERE task_run.run_id = processes.task_run_id
                          AND task_run.runtime_epoch = processes.task_run_epoch
                          AND task_run.status IN (
                            'queued', 'running', 'waiting_human',
                            'waiting_process', 'waiting_message', 'waiting_tool'
                          )
                          AND (task_run.deadline_at IS NULL OR task_run.deadline_at > ?)
                     )
                   )
                """,
                (
                    ProcessStatus.RUNNING.value,
                    utc_now(),
                    generation,
                    owner_id,
                    lease_id,
                    pid,
                    ProcessStatus.RUNNABLE.value,
                    expected_revision,
                    expected_state_generation,
                    expected_execution_generation,
                    *task_run_epoch_params,
                    utc_now(),
                ),
            )
            if updated.rowcount != 1:
                return None
            self.observe_process_concurrency(
                pid,
                revision=expected_revision + 1,
                execution_generation=generation,
                state_generation=expected_state_generation + 1,
                cursor=cur,
            )
            claimed_row = cur.execute(
                "SELECT task_run_epoch FROM processes WHERE pid = ?", (pid,)
            ).fetchone()
        return ProcessExecutionToken(
            pid=pid,
            generation=generation,
            owner_id=owner_id,
            lease_id=lease_id,
            task_run_epoch=(
                int(claimed_row["task_run_epoch"])
                if claimed_row is not None
                and claimed_row["task_run_epoch"] is not None
                else None
            ),
        )

    def claim_worker_process_exec(
        self,
        pid: str,
        *,
        execution_token: ProcessExecutionToken,
        owner_id: str,
        expected_revision: int,
        expected_state_generation: int,
        task_run_epoch: int | None = None,
    ) -> ProcessExecutionToken | None:
        """Atomically rotate an exact worker lease into exec-owned admission.

        The old worker token is invalid as soon as this CAS commits.  Exec then
        runs under the returned internal token, so a concurrent quantum
        completion either wins before admission (and prevents publication) or
        loses without being revivable by snapshot compensation.
        """

        if not owner_id:
            raise ValidationError("process exec owner id must be non-empty")
        if execution_token.pid != pid:
            raise ValidationError(
                f"process execution token for {execution_token.pid} cannot exec {pid}"
            )
        expected = (
            expected_revision,
            expected_state_generation,
            execution_token.generation,
        )
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value < 0
            for value in expected
        ):
            raise ValidationError(
                "process exec concurrency values must be non-negative integers"
            )
        generation = execution_token.generation + 1
        if task_run_epoch is not None and (
            type(task_run_epoch) is not int or task_run_epoch <= 0
        ):
            raise ValidationError("process exec TaskRun epoch must be positive")
        lease_id = new_id("execution_lease")
        task_run_epoch_sql = (
            "" if task_run_epoch is None else "AND task_run_epoch = ?"
        )
        task_run_epoch_params: tuple[int, ...] = (
            () if task_run_epoch is None else (task_run_epoch,)
        )
        with self.transaction() as cur:
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET updated_at = ?, revision = revision + 1,
                       status_message = NULL, wait_state_json = 'null',
                       outcome_json = 'null', state_generation = state_generation + 1,
                       execution_generation = ?, execution_owner_id = ?, execution_lease_id = ?
                 WHERE pid = ? AND status = ? AND revision = ?
                   AND state_generation = ? AND execution_generation = ?
                   AND execution_owner_id = ? AND execution_lease_id = ?
                   AND wait_state_json = 'null'
                   {task_run_epoch_sql}
                   AND (
                     task_run_id IS NULL OR EXISTS (
                       SELECT 1 FROM task_runs AS task_run
                        WHERE task_run.run_id = processes.task_run_id
                          AND task_run.runtime_epoch = processes.task_run_epoch
                          AND task_run.status IN (
                            'queued', 'running', 'waiting_human',
                            'waiting_process', 'waiting_message', 'waiting_tool'
                          )
                          AND (task_run.deadline_at IS NULL OR task_run.deadline_at > ?)
                     )
                   )
                """,
                (
                    utc_now(),
                    generation,
                    owner_id,
                    lease_id,
                    pid,
                    ProcessStatus.RUNNING.value,
                    expected_revision,
                    expected_state_generation,
                    execution_token.generation,
                    execution_token.owner_id,
                    execution_token.lease_id,
                    *task_run_epoch_params,
                    utc_now(),
                ),
            )
            if updated.rowcount != 1:
                return None
            self.observe_process_concurrency(
                pid,
                revision=expected_revision + 1,
                execution_generation=generation,
                state_generation=expected_state_generation + 1,
                cursor=cur,
            )
            claimed_row = cur.execute(
                "SELECT task_run_epoch FROM processes WHERE pid = ?", (pid,)
            ).fetchone()
        return ProcessExecutionToken(
            pid=pid,
            generation=generation,
            owner_id=owner_id,
            lease_id=lease_id,
            task_run_epoch=(
                int(claimed_row["task_run_epoch"])
                if claimed_row is not None
                and claimed_row["task_run_epoch"] is not None
                else None
            ),
        )

    def complete_execution(
        self,
        token: ProcessExecutionToken,
        *,
        status: ProcessStatus | str = ProcessStatus.RUNNABLE,
        status_message: str | None = None,
        wait_state: ProcessWaitState | None = None,
        outcome: ProcessOutcome | None = None,
    ) -> bool:
        """Complete only the exact claimed generation/owner/lease."""

        selected = ProcessStatus(status)
        validate_process_state_fields(selected.value, wait_state, outcome)
        if isinstance(wait_state, StaleExecutionProcessWait):
            raise ValidationError(
                "stale-execution recovery receipts are reserved for Store recovery"
            )
        selected_status_message = legacy_status_message(
            wait_state,
            outcome,
            status_message,
        )
        wait_state_json = dumps(process_wait_state_to_mapping(wait_state))
        outcome_json = dumps(process_outcome_to_mapping(outcome))
        task_run_epoch_sql = (
            "AND task_run_epoch IS NULL"
            if token.task_run_epoch is None
            else "AND task_run_epoch = ?"
        )
        task_run_epoch_params: tuple[int, ...] = (
            () if token.task_run_epoch is None else (token.task_run_epoch,)
        )
        generation_increment = 1 if selected in {
            ProcessStatus.EXITED,
            ProcessStatus.FAILED,
            ProcessStatus.KILLED,
        } else 0
        with self.transaction() as cur:
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET status = ?, status_message = ?, wait_state_json = ?,
                       outcome_json = ?, state_generation = state_generation + 1,
                       updated_at = ?, revision = revision + 1,
                       execution_generation = execution_generation + ?,
                       execution_owner_id = NULL, execution_lease_id = NULL
                 WHERE pid = ? AND status = ? AND execution_generation = ?
                   AND execution_owner_id = ? AND execution_lease_id = ?
                   {task_run_epoch_sql}
                """,
                (
                    selected.value,
                    selected_status_message,
                    wait_state_json,
                    outcome_json,
                    utc_now(),
                    generation_increment,
                    token.pid,
                    ProcessStatus.RUNNING.value,
                    token.generation,
                    token.owner_id,
                    token.lease_id,
                    *task_run_epoch_params,
                ),
            )
            if updated.rowcount != 1:
                return False
            self._ensure_process_terminal_cleanup_intent(
                cur,
                pid=token.pid,
                status=selected,
            )
            rows = list(
                cur.execute(
                    """
                    SELECT revision, execution_generation, state_generation
                      FROM processes WHERE pid = ?
                    """,
                    (token.pid,),
                )
            )
            self.observe_process_concurrency(
                token.pid,
                revision=int(rows[0]["revision"]),
                execution_generation=int(rows[0]["execution_generation"]),
                state_generation=int(rows[0]["state_generation"]),
                cursor=cur,
            )
            return True

    def release_execution(self, token: ProcessExecutionToken) -> bool:
        """Fence and detach an exact execution lease without changing status."""

        task_run_epoch_sql = (
            "AND task_run_epoch IS NULL"
            if token.task_run_epoch is None
            else "AND task_run_epoch = ?"
        )
        task_run_epoch_params: tuple[int, ...] = (
            () if token.task_run_epoch is None else (token.task_run_epoch,)
        )
        with self.transaction() as cur:
            updated = cur.execute(
                f"""
                UPDATE processes
                   SET updated_at = ?, revision = revision + 1,
                       execution_generation = execution_generation + 1,
                       execution_owner_id = NULL, execution_lease_id = NULL
                 WHERE pid = ? AND execution_generation = ?
                   AND execution_owner_id = ? AND execution_lease_id = ?
                   {task_run_epoch_sql}
                """,
                (
                    utc_now(),
                    token.pid,
                    token.generation,
                    token.owner_id,
                    token.lease_id,
                    *task_run_epoch_params,
                ),
            )
            if updated.rowcount != 1:
                return False
            rows = list(
                cur.execute(
                    "SELECT revision, execution_generation FROM processes WHERE pid = ?",
                    (token.pid,),
                )
            )
            self.observe_process_concurrency(
                token.pid,
                revision=int(rows[0]["revision"]),
                execution_generation=int(rows[0]["execution_generation"]),
                cursor=cur,
            )
            return True

    @staticmethod
    def _process_terminal_cleanup_from_row(row: Any) -> dict[str, Any]:
        completed = loads(row["completed_phases_json"], [])
        error = loads(row["last_error_json"], None)
        if (
            not isinstance(completed, list)
            or any(not isinstance(phase, str) for phase in completed)
            or any(phase not in _PROCESS_TERMINAL_CLEANUP_PHASES for phase in completed)
            or len(completed) != len(set(completed))
            or completed
            != [
                phase
                for phase in _PROCESS_TERMINAL_CLEANUP_PHASES
                if phase in completed
            ]
        ):
            raise ValidationError(
                f"process terminal cleanup phases are invalid: {row['pid']}"
            )
        if error is not None and not isinstance(error, dict):
            raise ValidationError(
                f"process terminal cleanup error is invalid: {row['pid']}"
            )
        return {
            "pid": str(row["pid"]),
            "terminal_status": str(row["terminal_status"]),
            "state": str(row["state"]),
            "completed_phases": list(completed),
            "attempt_count": int(row["attempt_count"]),
            "owner_id": row["owner_id"],
            "lease_id": row["lease_id"],
            "failed_phase": row["failed_phase"],
            "last_error": error,
            "created_at": str(row["created_at"]),
            "updated_at": str(row["updated_at"]),
        }

    def get_process_terminal_cleanup(self, pid: str) -> dict[str, Any] | None:
        rows = self._query(
            "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
            (pid,),
        )
        if not rows:
            return None
        return self._process_terminal_cleanup_from_row(rows[0])

    def list_process_terminal_cleanups(
        self,
        *,
        after: ProcessCursor | None,
        limit: int,
        include_completed: bool = False,
    ) -> list[dict[str, Any]]:
        if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
            raise ValidationError(
                "process terminal cleanup recovery limit must be a positive integer"
            )
        hard_limit = (
            self.config.runtime.process_terminal_cleanup_recovery_page_hard_limit
        )
        if limit > hard_limit:
            raise ValidationError(
                "process terminal cleanup recovery limit exceeds configured hard cap: "
                f"{limit} > {hard_limit}"
            )
        if after is not None and not isinstance(after, ProcessCursor):
            raise ValidationError(
                "process terminal cleanup recovery cursor has an invalid type"
            )
        clauses: list[str] = []
        params: list[Any] = []
        if not include_completed:
            clauses.append("state != ?")
            params.append("completed")
        if after is not None:
            clauses.append("(created_at, pid) > (?, ?)")
            params.extend((after.created_at, after.pid))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(limit)
        sql = (
            f"SELECT * FROM process_terminal_cleanups{where} "
            "ORDER BY created_at COLLATE BINARY, pid COLLATE BINARY LIMIT ?"
        )
        return [
            self._process_terminal_cleanup_from_row(row)
            for row in self._query(sql, params)
        ]

    def claim_process_terminal_cleanup(
        self,
        pid: str,
        *,
        owner_id: str,
        lease_id: str,
        expected_lease_id: str | None,
    ) -> dict[str, Any] | None:
        if not owner_id or not lease_id:
            raise ValidationError(
                "process terminal cleanup owner and lease must be non-empty"
            )
        lease_clause = "lease_id IS NULL" if expected_lease_id is None else "lease_id = ?"
        lease_params: tuple[Any, ...] = () if expected_lease_id is None else (expected_lease_id,)
        with self.transaction() as cur:
            updated = cur.execute(
                f"""
                UPDATE process_terminal_cleanups
                   SET state = 'running', owner_id = ?, lease_id = ?,
                       attempt_count = attempt_count + 1,
                       failed_phase = NULL, last_error_json = NULL,
                       updated_at = ?
                 WHERE pid = ? AND state != 'completed' AND {lease_clause}
                """,
                (
                    owner_id,
                    lease_id,
                    utc_now(),
                    pid,
                    *lease_params,
                ),
            )
            if updated.rowcount != 1:
                return None
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            return self._process_terminal_cleanup_from_row(rows[0])

    def complete_process_terminal_cleanup_phase(
        self,
        pid: str,
        *,
        lease_id: str,
        phase: str,
    ) -> dict[str, Any] | None:
        if phase not in _PROCESS_TERMINAL_CLEANUP_PHASES:
            raise ValidationError(f"invalid process terminal cleanup phase: {phase}")
        with self.transaction() as cur:
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            if not rows:
                return None
            current = self._process_terminal_cleanup_from_row(rows[0])
            if current["state"] != "running" or current["lease_id"] != lease_id:
                return None
            completed = list(current["completed_phases"])
            if phase not in completed:
                completed.append(phase)
                completed = [
                    candidate
                    for candidate in _PROCESS_TERMINAL_CLEANUP_PHASES
                    if candidate in completed
                ]
                updated = cur.execute(
                    """
                    UPDATE process_terminal_cleanups
                       SET completed_phases_json = ?, updated_at = ?
                     WHERE pid = ? AND state = 'running' AND lease_id = ?
                    """,
                    (dumps(completed), utc_now(), pid, lease_id),
                )
                if updated.rowcount != 1:
                    return None
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            return self._process_terminal_cleanup_from_row(rows[0])

    def fail_process_terminal_cleanup(
        self,
        pid: str,
        *,
        lease_id: str,
        phase: str,
        error: Mapping[str, Any],
    ) -> dict[str, Any] | None:
        if phase not in _PROCESS_TERMINAL_CLEANUP_PHASES:
            raise ValidationError(f"invalid process terminal cleanup phase: {phase}")
        with self.transaction() as cur:
            updated = cur.execute(
                """
                UPDATE process_terminal_cleanups
                   SET state = 'failed', owner_id = NULL, lease_id = NULL,
                       failed_phase = ?, last_error_json = ?, updated_at = ?
                 WHERE pid = ? AND state = 'running' AND lease_id = ?
                """,
                (phase, dumps(dict(error)), utc_now(), pid, lease_id),
            )
            if updated.rowcount != 1:
                return None
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            return self._process_terminal_cleanup_from_row(rows[0])

    def finish_process_terminal_cleanup(
        self,
        pid: str,
        *,
        lease_id: str,
    ) -> dict[str, Any] | None:
        with self.transaction() as cur:
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            if not rows:
                return None
            current = self._process_terminal_cleanup_from_row(rows[0])
            if (
                current["state"] != "running"
                or current["lease_id"] != lease_id
                or current["completed_phases"]
                != list(_PROCESS_TERMINAL_CLEANUP_PHASES)
            ):
                return None
            updated = cur.execute(
                """
                UPDATE process_terminal_cleanups
                   SET state = 'completed', owner_id = NULL, lease_id = NULL,
                       failed_phase = NULL, last_error_json = NULL, updated_at = ?
                 WHERE pid = ? AND state = 'running' AND lease_id = ?
                """,
                (utc_now(), pid, lease_id),
            )
            if updated.rowcount != 1:
                return None
            rows = list(
                cur.execute(
                    "SELECT * FROM process_terminal_cleanups WHERE pid = ?",
                    (pid,),
                )
            )
            return self._process_terminal_cleanup_from_row(rows[0])

    def recover_stale_executions(
        self,
        *,
        owner_id: str,
        require_recovery_lease: Callable[[], None],
        on_recovered: Callable[[str], None],
    ) -> StaleExecutionRecoverySummary:
        """Fail closed persisted RUNNING rows owned by an earlier Runtime."""

        require_recovery_lease()
        if not callable(on_recovered):
            raise TypeError("stale execution recovery callback must be callable")
        page_size = self.config.runtime.operation_recovery_page_size
        recovered_total = 0
        recovered_sample: list[str] = []
        after_pid: str | None = None
        while True:
            with self.transaction() as cur:
                params: list[Any] = [ProcessStatus.RUNNING.value, owner_id]
                after_clause = ""
                if after_pid is not None:
                    after_clause = " AND pid > ?"
                    params.append(after_pid)
                params.append(page_size)
                rows = list(
                    cur.execute(
                        f"""
                        SELECT pid, state_generation, execution_generation,
                               execution_owner_id, execution_lease_id
                          FROM processes
                         WHERE status = ?
                           AND (execution_owner_id IS NULL OR execution_owner_id <> ?)
                           {after_clause}
                         ORDER BY pid
                         LIMIT ?
                        """,
                        params,
                    )
                )
                pids = [str(row["pid"]) for row in rows]
                if not pids:
                    break
                recovered_pids: list[str] = []
                now = utc_now()
                recovered_by_owner_sha256 = hashlib.sha256(
                    owner_id.encode("utf-8")
                ).hexdigest()
                for row in rows:
                    recovered_pid = self._recover_one_stale_execution(
                        cur,
                        row,
                        owner_id=owner_id,
                        recovered_by_owner_sha256=recovered_by_owner_sha256,
                        recovered_at=now,
                    )
                    if recovered_pid is not None:
                        recovered_pids.append(recovered_pid)
                if not recovered_pids:
                    after_pid = pids[-1]
                    continue
                placeholders = ", ".join("?" for _ in recovered_pids)
                concurrency_rows = list(
                    cur.execute(
                        f"""
                        SELECT pid, revision, execution_generation, state_generation
                          FROM processes
                         WHERE pid IN ({placeholders})
                        """,
                        recovered_pids,
                    )
                )
                for row in concurrency_rows:
                    self.observe_process_concurrency(
                        str(row["pid"]),
                        revision=int(row["revision"]),
                        execution_generation=int(row["execution_generation"]),
                        state_generation=int(row["state_generation"]),
                        cursor=cur,
                    )
                for pid in recovered_pids:
                    on_recovered(pid)
                recovered_total += len(recovered_pids)
                if len(recovered_sample) < page_size:
                    recovered_sample.extend(
                        recovered_pids[: page_size - len(recovered_sample)]
                    )
                after_pid = pids[-1]
        return StaleExecutionRecoverySummary(
            total_count=recovered_total,
            sample_pids=tuple(recovered_sample),
        )

    @staticmethod
    def _stale_execution_identity_sha256(value: Any) -> str | None:
        if not isinstance(value, str) or not value:
            return None
        return hashlib.sha256(value.encode("utf-8")).hexdigest()

    def _recover_one_stale_execution(
        self,
        cursor: Any,
        row: Any,
        *,
        owner_id: str,
        recovered_by_owner_sha256: str,
        recovered_at: str,
    ) -> str | None:
        """CAS one selected lease and its hash-only receipt in one statement."""

        pid = str(row["pid"])
        prior_owner = row["execution_owner_id"]
        prior_lease = row["execution_lease_id"]
        prior_state_generation = int(row["state_generation"])
        prior_execution_generation = int(row["execution_generation"])
        receipt = StaleExecutionProcessWait(
            pid=pid,
            recovered_by_owner_sha256=recovered_by_owner_sha256,
            prior_owner_sha256=self._stale_execution_identity_sha256(prior_owner),
            prior_lease_sha256=self._stale_execution_identity_sha256(prior_lease),
            prior_execution_generation=prior_execution_generation,
            recovered_execution_generation=prior_execution_generation + 1,
            recovered_state_generation=prior_state_generation + 1,
        )
        owner_clause = (
            "execution_owner_id IS NULL"
            if prior_owner is None
            else "execution_owner_id = ?"
        )
        lease_clause = (
            "execution_lease_id IS NULL"
            if prior_lease is None
            else "execution_lease_id = ?"
        )
        identity_params = (
            (() if prior_owner is None else (prior_owner,))
            + (() if prior_lease is None else (prior_lease,))
        )
        updated = cursor.execute(
            f"""
            UPDATE processes
               SET status = ?, status_message = ?, updated_at = ?,
                   wait_state_json = ?, outcome_json = 'null',
                   state_generation = state_generation + 1,
                   revision = revision + 1,
                   execution_generation = execution_generation + 1,
                   execution_owner_id = NULL,
                   execution_lease_id = NULL
             WHERE pid = ? AND status = ?
               AND state_generation = ?
               AND execution_generation = ?
               AND {owner_clause}
               AND {lease_clause}
               AND (
                 execution_owner_id IS NULL
                 OR execution_owner_id <> ?
               )
            """,
            (
                ProcessStatus.PAUSED.value,
                legacy_status_message(receipt, None),
                recovered_at,
                dumps(process_wait_state_to_mapping(receipt)),
                pid,
                ProcessStatus.RUNNING.value,
                prior_state_generation,
                prior_execution_generation,
                *identity_params,
                owner_id,
            ),
        )
        return pid if updated.rowcount == 1 else None

    def upsert_resource_reservation(self, reservation: ResourceReservation) -> None:
        self._execute(
            """
            INSERT INTO process_resource_reservations (
                parent_pid, child_pid, reservation_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(parent_pid, child_pid) DO UPDATE SET
                reservation_json = excluded.reservation_json,
                updated_at = excluded.updated_at
            """,
            (
                reservation.parent_pid,
                reservation.child_pid,
                dumps(reservation.reserved),
                reservation.created_at,
                reservation.updated_at,
            ),
        )

    def get_resource_reservation(self, parent_pid: str, child_pid: str) -> ResourceReservation | None:
        rows = self._query(
            "SELECT * FROM process_resource_reservations WHERE parent_pid = ? AND child_pid = ?",
            (parent_pid, child_pid),
        )
        return self._row_to_resource_reservation(rows[0]) if rows else None

    def insert_resource_usage_reservation(
        self,
        *,
        reservation_id: str,
        pid: str,
        usage: ResourceUsage,
        reserved_by: str,
        reason: str,
        created_at: str,
    ) -> None:
        self._execute(
            """
            INSERT INTO resource_usage_reservations (
                reservation_id, pid, usage_json, status, reserved_by, reason,
                settled_usage_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                reservation_id,
                pid,
                dumps(usage),
                "active",
                reserved_by,
                reason,
                None,
                created_at,
                created_at,
            ),
        )

    def get_resource_usage_reservation(self, reservation_id: str) -> dict[str, Any] | None:
        rows = self._query(
            "SELECT * FROM resource_usage_reservations WHERE reservation_id = ?",
            (reservation_id,),
        )
        return self._resource_usage_reservation_row(rows[0]) if rows else None

    def list_resource_usage_reservations(
        self,
        *,
        pid: str | None = None,
        status: str | None = None,
    ) -> list[dict[str, Any]]:
        clauses: list[str] = []
        params: list[Any] = []
        if pid is not None:
            clauses.append("pid = ?")
            params.append(pid)
        if status is not None:
            clauses.append("status = ?")
            params.append(status)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = self._query(
            f"SELECT * FROM resource_usage_reservations{where} "
            "ORDER BY created_at, reservation_id",
            params,
        )
        return [self._resource_usage_reservation_row(row) for row in rows]

    def query_resource_usage_reservation_recovery(
        self,
        *,
        after: ResourceUsageReservationCursor | None,
        limit: int,
    ) -> ResourceUsageReservationPage:
        """Return one stable, hard-bounded page of active reservations."""

        selected_limit = self._resource_usage_reservation_recovery_limit(limit)
        clauses = ["status = ?"]
        params: list[Any] = [ResourceUsageReservationStatus.ACTIVE.value]
        if after is not None:
            if not isinstance(after, ResourceUsageReservationCursor):
                raise ValidationError(
                    "resource usage reservation recovery cursor has an invalid type"
                )
            clauses.append("(created_at, reservation_id) > (?, ?)")
            params.extend((after.created_at, after.reservation_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM resource_usage_reservations "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at, reservation_id LIMIT ?",
            params,
        )
        records = tuple(
            self._row_to_resource_usage_reservation(row)
            for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit:
            last = records[-1]
            next_cursor = ResourceUsageReservationCursor(
                last.created_at,
                last.reservation_id,
            )
        return ResourceUsageReservationPage(
            records=records,
            next_cursor=next_cursor,
        )

    def settle_resource_usage_reservation(
        self,
        reservation_id: str,
        *,
        status: str,
        settled_usage: ResourceUsage,
        updated_at: str,
    ) -> bool:
        if status not in {"settled", "released", "charged_maximum"}:
            raise ValidationError(f"invalid resource usage reservation status: {status}")
        cur = self._execute(
            """
            UPDATE resource_usage_reservations
               SET status = ?, settled_usage_json = ?, updated_at = ?
             WHERE reservation_id = ? AND status = ?
            """,
            (status, dumps(settled_usage), updated_at, reservation_id, "active"),
        )
        return cur.rowcount == 1

    @staticmethod
    def _resource_usage_reservation_row(row: Any) -> dict[str, Any]:
        return {
            "reservation_id": str(row["reservation_id"]),
            "pid": str(row["pid"]),
            "usage": ResourceUsage(**loads(row["usage_json"], {})),
            "status": str(row["status"]),
            "reserved_by": str(row["reserved_by"]),
            "reason": str(row["reason"]),
            "settled_usage": (
                ResourceUsage(**loads(row["settled_usage_json"], {}))
                if row["settled_usage_json"]
                else None
            ),
            "created_at": str(row["created_at"]),
            "updated_at": str(row["updated_at"]),
        }

    @staticmethod
    def _row_to_resource_usage_reservation(
        row: Any,
    ) -> ResourceUsageReservation:
        with _persisted_model_decode(
            f"resource usage reservation {row['reservation_id']}"
        ):
            return ResourceUsageReservation(
                reservation_id=str(row["reservation_id"]),
                pid=str(row["pid"]),
                usage=ResourceUsage(**loads(row["usage_json"], {})),
                status=ResourceUsageReservationStatus(str(row["status"])),
                reserved_by=str(row["reserved_by"]),
                reason=str(row["reason"]),
                settled_usage=(
                    ResourceUsage(**loads(row["settled_usage_json"], {}))
                    if row["settled_usage_json"]
                    else None
                ),
                created_at=str(row["created_at"]),
                updated_at=str(row["updated_at"]),
            )

    def get_jit_rehydration_artifacts(
        self,
        *,
        pid: str,
        tool_ids: Iterable[str],
    ) -> tuple[JITRehydrationArtifact, ...]:
        """Read only requested ephemeral tools and their exact owner candidates."""

        if not isinstance(pid, str) or not pid or "\x00" in pid:
            raise ValidationError("JIT rehydration requires a valid process identity")
        return self.get_jit_rehydration_artifacts_for_tool_ids(tool_ids)

    def get_jit_rehydration_artifacts_for_tool_ids(
        self,
        tool_ids: Iterable[str],
    ) -> tuple[JITRehydrationArtifact, ...]:
        """Bulk-read one hard-bounded page of exact ephemeral Tool artifacts."""

        selected_ids = self._validated_jit_rehydration_tool_ids(tool_ids)
        if not selected_ids:
            return ()

        tool_rows = self._query_jit_rehydration_tool_rows(selected_ids)
        if not tool_rows:
            return ()

        ephemeral_ids = sorted(str(row["tool_id"]) for row in tool_rows)
        # Do not predicate candidates by the requesting pid: returning the
        # exact durable owner is what lets configuration and startup reject a
        # cross-process alias instead of mistaking it for missing metadata.
        candidate_counts, first_candidates = (
            self._query_jit_rehydration_candidate_rows(
                tool_ids=ephemeral_ids,
                expected_ids=frozenset(selected_ids),
            )
        )
        return tuple(
            self._jit_rehydration_artifact_from_row(
                row,
                candidate_counts=candidate_counts,
                first_candidates=first_candidates,
            )
            for row in tool_rows
        )

    def delete_jit_tool_rows(
        self,
        pid: str,
        tool_ids: Iterable[str],
    ) -> None:
        """Atomically delete one process's exact ephemeral JIT artifacts.

        The durable binding eligibility column is a derived projection. Clear
        bindings for the exact requested identities, then delete only matching
        ephemeral Tool rows and owner-candidate rows in bounded set-based
        statements. This avoids one transaction per tool identity and also
        repairs an impossible stale-positive projection for a missing/static
        Tool row.
        """

        if not isinstance(pid, str) or not pid or "\x00" in pid:
            raise ValidationError("JIT tool deletion requires a valid process identity")
        if isinstance(tool_ids, (str, bytes, bytearray)):
            raise ValidationError("JIT tool deletion IDs must be an iterable")
        selected_ids: set[str] = set()
        for tool_id in tool_ids:
            if not isinstance(tool_id, str) or not tool_id or "\x00" in tool_id:
                raise ValidationError(
                    "JIT tool deletion IDs must be non-empty text"
                )
            selected_ids.add(tool_id)
        if not selected_ids:
            return

        ordered_ids = tuple(sorted(selected_ids))
        with self.transaction() as cursor:
            for offset in range(0, len(ordered_ids), _TOOL_ID_LOOKUP_BATCH_SIZE):
                batch = ordered_ids[
                    offset : offset + _TOOL_ID_LOOKUP_BATCH_SIZE
                ]
                placeholders = ", ".join("?" for _ in batch)
                cursor.execute(
                    "UPDATE process_tool_bindings "
                    "SET jit_rehydration_eligible = 0 "
                    "WHERE jit_rehydration_eligible = 1 "
                    f"AND tool_id IN ({placeholders})",
                    batch,
                )
                cursor.execute(
                    "DELETE FROM tools WHERE ephemeral = 1 "
                    f"AND tool_id IN ({placeholders})",
                    batch,
                )
                cursor.execute(
                    "DELETE FROM tool_candidates WHERE pid = ? "
                    f"AND registered_tool_id IN ({placeholders})",
                    (pid, *batch),
                )

    def _validated_jit_rehydration_tool_ids(
        self,
        tool_ids: Iterable[str],
    ) -> tuple[str, ...]:
        if isinstance(tool_ids, (str, bytes, bytearray)):
            raise ValidationError("JIT rehydration tool IDs must be an iterable")
        hard_limit = self.config.runtime.jit_rehydration_page_hard_limit
        selected_ids: set[str] = set()
        for item_count, tool_id in enumerate(tool_ids, start=1):
            if item_count > hard_limit:
                raise ValidationError(
                    "JIT rehydration tool ID batch exceeds configured hard cap: "
                    f"> {hard_limit}"
                )
            if not isinstance(tool_id, str) or not tool_id or "\x00" in tool_id:
                raise ValidationError(
                    "JIT rehydration tool IDs must be non-empty text"
                )
            selected_ids.add(tool_id)
        return tuple(sorted(selected_ids))

    def _query_jit_rehydration_tool_rows(
        self,
        tool_ids: tuple[str, ...],
    ) -> list[Any]:
        tool_rows: list[Any] = []
        for offset in range(0, len(tool_ids), _TOOL_ID_LOOKUP_BATCH_SIZE):
            batch = tool_ids[offset : offset + _TOOL_ID_LOOKUP_BATCH_SIZE]
            placeholders = ", ".join("?" for _ in batch)
            tool_rows.extend(
                self._query(
                    "SELECT tool_id, name, scope FROM tools "
                    f"WHERE ephemeral = 1 AND tool_id IN ({placeholders}) "
                    "ORDER BY tool_id",
                    batch,
                )
            )
        return tool_rows

    def _query_jit_rehydration_candidate_rows(
        self,
        *,
        tool_ids: list[str],
        expected_ids: frozenset[str],
    ) -> tuple[dict[str, int], dict[str, Any]]:
        hard_limit = self.config.runtime.jit_rehydration_page_hard_limit
        candidate_counts: dict[str, int] = {}
        first_candidates: dict[str, Any] = {}
        candidate_row_total = 0
        for offset in range(0, len(tool_ids), _TOOL_ID_LOOKUP_BATCH_SIZE):
            batch = tool_ids[offset : offset + _TOOL_ID_LOOKUP_BATCH_SIZE]
            placeholders = ", ".join("?" for _ in batch)
            remaining = hard_limit - candidate_row_total
            rows = self._query(
                "SELECT registered_tool_id, candidate_id, pid, source_code "
                "FROM tool_candidates "
                f"WHERE registered_tool_id IN ({placeholders}) "
                "AND status = ? "
                "ORDER BY registered_tool_id, pid, candidate_id LIMIT ?",
                (*batch, ToolCandidateStatus.REGISTERED.value, remaining + 1),
            )
            candidate_row_total += len(rows)
            if candidate_row_total > hard_limit:
                raise ValidationError(
                    "JIT rehydration candidate result exceeds configured hard cap: "
                    f"> {hard_limit}"
                )
            self._accumulate_jit_rehydration_candidates(
                rows,
                expected_ids=expected_ids,
                candidate_counts=candidate_counts,
                first_candidates=first_candidates,
            )
        return candidate_counts, first_candidates

    @staticmethod
    def _accumulate_jit_rehydration_candidates(
        rows: Iterable[Any],
        *,
        expected_ids: frozenset[str],
        candidate_counts: dict[str, int],
        first_candidates: dict[str, Any],
    ) -> None:
        for row in rows:
            tool_id = str(row["registered_tool_id"] or "")
            if tool_id not in expected_ids:
                raise ValidationError(
                    "JIT rehydration candidate lookup returned an unexpected tool"
                )
            candidate_counts[tool_id] = candidate_counts.get(tool_id, 0) + 1
            first_candidates.setdefault(tool_id, row)

    @staticmethod
    def _jit_rehydration_artifact_from_row(
        row: Any,
        *,
        candidate_counts: dict[str, int],
        first_candidates: dict[str, Any],
    ) -> JITRehydrationArtifact:
        tool_id = str(row["tool_id"])
        candidate_count = candidate_counts.get(tool_id, 0)
        candidate = first_candidates.get(tool_id) if candidate_count == 1 else None
        return JITRehydrationArtifact(
            tool_id=tool_id,
            name=str(row["name"]),
            scope=str(row["scope"]),
            candidate_match_count=candidate_count,
            candidate_id=(
                str(candidate["candidate_id"]) if candidate is not None else None
            ),
            candidate_pid=(str(candidate["pid"]) if candidate is not None else None),
            source_code=(
                str(candidate["source_code"]) if candidate is not None else None
            ),
        )

    def list_resource_reservations(
        self,
        *,
        parent_pid: str | None = None,
        parent_pids: Iterable[str] | None = None,
        child_pid: str | None = None,
    ) -> list[ResourceReservation]:
        if parent_pid is not None and parent_pids is not None:
            raise ValueError("resource reservation query cannot combine parent_pid and parent_pids")
        clauses: list[str] = []
        params: list[Any] = []
        if parent_pid is not None:
            clauses.append("parent_pid = ?")
            params.append(parent_pid)
        if parent_pids is not None:
            selected_parent_pids = sorted({str(pid) for pid in parent_pids if str(pid)})
            if not selected_parent_pids:
                return []
            clauses.append(f"parent_pid IN ({', '.join('?' for _ in selected_parent_pids)})")
            params.extend(selected_parent_pids)
        if child_pid is not None:
            clauses.append("child_pid = ?")
            params.append(child_pid)
        sql = "SELECT * FROM process_resource_reservations"
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY parent_pid, child_pid"
        return [self._row_to_resource_reservation(row) for row in self._query(sql, params)]

    def delete_resource_reservation(self, parent_pid: str, child_pid: str) -> None:
        self._execute(
            "DELETE FROM process_resource_reservations WHERE parent_pid = ? AND child_pid = ?",
            (parent_pid, child_pid),
        )

    def delete_resource_reservations_for_process(self, pid: str) -> None:
        self._execute(
            "DELETE FROM process_resource_reservations WHERE parent_pid = ? OR child_pid = ?",
            (pid, pid),
        )

    def select_table_rows(
        self,
        table: str,
        where_sql: str = "",
        params: Iterable[Any] = (),
        *,
        order_by: str | None = None,
    ) -> list[dict[str, Any]]:
        table = self.validate_table_identifier(table)
        sql = f"SELECT * FROM {table}"
        if where_sql:
            sql += f" WHERE {where_sql}"
        if order_by:
            sql += f" ORDER BY {order_by}"
        return [self._row_to_dict(row) for row in self._query(sql, params)]

    def insert_table_row(self, table: str, row: dict[str, Any]) -> None:
        table = self.validate_table_identifier(table)
        if table in _SEMANTIC_TYPED_TABLES:
            raise ValidationError(
                "semantic persistence requires its typed repository"
            )
        if table == "process_tool_bindings":
            raise ValidationError(
                "process tool bindings are a derived typed projection"
            )
        columns = list(row)
        for column in columns:
            self.validate_column_identifier(table, column)
        placeholders = ", ".join("?" for _ in columns)
        col_sql = ", ".join(columns)
        params = tuple(row[column] for column in columns)
        if table not in {"processes", "tools"}:
            self._execute(
                f"INSERT INTO {table} ({col_sql}) VALUES ({placeholders})",
                params,
            )
            return
        with self.transaction() as cursor:
            cursor.execute(
                f"INSERT INTO {table} ({col_sql}) VALUES ({placeholders})",
                params,
            )
            if table == "processes":
                self._replace_process_tool_bindings(
                    cursor,
                    str(row["pid"]),
                    loads(row.get("tool_table_json"), {}),
                    loads(row.get("model_tool_table_json"), {}),
                )
                self._ensure_process_terminal_cleanup_intent(
                    cursor,
                    pid=str(row["pid"]),
                    status=str(row["status"]),
                )
            else:
                self._refresh_process_binding_jit_eligibility(
                    cursor,
                    tool_id=str(row["tool_id"]),
                )

    def delete_table_rows(self, table: str, where_sql: str, params: Iterable[Any] = ()) -> None:
        table = self.validate_table_identifier(table)
        if table in _SEMANTIC_TYPED_TABLES:
            raise ValidationError("semantic evidence cannot be generically deleted")
        if table == "process_tool_bindings":
            raise ValidationError(
                "process tool bindings are a derived typed projection"
            )
        if table != "tools":
            self._execute(f"DELETE FROM {table} WHERE {where_sql}", params)
            return
        selected_params = tuple(params)
        selected_tool_ids = "SELECT tool_id FROM tools"
        if where_sql:
            selected_tool_ids += f" WHERE {where_sql}"
        with self.transaction() as cursor:
            cursor.execute(
                "UPDATE process_tool_bindings "
                "SET jit_rehydration_eligible = 0 "
                "WHERE jit_rehydration_eligible = 1 "
                f"AND tool_id IN ({selected_tool_ids})",
                selected_params,
            )
            delete_where = f" WHERE {where_sql}" if where_sql else ""
            cursor.execute(
                f"DELETE FROM tools{delete_where}",
                selected_params,
            )

    def payload_marker(
        self,
        *,
        present: bool,
        recovered_after_reopen: bool = False,
    ) -> dict[str, Any]:
        if present and recovered_after_reopen:
            raise ValueError("a present Object payload cannot be marked as recovered")
        marker: dict[str, Any] = {
            "storage": "runtime_memory",
            "present": present,
        }
        if recovered_after_reopen:
            marker["recovered_after_reopen"] = True
        return marker

    def object_payload(self, oid: str) -> Any:
        with self.locked():
            if oid in self._object_payloads:
                return deepcopy(self._object_payloads[oid])
            rows = self._query("SELECT payload_json FROM objects WHERE oid = ?", (oid,))
            if not rows:
                raise KeyError(oid)
            payload = self._decode_stored_object_payload(rows[0]["payload_json"])
            if payload is _MISSING_OBJECT_PAYLOAD:
                raise KeyError(oid)
            self._set_cached_object_payload(oid, payload)
            return deepcopy(payload)

    def set_object_payload(self, oid: str, payload: Any) -> None:
        self._ensure_healthy()
        with self.transaction(include_object_payloads=True) as cur:
            updated = cur.execute(
                "UPDATE objects SET payload_json = ? "
                "WHERE oid = ? AND lifecycle_state = ?",
                (
                    dumps(self.payload_marker(present=True)),
                    oid,
                    ObjectLifecycleState.LIVE.value,
                ),
            )
            if updated.rowcount != 1:
                raise ValidationError(
                    "cannot set payload for a missing or released Object: "
                    f"{oid}"
                )
            # Cache mutation follows the durable CAS.  The per-OID transaction
            # journal restores this before-image after every known rollback;
            # an ambiguous outer commit poisons the store before it can serve
            # either SQL or cache state.
            self._set_cached_object_payload(oid, payload)

    def rehydrate_object_payload_cache(
        self,
        object_payloads: Mapping[str, Any],
    ) -> tuple[str, ...]:
        """Atomically replace validated volatile payloads without SQL writes."""

        if any(not isinstance(oid, str) or not oid for oid in object_payloads):
            raise ValidationError(
                "Object payload cache ids must be non-empty strings"
            )
        staged = {
            oid: deepcopy(payload)
            for oid, payload in object_payloads.items()
        }
        with self._lock:
            self._ensure_healthy()
            self._ensure_store_scope_admitted()
            if self._transaction_depth != 0:
                raise ValidationError(
                    "Object payload cache rehydration requires an outermost "
                    "durable transaction boundary"
                )
            self._object_payloads.update(staged)
            return tuple(sorted(staged))

    def forget_object_payload(self, oid: str) -> None:
        with self.locked():
            self._forget_cached_object_payload(oid)

    def has_object_payload(self, oid: str, *, row: Any | None = None) -> bool:
        with self.locked():
            if oid in self._object_payloads:
                return True
            selected_row = row
            if selected_row is None:
                rows = self._query("SELECT payload_json FROM objects WHERE oid = ?", (oid,))
                selected_row = rows[0] if rows else None
            if selected_row is None:
                return False
            payload = self._decode_stored_object_payload(selected_row["payload_json"])
            if payload is _MISSING_OBJECT_PAYLOAD:
                return False
            self._set_cached_object_payload(oid, payload)
            return True

    def get_persisted_object_state(
        self,
        oid: str,
    ) -> PersistedObjectState | None:
        """Read the exact payload-free Object state used for revalidation."""

        with self._lock:
            rows = self._query(
                "SELECT oid, lifecycle_state, version, payload_json "
                "FROM objects WHERE oid = ?",
                (oid,),
            )
            if not rows:
                return None
            row = rows[0]
            with _persisted_model_decode("Object state"):
                return PersistedObjectState(
                    oid=row["oid"],
                    lifecycle_state=ObjectLifecycleState(row["lifecycle_state"]),
                    version=row["version"],
                    payload_present=(
                        oid in self._object_payloads
                        or _persisted_object_payload_is_present_without_cache(
                            row["payload_json"]
                        )
                    ),
                    recovered_after_reopen=(
                        _is_recovered_runtime_object_payload_marker(
                            row["payload_json"]
                        )
                    ),
                )

    def _validated_root_spawn_goal_rehydration_payload(
        self,
        oid: str,
        payload: Any,
        *,
        expected_version: int,
        expected_identity_sha256: str,
    ) -> bytes:
        if type(oid) is not str or not oid or "\x00" in oid:
            raise ValidationError("root spawn goal oid must be non-empty text")
        if (
            isinstance(expected_version, bool)
            or not isinstance(expected_version, int)
            or expected_version <= 0
        ):
            raise ValidationError("root spawn goal version must be positive")
        digest_is_valid = (
            type(expected_identity_sha256) is str
            and len(expected_identity_sha256) == 64
            and all(
                character in "0123456789abcdef"
                for character in expected_identity_sha256
            )
        )
        if not digest_is_valid:
            raise ValidationError("root spawn goal identity digest is invalid")
        try:
            payload_bytes = canonical_initial_goal_json_bytes(payload)
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        hard_limit = self.config.tools.memory_payload_hard_limit_bytes
        if len(payload_bytes) > hard_limit:
            raise ValidationError(
                "root spawn goal payload exceeds configured hard limit: "
                f"{len(payload_bytes)} > {hard_limit}"
            )
        return payload_bytes

    def _root_spawn_goal_rehydration_row(self, oid: str) -> Mapping[str, Any]:
        rows = self._query(
            "SELECT oid, namespace, name, type, schema_version, payload_json, "
            "metadata_json, provenance_json, version, immutable, created_by, "
            "owner_kind, owner_id, lifecycle_state, created_at "
            "FROM objects WHERE oid = ?",
            (oid,),
        )
        if len(rows) != 1:
            raise ValidationError("root spawn goal Object is missing")
        return rows[0]

    @staticmethod
    def _require_root_spawn_goal_rehydration_state(
        row: Mapping[str, Any],
        *,
        expected_version: int,
    ) -> None:
        immutable = row["immutable"]
        immutable_is_true = (
            type(immutable) is bool and immutable is True
        ) or (
            type(immutable) is int and immutable == 1
        )
        state_matches = (
            row["type"] == ObjectType.GOAL.value
            and row["lifecycle_state"] == ObjectLifecycleState.LIVE.value
            and row["version"] == expected_version
            and row["payload_json"] in _RUNTIME_OBJECT_PRESENT_PAYLOAD_MARKERS
            and immutable_is_true
        )
        if not state_matches:
            raise ValidationError("root spawn goal Object state changed")

    @staticmethod
    def _root_spawn_goal_identity_digest(row: Mapping[str, Any]) -> str:
        try:
            identity = initial_goal_object_identity(
                oid=str(row["oid"]),
                namespace=str(row["namespace"]),
                name=str(row["name"]),
                object_type=str(row["type"]),
                schema_version=str(row["schema_version"]),
                metadata=loads(row["metadata_json"], {}),
                provenance=loads(row["provenance_json"], {}),
                version=int(row["version"]),
                immutable=bool(row["immutable"]),
                created_by=str(row["created_by"]),
                owner_kind=str(row["owner_kind"]),
                owner_id=str(row["owner_id"]),
                created_at=str(row["created_at"]),
            )
            return initial_goal_object_identity_sha256(identity)
        except (TypeError, ValueError) as exc:
            raise ValidationError(
                f"root spawn goal Object identity is invalid: {exc}"
            ) from exc

    def _cache_root_spawn_goal_payload(
        self,
        oid: str,
        payload: Any,
        payload_bytes: bytes,
    ) -> bool:
        if oid not in self._object_payloads:
            self._object_payloads[oid] = deepcopy(payload)
            return True
        try:
            existing = canonical_initial_goal_json_bytes(self._object_payloads[oid])
        except ValueError as exc:
            raise ValidationError(
                f"root spawn goal cache payload is invalid: {exc}"
            ) from exc
        if existing != payload_bytes:
            raise ValidationError("root spawn goal cache payload changed")
        return False

    def rehydrate_root_spawn_goal_payload(
        self,
        oid: str,
        payload: Any,
        *,
        expected_version: int,
        expected_identity_sha256: str,
        require_recovery_lease: Callable[[], None],
    ) -> bool:
        """Restore one validated root goal into volatile cache without SQL writes."""

        require_recovery_lease()
        payload_bytes = self._validated_root_spawn_goal_rehydration_payload(
            oid,
            payload,
            expected_version=expected_version,
            expected_identity_sha256=expected_identity_sha256,
        )
        with self._lock:
            self._ensure_healthy()
            self._ensure_store_scope_admitted()
            if self._transaction_depth != 0:
                raise ValidationError(
                    "root spawn goal cache rehydration requires an outermost "
                    "durable transaction boundary"
                )
            row = self._root_spawn_goal_rehydration_row(oid)
            self._require_root_spawn_goal_rehydration_state(
                row,
                expected_version=expected_version,
            )
            actual_identity_sha256 = self._root_spawn_goal_identity_digest(row)
            if actual_identity_sha256 != expected_identity_sha256:
                raise ValidationError("root spawn goal Object identity changed")
            return self._cache_root_spawn_goal_payload(
                oid,
                payload,
                payload_bytes,
            )

    def is_recovered_object_payload(self, oid: str) -> bool:
        with self.locked():
            rows = self._query("SELECT payload_json FROM objects WHERE oid = ?", (oid,))
            if not rows:
                return False
            return _is_recovered_runtime_object_payload_marker(
                rows[0]["payload_json"]
            )

    def snapshot_object_payloads(self, oids: Iterable[str]) -> dict[str, Any]:
        with self.locked():
            payloads: dict[str, Any] = {}
            for oid in oids:
                if self.has_object_payload(oid):
                    payloads[oid] = self.object_payload(oid)
            return payloads

    def insert_event(self, event: Event) -> None:
        payload_json = dumps(event.payload)
        self._execute(
            """
            INSERT INTO events (
                event_id, type, source, target, payload_json, priority,
                created_at, correlation_id, causality_json, gui_snapshot_visible
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                event.event_id,
                event.type.value,
                event.source,
                event.target,
                payload_json,
                event.priority.value,
                event.created_at,
                event.correlation_id,
                dumps(event.causality),
                int(
                    not is_gui_presentation_event_fields(
                        event.type,
                        loads(payload_json, {}),
                    )
                ),
            ),
        )

    def list_events(
        self,
        target: str | None = None,
        limit: int | None = None,
        before_event_id: str | None = None,
        after_event_id: str | None = None,
        *,
        include_gui_presentation: bool = True,
    ) -> list[Event]:
        if before_event_id is not None and after_event_id is not None:
            raise ValueError("event query cannot use before_event_id and after_event_id together")
        clauses: list[str] = []
        params: list[Any] = []
        if not include_gui_presentation:
            clauses.append("gui_snapshot_visible = 1")
        if target is not None:
            clauses.append("(target IS NULL OR target = ?)")
            params.append(target)
        if before_event_id is not None:
            cursor_rows = self._query(
                "SELECT created_at, event_id FROM events WHERE event_id = ?",
                (before_event_id,),
            )
            if not cursor_rows:
                return []
            cursor = cursor_rows[0]
            clauses.append("(created_at, event_id) < (?, ?)")
            params.extend((cursor["created_at"], cursor["event_id"]))
        if after_event_id is not None:
            cursor_rows = self._query(
                "SELECT created_at, event_id FROM events WHERE event_id = ?",
                (after_event_id,),
            )
            if not cursor_rows:
                return []
            cursor = cursor_rows[0]
            clauses.append("(created_at, event_id) > (?, ?)")
            params.extend((cursor["created_at"], cursor["event_id"]))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        if limit is None:
            rows = self._query(
                f"SELECT * FROM events{where} ORDER BY created_at, event_id",
                params,
            )
        elif after_event_id is not None:
            params.append(max(0, int(limit)))
            rows = self._query(
                f"SELECT * FROM events{where} ORDER BY created_at, event_id LIMIT ?",
                params,
            )
        else:
            selected_limit = max(0, int(limit))
            params.append(selected_limit)
            rows = self._query(
                "SELECT * FROM ("
                f"SELECT * FROM events{where} "
                "ORDER BY created_at DESC, event_id DESC LIMIT ?"
                ") AS recent_events ORDER BY created_at, event_id",
                params,
            )
        return [self._row_to_event(row) for row in rows]

    def get_event(self, event_id: str) -> Event | None:
        rows = self._query("SELECT * FROM events WHERE event_id = ?", (event_id,))
        return self._row_to_event(rows[0]) if rows else None

    def insert_capability(self, cap: Capability) -> None:
        uses_remaining = _capability_uses_remaining(
            cap.uses_remaining,
            status=cap.status,
        )
        rights = _capability_rights_for_write(cap.rights)
        constraints = _capability_json_object(
            cap.constraints,
            label="constraints",
        )
        metadata = _capability_json_object(
            cap.metadata,
            label="metadata",
        )
        if len(rights) > self.config.capability.max_rights_per_capability:
            raise ValueError("capability rights exceed configured limit")
        (
            delegable,
            revocable,
            delegation_depth,
            max_delegation_depth,
        ) = _capability_authority_scalars(cap)
        self._execute(
            """
            INSERT INTO capabilities (
                cap_id, subject, resource, rights_json, constraints_json,
                issued_by, issued_at, expires_at, delegable, revocable, effect,
                issuer_cap_id, parent_cap_id, delegation_depth, max_delegation_depth,
                uses_remaining, status, metadata_json
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                cap.cap_id,
                cap.subject,
                cap.resource,
                dumps(rights),
                dumps(constraints),
                cap.issued_by,
                cap.issued_at,
                cap.expires_at,
                int(delegable),
                int(revocable),
                cap.effect.value,
                cap.issuer_cap_id,
                cap.parent_cap_id,
                delegation_depth,
                max_delegation_depth,
                uses_remaining,
                cap.status.value,
                dumps(metadata),
            ),
        )

    def consume_capability_uses(self, cap_id: str, count: int = 1) -> Capability | None:
        count = _positive_capability_use_count(count)
        with self._join_or_begin_transaction() as cur:
            updated = cur.execute(
                """
                UPDATE capabilities
                   SET uses_remaining = uses_remaining - ?,
                       status = CASE
                           WHEN uses_remaining - ? <= 0 THEN ?
                           ELSE status
                       END
                 WHERE cap_id = ?
                   AND status = ?
                   AND uses_remaining IS NOT NULL
                   AND uses_remaining >= ?
                """,
                (
                    count,
                    count,
                    CapabilityStatus.REVOKED.value,
                    cap_id,
                    CapabilityStatus.ACTIVE.value,
                    count,
                ),
            )
            if updated.rowcount != 1:
                return None
            rows = list(cur.execute("SELECT * FROM capabilities WHERE cap_id = ?", (cap_id,)))
            return self._row_to_capability(rows[0]) if rows else None

    def reserve_capability_uses(
        self,
        cap_id: str,
        reservation_id: str,
        *,
        count: int = 1,
        reserved_by: str,
        reason: str,
        created_at: str,
    ) -> Capability | None:
        count = _positive_capability_use_count(count)
        with self.transaction() as cur:
            updated = cur.execute(
                """
                UPDATE capabilities
                   SET uses_remaining = uses_remaining - ?,
                       status = CASE
                           WHEN uses_remaining - ? <= 0 THEN ?
                           ELSE status
                       END
                 WHERE cap_id = ?
                   AND status = ?
                   AND uses_remaining IS NOT NULL
                   AND uses_remaining >= ?
                """,
                (
                    count,
                    count,
                    CapabilityStatus.REVOKED.value,
                    cap_id,
                    CapabilityStatus.ACTIVE.value,
                    count,
                ),
            )
            if updated.rowcount != 1:
                return None
            cur.execute(
                """
                INSERT INTO capability_use_reservations (
                    reservation_id, cap_id, count, status, reserved_by, reason, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (reservation_id, cap_id, count, "reserved", reserved_by, reason, created_at, created_at),
            )
            rows = list(cur.execute("SELECT * FROM capabilities WHERE cap_id = ?", (cap_id,)))
            return self._row_to_capability(rows[0]) if rows else None

    def commit_capability_use_reservation(self, reservation_id: str, *, updated_at: str) -> bool:
        with self._join_or_begin_transaction() as cur:
            updated = cur.execute(
                """
                UPDATE capability_use_reservations
                   SET status = ?, updated_at = ?
                 WHERE reservation_id = ? AND status = ?
                """,
                ("committed", updated_at, reservation_id, "reserved"),
            )
            return updated.rowcount == 1

    def restore_capability_use_reservation(self, reservation_id: str, *, updated_at: str) -> Capability | None:
        with self.transaction() as cur:
            reservations = list(
                cur.execute(
                    """
                    SELECT * FROM capability_use_reservations
                     WHERE reservation_id = ? AND status = ?
                    """,
                    (reservation_id, "reserved"),
                )
            )
            if not reservations:
                return None
            reservation = reservations[0]
            cap_id = str(reservation["cap_id"])
            try:
                count = _positive_capability_use_count(
                    reservation["count"],
                    label="persisted capability reservation count",
                )
            except ValueError as exc:
                raise ValidationError(str(exc)) from exc
            restored = cur.execute(
                """
                UPDATE capabilities
                   SET uses_remaining = uses_remaining + ?,
                       status = CASE
                           WHEN status = ? THEN ?
                           ELSE status
                       END
                 WHERE cap_id = ?
                   AND uses_remaining IS NOT NULL
                   AND status IN (?, ?)
                """,
                (
                    count,
                    CapabilityStatus.REVOKED.value,
                    CapabilityStatus.ACTIVE.value,
                    cap_id,
                    CapabilityStatus.ACTIVE.value,
                    CapabilityStatus.REVOKED.value,
                ),
            )
            if restored.rowcount != 1:
                cur.execute(
                    """
                    UPDATE capability_use_reservations
                       SET status = ?, updated_at = ?
                     WHERE reservation_id = ? AND status = ?
                    """,
                    ("invalidated", updated_at, reservation_id, "reserved"),
                )
                return None
            cur.execute(
                """
                UPDATE capability_use_reservations
                   SET status = ?, updated_at = ?
                 WHERE reservation_id = ? AND status = ?
                """,
                ("restored", updated_at, reservation_id, "reserved"),
            )
            rows = list(cur.execute("SELECT * FROM capabilities WHERE cap_id = ?", (cap_id,)))
            return self._row_to_capability(rows[0]) if rows else None

    def get_capability_use_reservation(self, reservation_id: str) -> dict[str, Any] | None:
        rows = self._query(
            "SELECT * FROM capability_use_reservations WHERE reservation_id = ?",
            (reservation_id,),
        )
        if not rows:
            return None
        selected = dict(rows[0])
        try:
            _positive_capability_use_count(
                selected["count"],
                label="persisted capability reservation count",
            )
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        return selected

    def update_capability(self, cap: Capability) -> None:
        uses_remaining = _capability_uses_remaining(
            cap.uses_remaining,
            status=cap.status,
        )
        rights = _capability_rights_for_write(cap.rights)
        constraints = _capability_json_object(
            cap.constraints,
            label="constraints",
        )
        metadata = _capability_json_object(
            cap.metadata,
            label="metadata",
        )
        if len(rights) > self.config.capability.max_rights_per_capability:
            raise ValueError("capability rights exceed configured limit")
        (
            delegable,
            revocable,
            delegation_depth,
            max_delegation_depth,
        ) = _capability_authority_scalars(cap)
        sql = """
            UPDATE capabilities
               SET subject = ?, resource = ?, rights_json = ?, constraints_json = ?,
                   issued_by = ?, issued_at = ?, expires_at = ?, delegable = ?,
                   revocable = ?, effect = ?, issuer_cap_id = ?, parent_cap_id = ?,
                   delegation_depth = ?, max_delegation_depth = ?, uses_remaining = ?,
                   status = ?, metadata_json = ?
             WHERE cap_id = ?
            """
        params = (
            cap.subject,
            cap.resource,
            dumps(rights),
            dumps(constraints),
            cap.issued_by,
            cap.issued_at,
            cap.expires_at,
            int(delegable),
            int(revocable),
            cap.effect.value,
            cap.issuer_cap_id,
            cap.parent_cap_id,
            delegation_depth,
            max_delegation_depth,
            uses_remaining,
            cap.status.value,
            dumps(metadata),
            cap.cap_id,
        )
        if cap.status == CapabilityStatus.ACTIVE:
            self._execute(sql, params)
            return
        with self.transaction() as cur:
            cur.execute(sql, params)
            cur.execute(
                """
                UPDATE capability_use_reservations
                   SET status = ?, updated_at = ?
                 WHERE cap_id = ? AND status = ?
                """,
                ("invalidated", utc_now(), cap.cap_id, "reserved"),
            )

    def transition_capability_status(
        self,
        cap_id: str,
        *,
        expected_status: CapabilityStatus,
        status: CapabilityStatus,
        metadata: dict[str, Any],
    ) -> Capability | None:
        """Atomically move one capability only from its expected lifecycle state."""

        selected_expected = CapabilityStatus(expected_status)
        selected_status = CapabilityStatus(status)
        with self.transaction() as cur:
            updated = cur.execute(
                """
                UPDATE capabilities
                   SET status = ?, metadata_json = ?
                 WHERE cap_id = ? AND status = ?
                """,
                (
                    selected_status.value,
                    dumps(metadata),
                    cap_id,
                    selected_expected.value,
                ),
            )
            if updated.rowcount != 1:
                return None
            if selected_status != CapabilityStatus.ACTIVE:
                cur.execute(
                    """
                    UPDATE capability_use_reservations
                       SET status = ?, updated_at = ?
                     WHERE cap_id = ? AND status = ?
                    """,
                    ("invalidated", utc_now(), cap_id, "reserved"),
                )
            rows = list(
                cur.execute(
                    "SELECT * FROM capabilities WHERE cap_id = ?",
                    (cap_id,),
                )
            )
            return self._row_to_capability(rows[0]) if rows else None

    def get_capability(self, cap_id: str) -> Capability | None:
        rows = self._query("SELECT * FROM capabilities WHERE cap_id = ?", (cap_id,))
        return self._row_to_capability(rows[0]) if rows else None

    def list_capabilities(
        self,
        subject: str | None = None,
        *,
        limit: int | None = None,
    ) -> list[Capability]:
        if limit is not None and (
            type(limit) is not int
            or limit <= 0
            or limit > self.config.capability.list_limit
        ):
            raise ValidationError(
                "capability list limit must be a positive integer no greater than "
                f"capability.list_limit={self.config.capability.list_limit}"
            )
        params: list[Any] = []
        if subject is None:
            sql = "SELECT * FROM capabilities ORDER BY subject ASC, issued_at ASC, cap_id ASC"
        else:
            sql = (
                "SELECT * FROM capabilities WHERE subject = ? "
                "ORDER BY issued_at ASC, cap_id ASC"
            )
            params.append(subject)
        if limit is not None:
            sql += " LIMIT ?"
            params.append(limit)
        rows = self._query(sql, params)
        return [self._row_to_capability(row) for row in rows]

    def query_capabilities(
        self,
        subject: str | None = None,
        *,
        active_only: bool,
        after_cap_id: str | None,
        limit: int,
    ) -> list[Capability]:
        """Return one stable, hard-bounded capability page ordered by ID."""

        if subject is not None and (type(subject) is not str or not subject):
            raise ValidationError(
                "capability page subject must be a non-empty string when set"
            )
        if type(active_only) is not bool:
            raise ValidationError("capability page active_only must be boolean")
        if after_cap_id is not None and (
            type(after_cap_id) is not str or not after_cap_id
        ):
            raise ValidationError(
                "capability page cursor must be a non-empty string when set"
            )
        if (
            type(limit) is not int
            or limit <= 0
            or limit > self.config.capability.list_limit
        ):
            raise ValidationError(
                "capability page limit must be a positive integer no greater than "
                f"capability.list_limit={self.config.capability.list_limit}"
            )

        clauses: list[str] = []
        params: list[Any] = []
        if subject is not None:
            clauses.append("subject = ?")
            params.append(subject)
        if active_only:
            clauses.append("status = ?")
            params.append(CapabilityStatus.ACTIVE.value)
        if after_cap_id is not None:
            clauses.append("cap_id > ?")
            params.append(after_cap_id)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(limit)
        rows = self._query(
            f"SELECT * FROM capabilities{where} ORDER BY cap_id ASC LIMIT ?",
            params,
        )
        return [self._row_to_capability(row) for row in rows]

    def register_sink_trust(self, spec: SinkTrustSpec, *, replace: bool = False) -> SinkTrustSpec:
        if not isinstance(spec, SinkTrustSpec):
            raise ValidationError("sink trust registration requires a validated SinkTrustSpec")
        if not spec.active:
            raise ValidationError("new sink trust record must be active")
        with self.transaction() as cur:
            current = self._sink_trust_generation_from_cursor(cur)
            if spec.generation != current + 1:
                raise ValidationError(
                    f"sink trust generation conflict: expected {current + 1}, got {spec.generation}"
                )
            cur.execute(
                "SELECT trust_id FROM sink_trust_records WHERE pattern = ? AND active = 1",
                (spec.pattern,),
            )
            existing = cur.fetchone()
            if existing is not None and not replace:
                raise ValidationError(f"active sink trust rule already exists: {spec.pattern}")
            if existing is not None:
                cur.execute(
                    """
                    UPDATE sink_trust_records
                       SET active = 0, deactivated_at = ?
                     WHERE pattern = ? AND active = 1
                    """,
                    (spec.created_at, spec.pattern),
                )
            cur.execute(
                """
                INSERT INTO sink_trust_records (
                    trust_id, schema_version, pattern, trust_level,
                    max_sensitivity, tenants_json, principals_json,
                    identity_sha256, generation, spec_hash, active,
                    created_by, created_at, deactivated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    spec.trust_id,
                    spec.schema_version,
                    spec.pattern,
                    spec.trust_level.value,
                    spec.max_sensitivity.value,
                    dumps(spec.tenants),
                    dumps(spec.principals),
                    spec.identity_sha256,
                    spec.generation,
                    spec.spec_hash,
                    1,
                    spec.created_by,
                    spec.created_at,
                    None,
                ),
            )
            cur.execute(
                "UPDATE sink_trust_registry SET generation = ?, updated_at = ? WHERE registry_key = 'default'",
                (spec.generation, spec.created_at),
            )
            if cur.rowcount != 1:
                raise ValidationError("sink trust registry metadata is missing")
        return spec

    def unregister_sink_trust(
        self,
        pattern: str,
        *,
        generation: int,
        deactivated_at: str,
    ) -> bool:
        try:
            SinkTrustRule(pattern=pattern)
        except ValueError as exc:
            raise ValidationError(f"invalid sink trust pattern: {exc}") from exc
        if not isinstance(deactivated_at, str) or not deactivated_at.strip():
            raise ValidationError("sink trust deactivated_at must be a non-empty string")
        with self.transaction() as cur:
            current = self._sink_trust_generation_from_cursor(cur)
            if generation != current + 1:
                raise ValidationError(
                    f"sink trust generation conflict: expected {current + 1}, got {generation}"
                )
            cur.execute(
                "SELECT trust_id FROM sink_trust_records WHERE pattern = ? AND active = 1",
                (pattern,),
            )
            if cur.fetchone() is None:
                return False
            cur.execute(
                """
                UPDATE sink_trust_records
                   SET active = 0, deactivated_at = ?
                 WHERE pattern = ? AND active = 1
                """,
                (deactivated_at, pattern),
            )
            if cur.rowcount != 1:
                raise ValidationError(f"sink trust rule changed concurrently: {pattern}")
            cur.execute(
                "UPDATE sink_trust_registry SET generation = ?, updated_at = ? WHERE registry_key = 'default'",
                (generation, deactivated_at),
            )
            if cur.rowcount != 1:
                raise ValidationError("sink trust registry metadata is missing")
        return True

    def get_sink_trust(self, trust_id: str) -> SinkTrustSpec | None:
        rows = self._query("SELECT * FROM sink_trust_records WHERE trust_id = ?", (trust_id,))
        return self._row_to_sink_trust(rows[0]) if rows else None

    def inspect_sink_trust(self, pattern: str) -> SinkTrustSpec | None:
        rows = self._query(
            "SELECT * FROM sink_trust_records WHERE pattern = ? AND active = 1",
            (pattern,),
        )
        return self._row_to_sink_trust(rows[0]) if rows else None

    def list_sink_trust(
        self,
        *,
        active_only: bool = True,
        generation: int | None = None,
        limit: int | None = None,
    ) -> list[SinkTrustSpec]:
        clauses: list[str] = []
        params: list[Any] = []
        if active_only:
            clauses.append("active = 1")
        if generation is not None:
            if isinstance(generation, bool) or not isinstance(generation, int) or generation < 0:
                raise ValidationError("sink trust generation filter must be a non-negative integer")
            clauses.append("generation = ?")
            params.append(generation)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        sql = f"SELECT * FROM sink_trust_records{where} ORDER BY generation DESC, pattern, trust_id"
        if limit is not None:
            selected_limit = self._data_flow_list_limit(
                limit,
                default=self.config.data_flow.registry_list_limit,
                hard_limit=self.config.data_flow.registry_list_limit,
                label="sink trust",
            )
            sql += " LIMIT ?"
            params.append(selected_limit)
        # Enforcement resolution calls this method without a limit and must
        # see the complete Host registry. Explicit administrative list calls
        # may opt into the configured bounded window.
        rows = self._query(sql, params)
        return [self._row_to_sink_trust(row) for row in rows]

    def get_sink_trust_generation(self) -> int:
        rows = self._query(
            "SELECT generation FROM sink_trust_registry WHERE registry_key = 'default'"
        )
        if not rows:
            raise ValidationError("sink trust registry metadata is missing")
        generation = rows[0]["generation"]
        if isinstance(generation, bool) or not isinstance(generation, int) or generation < 0:
            raise ValidationError("invalid persisted sink trust registry generation")
        return generation

    def insert_data_flow_decision(self, decision: DataFlowDecision) -> None:
        if not isinstance(decision, DataFlowDecision):
            raise ValidationError("data-flow decision insert requires a validated DataFlowDecision")
        self._execute(
            """
            INSERT INTO data_flow_decisions (
                decision_id, pid, sink, direction, outcome, reason,
                labels_json, source_refs_json, payload_hash, trust_id,
                trust_hash, registry_generation, release_capability_id, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                decision.decision_id,
                decision.pid,
                decision.sink,
                decision.direction.value,
                decision.outcome.value,
                decision.reason,
                dumps(decision.labels.to_dict()),
                dumps([ref.to_dict() for ref in decision.source_refs]),
                decision.payload_hash,
                decision.trust_id,
                decision.trust_hash,
                decision.registry_generation,
                decision.release_capability_id,
                decision.created_at,
            ),
        )

    def get_data_flow_decision(self, decision_id: str) -> DataFlowDecision | None:
        rows = self._query("SELECT * FROM data_flow_decisions WHERE decision_id = ?", (decision_id,))
        return self._row_to_data_flow_decision(rows[0]) if rows else None

    def list_data_flow_decisions(
        self,
        *,
        pid: str | None = None,
        sink: str | None = None,
        outcome: str | None = None,
        limit: int | None = None,
    ) -> list[DataFlowDecision]:
        clauses: list[str] = []
        params: list[Any] = []
        for column, value in (("pid", pid), ("sink", sink)):
            if value is not None:
                clauses.append(f"{column} = ?")
                params.append(value)
        if outcome is not None:
            try:
                selected_outcome = DataFlowOutcome(outcome).value
            except ValueError as exc:
                raise ValidationError(f"invalid data-flow outcome filter: {outcome}") from exc
            clauses.append("outcome = ?")
            params.append(selected_outcome)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        selected_limit = self._data_flow_list_limit(
            limit,
            default=self.config.data_flow.decision_list_limit,
            hard_limit=self.config.data_flow.decision_list_limit,
            label="data-flow decision",
        )
        rows = self._query(
            f"SELECT * FROM data_flow_decisions{where} "
            "ORDER BY created_at DESC, decision_id DESC LIMIT ?",
            [*params, selected_limit],
        )
        return [self._row_to_data_flow_decision(row) for row in rows]

    def upsert_file_label_binding(self, binding: FileLabelBinding) -> FileLabelBinding:
        if not isinstance(binding, FileLabelBinding):
            raise ValidationError("file label upsert requires a validated FileLabelBinding")
        if binding.tombstoned or not binding.active:
            raise ValidationError("file label upsert requires an active, non-tombstoned binding")
        with self.transaction() as cur:
            current_generation = self._file_label_generation_from_cursor(cur, binding.normalized_path)
            if binding.generation != current_generation + 1:
                raise ValidationError(
                    "file label generation conflict for "
                    f"{binding.normalized_path}: expected {current_generation + 1}, got {binding.generation}"
                )
            cur.execute(
                """
                UPDATE file_label_bindings
                   SET active = 0, superseded_at = ?
                 WHERE normalized_path = ? AND active = 1
                """,
                (binding.created_at, binding.normalized_path),
            )
            self._insert_file_label_binding(cur, binding)
        return binding

    def get_file_label_binding(self, normalized_path: str) -> FileLabelBinding | None:
        rows = self._query(
            """
            SELECT * FROM file_label_bindings
             WHERE normalized_path = ? AND active = 1 AND tombstoned = 0
            """,
            (normalized_path,),
        )
        return self._row_to_file_label_binding(rows[0]) if rows else None

    def get_file_label_binding_by_id(
        self,
        binding_id: str,
    ) -> FileLabelBinding | None:
        rows = self._query(
            """
            SELECT * FROM file_label_bindings
             WHERE binding_id = ?
            """,
            (binding_id,),
        )
        return self._row_to_file_label_binding(rows[0]) if rows else None

    def get_file_label_binding_generation(self, normalized_path: str) -> int:
        rows = self._query(
            "SELECT MAX(generation) AS generation FROM file_label_bindings WHERE normalized_path = ?",
            (normalized_path,),
        )
        value = rows[0]["generation"] if rows else None
        return int(value) if value is not None else 0

    def list_file_label_bindings(
        self,
        *,
        normalized_path: str | None = None,
        include_history: bool = False,
        include_tombstones: bool = False,
        limit: int | None = None,
    ) -> list[FileLabelBinding]:
        clauses: list[str] = []
        params: list[Any] = []
        if normalized_path is not None:
            clauses.append("normalized_path = ?")
            params.append(normalized_path)
        if not include_history:
            clauses.append("active = 1")
        if not include_tombstones:
            clauses.append("tombstoned = 0")
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        selected_limit = self._data_flow_list_limit(
            limit,
            default=self.config.data_flow.file_binding_list_limit,
            hard_limit=self.config.data_flow.file_binding_list_limit,
            label="file label binding",
        )
        rows = self._query(
            f"SELECT * FROM file_label_bindings{where} "
            "ORDER BY normalized_path, generation DESC, binding_id LIMIT ?",
            [*params, selected_limit],
        )
        return [self._row_to_file_label_binding(row) for row in rows]

    def list_file_label_bindings_for_tree(
        self,
        normalized_path: str,
    ) -> list[FileLabelBinding]:
        selected = str(normalized_path).rstrip("/")
        batch_size = self.config.data_flow.file_binding_list_limit
        found: list[FileLabelBinding] = []
        last_path: str | None = None
        while True:
            params: list[Any] = []
            clauses = [
                "active = 1",
                "tombstoned = 0",
                "normalized_path COLLATE BINARY != '.git'",
                "normalized_path COLLATE BINARY NOT LIKE '.git/%'",
            ]
            if selected not in {"", "."}:
                descendant_prefix = f"{selected}/"
                escaped_prefix = (
                    descendant_prefix.replace("!", "!!")
                    .replace("%", "!%")
                    .replace("_", "!_")
                )
                # The outer range drives an index seek; the escaped LIKE keeps
                # exact subtree semantics for adjacent names such as treehouse.
                upper_bound = f"{selected}\U0010ffff"
                clauses.extend(
                    (
                        "normalized_path COLLATE BINARY >= ?",
                        "normalized_path COLLATE BINARY < ?",
                        "(normalized_path COLLATE BINARY = ? "
                        "OR normalized_path COLLATE BINARY LIKE ? ESCAPE '!')",
                    )
                )
                params.extend(
                    (selected, upper_bound, selected, f"{escaped_prefix}%")
                )
            if last_path is not None:
                clauses.append("normalized_path COLLATE BINARY > ?")
                params.append(last_path)
            params.append(batch_size)
            rows = self._query(
                "SELECT * FROM file_label_bindings "
                f"WHERE {' AND '.join(clauses)} "
                "ORDER BY normalized_path COLLATE BINARY, generation DESC, binding_id LIMIT ?",
                params,
            )
            found.extend(self._row_to_file_label_binding(row) for row in rows)
            if len(rows) < batch_size:
                break
            last_path = str(rows[-1]["normalized_path"])
        return found

    def tombstone_file_label_binding(
        self,
        normalized_path: str,
        *,
        binding_id: str,
        created_by: str,
        created_at: str,
        expected_binding_id: str | None = None,
        expected_generation: int | None = None,
    ) -> FileLabelBinding | None:
        if (expected_binding_id is None) != (expected_generation is None):
            raise ValidationError(
                "file label tombstone CAS requires both binding ID and generation"
            )
        with self.transaction() as cur:
            cur.execute(
                """
                SELECT * FROM file_label_bindings
                 WHERE normalized_path = ? AND active = 1 AND tombstoned = 0
                """,
                (normalized_path,),
            )
            row = cur.fetchone()
            if row is None:
                return None
            previous = self._row_to_file_label_binding(row)
            if expected_binding_id is not None and (
                previous.binding_id != expected_binding_id
                or previous.generation != expected_generation
            ):
                return None
            tombstone = FileLabelBinding(
                binding_id=binding_id,
                normalized_path=normalized_path,
                content_sha256=None,
                labels=previous.labels,
                source_refs=previous.source_refs,
                generation=previous.generation + 1,
                tombstoned=True,
                active=True,
                created_by=created_by,
                created_at=created_at,
            )
            cur.execute(
                """
                UPDATE file_label_bindings
                   SET active = 0, superseded_at = ?
                 WHERE binding_id = ? AND active = 1
                """,
                (created_at, previous.binding_id),
            )
            if cur.rowcount != 1:
                if expected_binding_id is not None:
                    return None
                raise ValidationError(f"file label binding changed concurrently: {normalized_path}")
            self._insert_file_label_binding(cur, tombstone)
        return tombstone

    def insert_audit(self, record: AuditRecord) -> None:
        decision_json = (
            dumps(record.decision) if record.decision is not None else None
        )
        self._execute(
            """
            INSERT INTO audit_records (
                record_id, timestamp, actor, action, target, input_refs_json,
                output_refs_json, capability_refs_json, decision_json,
                correlation_id, parent_record_id, gui_snapshot_visible
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                record.record_id,
                record.timestamp,
                record.actor,
                record.action,
                record.target,
                dumps(record.input_refs),
                dumps(record.output_refs),
                dumps(record.capability_refs),
                decision_json,
                record.correlation_id,
                record.parent_record_id,
                int(
                    not is_gui_presentation_audit_fields(
                        record.action,
                        record.target,
                        loads(decision_json) if decision_json is not None else None,
                    )
                ),
            ),
        )

    def list_audit(
        self,
        limit: int | None = None,
        *,
        actor: str | None = None,
        action: str | None = None,
        target: str | None = None,
        match_any: bool = False,
        include_gui_presentation: bool = True,
        before_record_id: str | None = None,
    ) -> list[AuditRecord]:
        clauses: list[str] = []
        params: list[Any] = []
        if not include_gui_presentation:
            clauses.append("gui_snapshot_visible = 1")
        selectors: list[str] = []
        selector_params: list[Any] = []
        if actor is not None:
            selectors.append("actor COLLATE BINARY = ? COLLATE BINARY")
            selector_params.append(actor)
        if action is not None:
            if not isinstance(action, str) or not action:
                raise ValidationError("audit action filter must be a non-empty string")
            clauses.append("action COLLATE BINARY = ? COLLATE BINARY")
            params.append(action)
        if target is not None:
            selectors.append("target = ?")
            selector_params.append(target)
        if selectors:
            joiner = " OR " if match_any and len(selectors) > 1 else " AND "
            clauses.append(f"({joiner.join(selectors)})")
            params.extend(selector_params)
        if before_record_id is not None:
            cursor_rows = self._query(
                "SELECT timestamp, record_id FROM audit_records WHERE record_id = ?",
                (before_record_id,),
            )
            if not cursor_rows:
                return []
            cursor = cursor_rows[0]
            clauses.append("(timestamp, record_id) < (?, ?)")
            params.extend((cursor["timestamp"], cursor["record_id"]))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        order = "ORDER BY timestamp, record_id"
        if limit is None:
            return [self._row_to_audit(row) for row in self._query(f"SELECT * FROM audit_records{where} {order}", params)]
        selected_limit = int(limit)
        if selected_limit <= 0:
            return []
        # Limited audit reads are used by the GUI and API list views. Select the
        # newest window first, then return it chronologically so append streams
        # do not lose recent records once the table is larger than the window.
        limited = (
            f"SELECT audit_records.* FROM audit_records{where} "
            "ORDER BY timestamp DESC, record_id DESC LIMIT ?"
        )
        rows = self._query(
            f"SELECT * FROM ({limited}) AS limited_audit ORDER BY timestamp, record_id",
            [*params, selected_limit],
        )
        return [self._row_to_audit(row) for row in rows]

    def get_audit(self, record_id: str) -> AuditRecord | None:
        rows = self._query("SELECT * FROM audit_records WHERE record_id = ?", (record_id,))
        return self._row_to_audit(rows[0]) if rows else None

    def insert_operation(self, record: OperationRecord) -> None:
        runtime_publication_id = _operation_runtime_publication_id(record.metadata)
        with self._join_or_begin_transaction():
            self._require_operation_publication_binding_available(
                runtime_publication_id,
                operation_id=record.operation_id,
            )
            self._execute(
                """
                INSERT INTO operations (
                    operation_id, root_operation_id, parent_operation_id, kind, name,
                    actor, pid, state, outcome, expected_roles_json, metadata_json,
                    runtime_publication_id, started_at, updated_at, completed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    record.operation_id,
                    record.root_operation_id,
                    record.parent_operation_id,
                    record.kind.value,
                    record.name,
                    record.actor,
                    record.pid,
                    record.state.value,
                    record.outcome.value,
                    dumps(record.expected_roles),
                    dumps(record.metadata),
                    runtime_publication_id,
                    record.started_at,
                    record.updated_at,
                    record.completed_at,
                ),
            )
            self._invalidate_runtime_publication_operation_reconciliation(
                (runtime_publication_id,)
            )

    def get_operation(self, operation_id: str) -> OperationRecord | None:
        rows = self._query("SELECT * FROM operations WHERE operation_id = ?", (operation_id,))
        return self._row_to_operation(rows[0]) if rows else None

    def list_operation_ids_by_runtime_publication_id(
        self,
        publication_id: str,
    ) -> list[str]:
        selected = str(publication_id)
        if not selected:
            return []
        rows = self._query(
            "SELECT operation_id FROM operations "
            "WHERE runtime_publication_id = ? ORDER BY operation_id",
            (selected,),
        )
        return [str(row["operation_id"]) for row in rows]

    def _require_operation_publication_binding_available(
        self,
        publication_id: str | None,
        *,
        operation_id: str,
    ) -> None:
        if publication_id is None:
            return
        bound_ids = self.list_operation_ids_by_runtime_publication_id(publication_id)
        if any(bound_id != operation_id for bound_id in bound_ids):
            raise ValidationError(
                "runtime publication is already bound to another operation: "
                f"{publication_id} -> {bound_ids}"
            )

    def _invalidate_runtime_publication_operation_reconciliation(
        self,
        publication_ids: Iterable[str | None],
    ) -> None:
        """Dirty exact publication bindings in the caller's SQL transaction."""

        selected_ids = sorted(
            {
                publication_id
                for publication_id in publication_ids
                if publication_id is not None
            }
        )
        if not selected_ids:
            return
        placeholders = ", ".join("?" for _ in selected_ids)
        self._execute(
            "UPDATE runtime_publications "
            "SET operation_reconciled = 0, updated_at = ? "
            f"WHERE publication_id IN ({placeholders})",
            (utc_now(), *selected_ids),
        )

    def list_operations(
        self,
        *,
        pid: str | None = None,
        root_operation_id: str | None = None,
        roots_only: bool = False,
        state: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> list[OperationRecord]:
        clauses: list[str] = []
        params: list[Any] = []
        if pid is not None:
            clauses.append("pid = ?")
            params.append(pid)
        if root_operation_id is not None:
            clauses.append("root_operation_id = ?")
            params.append(root_operation_id)
        if roots_only:
            clauses.append("parent_operation_id IS NULL")
        if state is not None:
            clauses.append("state = ?")
            params.append(str(state))
        if cursor is not None:
            cursor_row = self.get_operation(cursor)
            if cursor_row is None:
                return []
            clauses.append("(started_at, operation_id) < (?, ?)")
            params.extend((cursor_row.started_at, cursor_row.operation_id))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        sql = f"SELECT * FROM operations{where} ORDER BY started_at DESC, operation_id DESC"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(max(0, int(limit)))
        return [self._row_to_operation(row) for row in self._query(sql, params)]

    def scan_stale_running_operations(
        self,
        *,
        after: OperationCursor | None,
        limit: int,
    ) -> OperationPage:
        """Read one stable, hard-bounded startup-recovery page."""

        selected_limit = self._operation_recovery_limit(limit)
        clauses = ["state = ?"]
        params: list[Any] = [OperationState.RUNNING.value]
        if after is not None:
            if not isinstance(after, OperationCursor):
                raise ValidationError("operation recovery cursor has an invalid type")
            clauses.append("(started_at, operation_id) < (?, ?)")
            params.extend((after.started_at, after.operation_id))
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM operations "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY started_at DESC, operation_id DESC LIMIT ?",
            params,
        )
        records = tuple(self._row_to_operation(row) for row in rows[:selected_limit])
        next_cursor = None
        if len(rows) > selected_limit:
            last = records[-1]
            next_cursor = OperationCursor(last.started_at, last.operation_id)
        return OperationPage(records=records, next_cursor=next_cursor)

    def operation_ids_with_unknown_external_effects(
        self,
        operation_ids: Iterable[str],
    ) -> set[str]:
        """Read one bounded page from the active startup recovery index."""
        with self._lock:
            self._ensure_healthy()
            if not self._stale_operation_recovery_index_active:
                raise ValidationError(
                    "stale operation recovery index is not active"
                )
            hard_limit = self.config.runtime.operation_recovery_page_hard_limit
            selected: list[str] = []
            seen: set[str] = set()
            for index, operation_id in enumerate(operation_ids):
                if index >= hard_limit:
                    raise ValidationError(
                        "operation recovery id batch exceeds configured hard cap: "
                        f"> {hard_limit}"
                    )
                if not isinstance(operation_id, str) or not operation_id:
                    raise ValidationError(
                        "operation recovery ids must be non-empty text"
                    )
                if operation_id not in seen:
                    seen.add(operation_id)
                    selected.append(operation_id)
            selected_ids = tuple(selected)
            if not selected_ids:
                return set()
            placeholders = ", ".join("?" for _ in selected_ids)
            rows = self._query(
                "SELECT operation_id "
                f"FROM {_STALE_OPERATION_RECOVERY_TEMP_TABLE} "
                f"WHERE operation_id IN ({placeholders}) ORDER BY operation_id",
                selected_ids,
            )
        return {str(row["operation_id"]) for row in rows}

    @contextmanager
    def stale_operation_recovery_index(self) -> Iterator[None]:
        """Materialize uncertain running ancestors in a connection-local table.

        The store lock spans the snapshot, every bounded membership page, and
        cleanup.  Reentrant lifecycle writes can terminalize each page, while
        another thread using the same store cannot mutate evidence underneath
        the recovery classification.
        """

        table = _STALE_OPERATION_RECOVERY_TEMP_TABLE
        with self._lock:
            self._ensure_healthy()
            if self._stale_operation_recovery_index_depth > 0:
                self._stale_operation_recovery_index_depth += 1
                try:
                    yield
                finally:
                    self._stale_operation_recovery_index_depth -= 1
                return
            self._stale_operation_recovery_index_depth = 1
            try:
                self._execute(
                    f"CREATE TEMP TABLE IF NOT EXISTS {table} ("
                    "operation_id TEXT PRIMARY KEY)"
                )
                self._execute(f"DELETE FROM {table}")
                self._populate_stale_operation_recovery_index(table)
                self._stale_operation_recovery_index_active = True
            except BaseException as setup_error:
                self._stale_operation_recovery_index_depth = 0
                self._stale_operation_recovery_index_active = False
                try:
                    self._execute(f"DROP TABLE IF EXISTS {table}")
                except BaseException as cleanup_error:
                    self._poison(
                        "stale_operation_recovery_setup_cleanup_failed",
                        diagnostic_errors=(cleanup_error,),
                    )
                    setup_error.add_note(
                        "stale operation recovery cleanup also failed; "
                        "diagnostic fingerprint retained internally"
                    )
                raise
            body_error: BaseException | None = None
            try:
                yield
            except BaseException as exc:
                body_error = exc
                raise
            finally:
                self._stale_operation_recovery_index_depth = 0
                self._stale_operation_recovery_index_active = False
                try:
                    # DROP (rather than merely DELETE) also recovers from a
                    # partially populated or malformed temporary snapshot.
                    self._execute(f"DROP TABLE IF EXISTS {table}")
                except BaseException as cleanup_error:
                    self._poison(
                        "stale_operation_recovery_cleanup_failed",
                        diagnostic_errors=(cleanup_error,),
                    )
                    if body_error is not None:
                        body_error.add_note(
                            "stale operation recovery cleanup also failed; "
                            "diagnostic fingerprint retained internally"
                        )
                    else:
                        raise ValidationError(
                            "stale operation recovery cleanup failed; store is unusable"
                        ) from None

    def _populate_stale_operation_recovery_index(self, table: str) -> None:
        self._execute(
            f"""
            WITH RECURSIVE
            uncertain_effects(effect_id) AS MATERIALIZED (
                SELECT effect_id
                  FROM external_effects
                 WHERE effect_state = ?
                UNION
                SELECT effect_id
                  FROM external_effects
                 WHERE transaction_state = ?
            ),
            unknown_nodes(
                root_operation_id,
                operation_id,
                parent_operation_id
            ) AS MATERIALIZED (
                SELECT DISTINCT operation.root_operation_id,
                       operation.operation_id,
                       operation.parent_operation_id
                  FROM uncertain_effects
                  CROSS JOIN operation_evidence AS evidence
                  CROSS JOIN operations AS operation
                 WHERE evidence.evidence_type = 'external_effect'
                   AND evidence.evidence_id = uncertain_effects.effect_id
                   AND operation.operation_id = evidence.operation_id
            ),
            ancestors(
                root_operation_id,
                operation_id,
                parent_operation_id
            ) AS (
                SELECT root_operation_id,
                       operation_id,
                       parent_operation_id
                  FROM unknown_nodes
                UNION
                SELECT ancestors.root_operation_id,
                       parent.operation_id,
                       parent.parent_operation_id
                  FROM ancestors
                  JOIN operations AS parent
                    ON parent.operation_id = ancestors.parent_operation_id
                   AND parent.root_operation_id = ancestors.root_operation_id
            )
            INSERT INTO {table} (operation_id)
            SELECT DISTINCT operation.operation_id
              FROM ancestors
              JOIN operations AS operation
                ON operation.operation_id = ancestors.operation_id
             WHERE operation.state = ?
            """,
            ("pending", "unknown", OperationState.RUNNING.value),
        )

    def operation_has_unknown_external_effect(self, operation_id: str) -> bool:
        """Test one live operation subtree with indexed recursive EXISTS."""

        if not isinstance(operation_id, str) or not operation_id:
            raise ValidationError("operation recovery id must be non-empty text")
        rows = self._query(
            """
            WITH RECURSIVE
            selected(root_operation_id, operation_id) AS (
                SELECT root_operation_id, operation_id
                  FROM operations
                 WHERE operation_id = ?
            ),
            subtree(root_operation_id, operation_id) AS (
                SELECT root_operation_id, operation_id FROM selected
                UNION
                SELECT subtree.root_operation_id, child.operation_id
                  FROM subtree
                  JOIN operations AS child
                    ON child.parent_operation_id = subtree.operation_id
                   AND child.root_operation_id = subtree.root_operation_id
            )
            SELECT EXISTS (
                SELECT 1
                  FROM subtree
                 WHERE (
                    SELECT evidence.evidence_id
                      FROM operation_evidence AS evidence
                      JOIN external_effects AS effect
                        ON effect.effect_id = evidence.evidence_id
                     WHERE evidence.operation_id = subtree.operation_id
                       AND evidence.evidence_type = 'external_effect'
                       AND (
                            effect.effect_state = ?
                            OR effect.transaction_state = ?
                       )
                     LIMIT 1
                 ) IS NOT NULL
            ) AS has_unknown_external_effect
            """,
            (operation_id, "pending", "unknown"),
        )
        return bool(rows and rows[0]["has_unknown_external_effect"])

    def update_operation(
        self,
        record: OperationRecord,
        *,
        expected_states: Iterable[str] | None = None,
    ) -> bool:
        """Replace an operation with an optional state CAS predicate.

        ``None`` disables the state predicate.  A supplied but empty iterable
        matches no state and therefore rejects the mutation.
        """

        selected_states = (
            None
            if expected_states is None
            else sorted({str(value) for value in expected_states})
        )
        if selected_states is not None and not selected_states:
            return False
        runtime_publication_id = _operation_runtime_publication_id(record.metadata)
        params: list[Any] = [
            record.root_operation_id,
            record.parent_operation_id,
            record.kind.value,
            record.name,
            record.actor,
            record.pid,
            record.state.value,
            record.outcome.value,
            dumps(record.expected_roles),
            dumps(record.metadata),
            runtime_publication_id,
            record.started_at,
            record.updated_at,
            record.completed_at,
            record.operation_id,
        ]
        where = "operation_id = ?"
        if selected_states is not None:
            placeholders = ", ".join("?" for _ in selected_states)
            where += f" AND state IN ({placeholders})"
            params.extend(selected_states)
        with self._join_or_begin_transaction():
            existing = self._query(
                "SELECT runtime_publication_id FROM operations WHERE operation_id = ?",
                (record.operation_id,),
            )
            previous_publication_id = (
                str(existing[0]["runtime_publication_id"])
                if existing and existing[0]["runtime_publication_id"] is not None
                else None
            )
            self._require_operation_publication_binding_available(
                runtime_publication_id,
                operation_id=record.operation_id,
            )
            cursor = self._execute(
                f"""
                UPDATE operations
                   SET root_operation_id = ?, parent_operation_id = ?, kind = ?, name = ?,
                       actor = ?, pid = ?, state = ?, outcome = ?, expected_roles_json = ?,
                       metadata_json = ?, runtime_publication_id = ?, started_at = ?,
                       updated_at = ?, completed_at = ?
                 WHERE {where}
                """,
                params,
            )
            if cursor.rowcount != 1:
                return False

            # Operation reconciliation is an online cache of the exact durable
            # publication/operation binding.  Any successful mutation of a
            # bound operation makes that cache stale.  Invalidate both sides
            # when a repository caller moves a binding so startup can validate
            # the old publication and fill/validate the new one without ever
            # scanning settled operation history.  This runs in the caller's
            # transaction or a repository-owned transaction with the CAS.
            self._invalidate_runtime_publication_operation_reconciliation(
                (previous_publication_id, runtime_publication_id)
            )
            return True

    def insert_operation_evidence(self, link: OperationEvidenceLink) -> bool:
        cursor = self._execute(
            """
            INSERT INTO operation_evidence (
                link_id, operation_id, evidence_type, evidence_id, role, created_at, metadata_json
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(operation_id, evidence_type, evidence_id, role) DO NOTHING
            """,
            (
                link.link_id,
                link.operation_id,
                link.evidence_type,
                link.evidence_id,
                link.role,
                link.created_at,
                dumps(link.metadata),
            ),
        )
        return cursor.rowcount == 1

    def list_operation_evidence(
        self,
        *,
        operation_ids: Iterable[str] | None = None,
        evidence_types: Iterable[str] | None = None,
        evidence_id: str | None = None,
        limit: int | None = None,
        cursor: str | None = None,
    ) -> list[OperationEvidenceLink]:
        clauses: list[str] = []
        params: list[Any] = []
        selected_operations = sorted({str(value) for value in operation_ids or []})
        if operation_ids is not None:
            if not selected_operations:
                return []
            placeholders = ", ".join("?" for _ in selected_operations)
            clauses.append(f"operation_id IN ({placeholders})")
            params.extend(selected_operations)
        selected_types = sorted({str(value) for value in evidence_types or []})
        if evidence_types is not None:
            if not selected_types:
                return []
            placeholders = ", ".join("?" for _ in selected_types)
            clauses.append(f"evidence_type IN ({placeholders})")
            params.extend(selected_types)
        if evidence_id is not None:
            clauses.append("evidence_id = ?")
            params.append(evidence_id)
        if cursor is not None:
            cursor_rows = self._query("SELECT * FROM operation_evidence WHERE link_id = ?", (cursor,))
            if not cursor_rows:
                return []
            cursor_row = cursor_rows[0]
            clauses.append("(created_at, link_id) > (?, ?)")
            params.extend((cursor_row["created_at"], cursor_row["link_id"]))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        sql = f"SELECT * FROM operation_evidence{where} ORDER BY created_at, link_id"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(max(0, int(limit)))
        return [self._row_to_operation_evidence(row) for row in self._query(sql, params)]

    def insert_context_materialization_manifest(self, manifest: ContextMaterializationManifest) -> None:
        self._execute(
            """
            INSERT INTO context_materialization_manifests (
                materialization_id, pid, view_id, policy, budget_tokens, rendered_tokens,
                rendered_sha256, context_generation, context_oid, context_version,
                objects_json, compaction_json, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                manifest.materialization_id,
                manifest.pid,
                manifest.view_id,
                manifest.policy,
                manifest.budget_tokens,
                manifest.rendered_tokens,
                manifest.rendered_sha256,
                manifest.context_generation,
                manifest.context_oid,
                manifest.context_version,
                dumps(manifest.objects),
                dumps(manifest.compaction),
                manifest.created_at,
            ),
        )

    def get_context_materialization_manifest(
        self,
        materialization_id: str,
    ) -> ContextMaterializationManifest | None:
        rows = self._query(
            "SELECT * FROM context_materialization_manifests WHERE materialization_id = ?",
            (materialization_id,),
        )
        return self._row_to_context_materialization_manifest(rows[0]) if rows else None

    def list_context_materialization_manifests(
        self,
        *,
        pid: str | None = None,
        limit: int | None = None,
    ) -> list[ContextMaterializationManifest]:
        params: list[Any] = []
        where = ""
        if pid is not None:
            where = " WHERE pid = ?"
            params.append(pid)
        sql = (
            "SELECT * FROM context_materialization_manifests"
            f"{where} ORDER BY created_at DESC, materialization_id DESC"
        )
        if limit is not None:
            sql += " LIMIT ?"
            params.append(max(0, int(limit)))
        return [self._row_to_context_materialization_manifest(row) for row in self._query(sql, params)]

    def insert_external_effect(self, record: ExternalEffectRecord) -> None:
        if (
            external_effect_payload_retention_tier(record)
            is not PayloadRetentionTier.FULL
        ):
            raise ValidationError(
                "new external effect records must contain full provider payloads"
            )
        occurred_at = record.updated_at or record.created_at
        with self.transaction() as cur:
            cur.execute(
                """
                INSERT INTO external_effects (
                    effect_id, record_id, event_id, pid, provider, operation, target,
                    rollback_class, rollback_status, state_mutation, information_flow,
                    provider_metadata_json, created_at, effect_state, transaction_state,
                    canonical_args_hash, idempotency_key, provider_receipt_json, updated_at,
                    payload_retention_schema_version, payload_retention_tier,
                    payload_retention_sha256
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    record.effect_id,
                    record.record_id,
                    record.event_id,
                    record.pid,
                    record.provider,
                    record.operation,
                    record.target,
                    record.rollback_class.value,
                    record.rollback_status.value,
                    int(record.state_mutation),
                    int(record.information_flow),
                    dumps(record.provider_metadata),
                    record.created_at,
                    record.effect_state,
                    record.transaction_state,
                    record.canonical_args_hash,
                    record.idempotency_key,
                    dumps(record.provider_receipt),
                    occurred_at,
                    record.payload_retention_schema_version,
                    record.payload_retention_tier,
                    record.payload_retention_sha256,
                ),
            )
            self._append_external_effect_transition(
                cur,
                effect_id=record.effect_id,
                effect_state=record.effect_state,
                transaction_state=record.transaction_state,
                occurred_at=occurred_at,
            )

    def finalize_external_effect(self, intent_effect_id: str, record: ExternalEffectRecord) -> bool:
        if record.effect_id != intent_effect_id:
            raise ValidationError("external effect finalization record id must match intent id")
        if record.effect_state != "finalized":
            raise ValidationError("external effect finalization record must be finalized")
        if (
            external_effect_payload_retention_tier(record)
            is not PayloadRetentionTier.FULL
        ):
            raise ValidationError(
                "external effect finalization must contain full provider payloads"
            )
        occurred_at = record.updated_at or record.created_at
        with self.transaction() as cur:
            cursor = cur.execute(
                """
                UPDATE external_effects
               SET record_id = ?, event_id = ?, rollback_class = ?, rollback_status = ?,
                   state_mutation = ?, information_flow = ?, provider_metadata_json = ?, created_at = ?,
                   effect_state = ?, transaction_state = ?, canonical_args_hash = ?,
                   idempotency_key = ?, provider_receipt_json = ?, updated_at = ?,
                   payload_retention_schema_version = ?, payload_retention_tier = ?,
                   payload_retention_sha256 = ?
             WHERE effect_id = ?
               AND pid = ?
               AND provider = ?
               AND operation = ?
               AND ((target IS NULL AND CAST(? AS TEXT) IS NULL) OR target = ?)
               AND record_id IS NULL
               AND event_id IS NULL
               AND rollback_class = ?
               AND rollback_status = ?
               AND effect_state = 'pending'
                """,
                (
                record.record_id,
                record.event_id,
                record.rollback_class.value,
                record.rollback_status.value,
                int(record.state_mutation),
                int(record.information_flow),
                dumps(record.provider_metadata),
                record.created_at,
                record.effect_state,
                record.transaction_state,
                record.canonical_args_hash,
                record.idempotency_key,
                dumps(record.provider_receipt),
                record.updated_at or record.created_at,
                record.payload_retention_schema_version,
                record.payload_retention_tier,
                record.payload_retention_sha256,
                intent_effect_id,
                record.pid,
                record.provider,
                record.operation,
                record.target,
                record.target,
                ExternalEffectRollbackClass.UNKNOWN.value,
                ExternalEffectRollbackStatus.UNKNOWN.value,
                ),
            )
            if cursor.rowcount != 1:
                return False
            self._append_external_effect_transition(
                cur,
                effect_id=record.effect_id,
                effect_state=record.effect_state,
                transaction_state=record.transaction_state,
                occurred_at=occurred_at,
            )
            return True

    def transition_external_effect(
        self,
        effect_id: str,
        *,
        expected_states: Iterable[str],
        transaction_state: str,
        provider_metadata: dict[str, Any] | None = None,
        provider_receipt: dict[str, Any] | None = None,
        updated_at: str,
    ) -> bool:
        states = list(dict.fromkeys(str(state) for state in expected_states))
        if not states:
            raise ValidationError("external effect transition requires expected states")
        placeholders = ", ".join("?" for _ in states)
        with self.transaction() as cur:
            rows = list(cur.execute("SELECT * FROM external_effects WHERE effect_id = ?", (effect_id,)))
            if not rows:
                return False
            current = self._row_to_external_effect(rows[0])
            if current.transaction_state not in states:
                return False
            if (
                external_effect_payload_retention_tier(current)
                is not PayloadRetentionTier.FULL
            ):
                raise ValidationError(
                    "retained external effect payloads cannot be transitioned"
                )
            cursor = cur.execute(
                f"""
                UPDATE external_effects
                   SET transaction_state = ?, provider_metadata_json = ?,
                       provider_receipt_json = ?, updated_at = ?
                 WHERE effect_id = ? AND transaction_state IN ({placeholders})
                """,
                (
                    transaction_state,
                    dumps(provider_metadata if provider_metadata is not None else current.provider_metadata),
                    dumps(provider_receipt if provider_receipt is not None else current.provider_receipt),
                    updated_at,
                    effect_id,
                    *states,
                ),
            )
            if cursor.rowcount != 1:
                return False
            self._append_external_effect_transition(
                cur,
                effect_id=effect_id,
                effect_state=current.effect_state,
                transaction_state=transaction_state,
                occurred_at=updated_at,
            )
            return True

    def settle_external_effect_recovery(
        self,
        effect_id: str,
        *,
        expected_transaction_state: str,
        provider_state: str,
        provider_metadata: dict[str, Any],
        provider_receipt: dict[str, Any],
        audit_record: AuditRecord,
        updated_at: str,
        run_id: str | None = None,
        runtime_epoch: int | None = None,
    ) -> ExternalEffectRecoverySettlement | None:
        """CAS one provider-verified recovery result and its local evidence.

        Provider verification is intentionally outside the storage boundary.
        This method owns the second, durable half of the protocol: exact old
        state and optional TaskRun epoch fencing, reservation convergence, the
        effect transition, and its audit row all commit together.
        """

        settled_transaction_state = self._validate_external_effect_recovery_request(
            effect_id=effect_id,
            expected_transaction_state=expected_transaction_state,
            provider_state=provider_state,
            provider_metadata=provider_metadata,
            provider_receipt=provider_receipt,
            audit_record=audit_record,
            updated_at=updated_at,
            run_id=run_id,
            runtime_epoch=runtime_epoch,
        )
        with self.transaction() as cur:
            current = self._load_external_effect_recovery_candidate(
                cur,
                effect_id=effect_id,
                expected_transaction_state=expected_transaction_state,
                run_id=run_id,
                runtime_epoch=runtime_epoch,
            )
            if current is None:
                return None
            capability_reservation_ids = (
                self._external_effect_recovery_capability_reservation_ids(current)
            )
            if provider_state == "not_started":
                self._require_external_effect_globally_not_started(current)
            if not self._update_external_effect_recovery_candidate(
                cur,
                current=current,
                expected_transaction_state=expected_transaction_state,
                provider_state=provider_state,
                settled_transaction_state=settled_transaction_state,
                provider_metadata=provider_metadata,
                provider_receipt=provider_receipt,
                audit_record_id=audit_record.record_id,
                updated_at=updated_at,
            ):
                return None
            restored, committed, released = (
                self._converge_external_effect_recovery_reservations(
                    cur,
                    current=current,
                    capability_reservation_ids=capability_reservation_ids,
                    provider_state=provider_state,
                    updated_at=updated_at,
                )
            )
            return self._record_external_effect_recovery_settlement(
                cur,
                effect_id=effect_id,
                previous_transaction_state=expected_transaction_state,
                provider_state=provider_state,
                settled_transaction_state=settled_transaction_state,
                audit_record=audit_record,
                updated_at=updated_at,
                restored_capabilities=restored,
                committed_capabilities=committed,
                released_resources=released,
            )

    @staticmethod
    def _validate_external_effect_recovery_request(
        *,
        effect_id: str,
        expected_transaction_state: str,
        provider_state: str,
        provider_metadata: dict[str, Any],
        provider_receipt: dict[str, Any],
        audit_record: AuditRecord,
        updated_at: str,
        run_id: str | None,
        runtime_epoch: int | None,
    ) -> str:
        if not isinstance(effect_id, str) or not effect_id:
            raise ValidationError("external effect recovery requires an effect id")
        if expected_transaction_state not in {
            "prepared",
            "authorized",
            "approved",
            "dispatched",
            "unknown",
        }:
            raise ValidationError(
                "external effect recovery expected state is not recoverable"
            )
        if provider_state not in {
            "committed",
            "failed",
            "compensated",
            "not_started",
        }:
            raise ValidationError("external effect recovery provider state is invalid")
        if (
            expected_transaction_state == "prepared"
            and provider_state != "not_started"
        ):
            raise ValidationError(
                "prepared external effect recovery requires a certified "
                "not-started provider conclusion"
            )
        if not isinstance(provider_metadata, dict):
            raise ValidationError("external effect recovery metadata must be an object")
        if not isinstance(provider_receipt, dict) or not provider_receipt:
            raise ValidationError(
                "external effect recovery requires a non-empty provider receipt"
            )
        if not isinstance(audit_record, AuditRecord):
            raise ValidationError("external effect recovery requires an audit record")
        if (
            audit_record.action != "external_effect.recovery_settled"
            or audit_record.target != f"external_effect:{effect_id}"
        ):
            raise ValidationError(
                "external effect recovery audit is not bound to the effect"
            )
        if not isinstance(updated_at, str) or not updated_at:
            raise ValidationError("external effect recovery timestamp must not be empty")
        SQLRuntimeStore._validate_external_effect_recovery_run_fence(
            run_id,
            runtime_epoch,
        )
        return "failed" if provider_state == "not_started" else provider_state

    @staticmethod
    def _validate_external_effect_recovery_run_fence(
        run_id: str | None,
        runtime_epoch: int | None,
    ) -> None:
        if (run_id is None) != (runtime_epoch is None):
            raise ValidationError(
                "external effect recovery TaskRun id and epoch must be supplied together"
            )
        if run_id is not None and (not isinstance(run_id, str) or not run_id):
            raise ValidationError("external effect recovery TaskRun id must not be empty")
        if runtime_epoch is not None and (
            type(runtime_epoch) is not int or runtime_epoch <= 0
        ):
            raise ValidationError(
                "external effect recovery TaskRun epoch must be positive"
            )

    def _load_external_effect_recovery_candidate(
        self,
        cur: Any,
        *,
        effect_id: str,
        expected_transaction_state: str,
        run_id: str | None,
        runtime_epoch: int | None,
    ) -> ExternalEffectRecord | None:
        rows = list(
            cur.execute(
                "SELECT * FROM external_effects WHERE effect_id = ?",
                (effect_id,),
            )
        )
        if not rows:
            return None
        current = self._row_to_external_effect(rows[0])
        if (
            current.effect_state != "pending"
            or current.transaction_state != expected_transaction_state
        ):
            return None
        if (
            external_effect_payload_retention_tier(current)
            is not PayloadRetentionTier.FULL
        ):
            raise ValidationError(
                "retained external effect payloads cannot be recovered"
            )
        if run_id is None:
            return current
        membership = list(
            cur.execute(
                """
                SELECT process.pid
                  FROM processes AS process
                  JOIN task_runs AS run
                    ON run.run_id = process.task_run_id
                   AND run.runtime_epoch = process.task_run_epoch
                 WHERE process.pid = ?
                   AND process.task_run_id = ?
                   AND process.task_run_epoch = ?
                   AND run.runtime_epoch = ?
                """,
                (current.pid, run_id, runtime_epoch, runtime_epoch),
            )
        )
        return current if len(membership) == 1 else None

    @staticmethod
    def _update_external_effect_recovery_candidate(
        cur: Any,
        *,
        current: ExternalEffectRecord,
        expected_transaction_state: str,
        provider_state: str,
        settled_transaction_state: str,
        provider_metadata: dict[str, Any],
        provider_receipt: dict[str, Any],
        audit_record_id: str,
        updated_at: str,
    ) -> bool:
        changed = cur.execute(
            """
            UPDATE external_effects
               SET record_id = COALESCE(record_id, ?),
                   effect_state = 'finalized', transaction_state = ?,
                   provider_metadata_json = ?, provider_receipt_json = ?,
                   idempotency_key = ?, updated_at = ?
             WHERE effect_id = ?
               AND effect_state = 'pending'
               AND transaction_state = ?
            """,
            (
                audit_record_id,
                settled_transaction_state,
                dumps(provider_metadata),
                dumps(provider_receipt),
                None if provider_state == "not_started" else current.idempotency_key,
                updated_at,
                current.effect_id,
                expected_transaction_state,
            ),
        )
        return changed.rowcount == 1

    def _converge_external_effect_recovery_reservations(
        self,
        cur: Any,
        *,
        current: ExternalEffectRecord,
        capability_reservation_ids: tuple[str, ...],
        provider_state: str,
        updated_at: str,
    ) -> tuple[tuple[str, ...], tuple[str, ...], tuple[str, ...]]:
        restored: list[str] = []
        committed: list[str] = []
        for reservation_id in capability_reservation_ids:
            if provider_state == "not_started":
                self._restore_external_effect_capability_reservation(
                    cur,
                    current,
                    reservation_id=reservation_id,
                    updated_at=updated_at,
                )
                restored.append(reservation_id)
            else:
                self._commit_external_effect_capability_reservation(
                    cur,
                    current,
                    reservation_id=reservation_id,
                    updated_at=updated_at,
                )
                committed.append(reservation_id)
        released = self._release_external_effect_resource_reservations(
            cur,
            current,
            updated_at=updated_at,
            release=provider_state == "not_started",
        )
        return tuple(restored), tuple(committed), released

    def _record_external_effect_recovery_settlement(
        self,
        cur: Any,
        *,
        effect_id: str,
        previous_transaction_state: str,
        provider_state: str,
        settled_transaction_state: str,
        audit_record: AuditRecord,
        updated_at: str,
        restored_capabilities: tuple[str, ...],
        committed_capabilities: tuple[str, ...],
        released_resources: tuple[str, ...],
    ) -> ExternalEffectRecoverySettlement:
        transition_seq = self._append_external_effect_transition(
            cur,
            effect_id=effect_id,
            effect_state="finalized",
            transaction_state=settled_transaction_state,
            occurred_at=updated_at,
        )
        selected_audit = replace(
            audit_record,
            decision={
                **dict(audit_record.decision or {}),
                "previous_transaction_state": previous_transaction_state,
                "provider_state": provider_state,
                "settled_transaction_state": settled_transaction_state,
                "restored_capability_reservation_ids": list(restored_capabilities),
                "committed_capability_reservation_ids": list(committed_capabilities),
                "released_resource_reservation_ids": list(released_resources),
                "transition_seq": transition_seq,
            },
        )
        self.insert_audit(selected_audit)
        settled_rows = list(
            cur.execute(
                "SELECT * FROM external_effects WHERE effect_id = ?",
                (effect_id,),
            )
        )
        if len(settled_rows) != 1:
            raise ValidationError(
                "external effect recovery row disappeared during settlement"
            )
        settled = self._row_to_external_effect(settled_rows[0])
        return ExternalEffectRecoverySettlement(
            effect=settled,
            previous_transaction_state=previous_transaction_state,
            provider_state=provider_state,
            transition_seq=transition_seq,
            audit_record_id=selected_audit.record_id,
            restored_capability_reservation_ids=restored_capabilities,
            committed_capability_reservation_ids=committed_capabilities,
            released_resource_reservation_ids=released_resources,
        )

    @staticmethod
    def _external_effect_recovery_capability_reservation_ids(
        effect: ExternalEffectRecord,
    ) -> tuple[str, ...]:
        protected = effect.provider_metadata.get("protected_operation")
        if protected is None:
            return ()
        if not isinstance(protected, Mapping):
            raise ValidationError(
                "external effect recovery protected-operation evidence is invalid"
            )
        raw = protected.get("reservation_ids")
        if not isinstance(raw, (list, tuple)) or any(
            not isinstance(item, str) or not item for item in raw
        ):
            raise ValidationError(
                "external effect recovery capability reservations are invalid"
            )
        selected = tuple(raw)
        if len(selected) != len(set(selected)):
            raise ValidationError(
                "external effect recovery capability reservations are duplicated"
            )
        return selected

    @staticmethod
    def _require_external_effect_globally_not_started(
        effect: ExternalEffectRecord,
    ) -> None:
        phases = effect.provider_metadata.get("completed_provider_phases") or []
        if not isinstance(phases, list) or any(
            not isinstance(phase, Mapping) for phase in phases
        ):
            raise ValidationError(
                "external effect recovery provider phase evidence is invalid"
            )
        if any(
            bool(phase.get("state_mutation"))
            or bool(phase.get("information_flow"))
            or bool(phase.get("commits_authority"))
            for phase in phases
        ):
            raise ValidationError(
                "phase-local not-started receipt cannot erase an earlier provider effect"
            )

    @staticmethod
    def _external_effect_reservation_identity(
        effect: ExternalEffectRecord,
    ) -> tuple[str, str]:
        protected = effect.provider_metadata.get("protected_operation")
        if not isinstance(protected, Mapping):
            raise ValidationError(
                "external effect recovery reservation identity is missing"
            )
        actor = protected.get("actor")
        contract_name = protected.get("contract_name")
        if not isinstance(actor, str) or not actor or not isinstance(
            contract_name, str
        ) or not contract_name:
            raise ValidationError(
                "external effect recovery reservation identity is invalid"
            )
        return actor, contract_name

    def _restore_external_effect_capability_reservation(
        self,
        cur: Any,
        effect: ExternalEffectRecord,
        *,
        reservation_id: str,
        updated_at: str,
    ) -> None:
        actor, contract_name = self._external_effect_reservation_identity(effect)
        rows = list(
            cur.execute(
                "SELECT * FROM capability_use_reservations WHERE reservation_id = ?",
                (reservation_id,),
            )
        )
        if len(rows) != 1:
            raise ValidationError(
                "external effect recovery capability reservation is missing"
            )
        reservation = rows[0]
        if (
            reservation["status"] != "reserved"
            or reservation["reserved_by"] != actor
            or reservation["reason"]
            != f"protected operation reserved authority for {contract_name}"
        ):
            raise ValidationError(
                "external effect recovery capability reservation binding changed"
            )
        try:
            count = _positive_capability_use_count(
                reservation["count"],
                label="persisted capability reservation count",
            )
        except ValueError as exc:
            raise ValidationError(str(exc)) from exc
        restored = cur.execute(
            """
            UPDATE capabilities
               SET uses_remaining = uses_remaining + ?,
                   status = CASE WHEN status = ? THEN ? ELSE status END
             WHERE cap_id = ?
               AND uses_remaining IS NOT NULL
               AND status IN (?, ?)
            """,
            (
                count,
                CapabilityStatus.REVOKED.value,
                CapabilityStatus.ACTIVE.value,
                reservation["cap_id"],
                CapabilityStatus.ACTIVE.value,
                CapabilityStatus.REVOKED.value,
            ),
        )
        if restored.rowcount != 1:
            raise ValidationError(
                "external effect recovery capability could not be restored"
            )
        changed = cur.execute(
            """
            UPDATE capability_use_reservations
               SET status = 'restored', updated_at = ?
             WHERE reservation_id = ? AND status = 'reserved'
            """,
            (updated_at, reservation_id),
        )
        if changed.rowcount != 1:
            raise ValidationError(
                "external effect recovery capability reservation raced"
            )

    def _commit_external_effect_capability_reservation(
        self,
        cur: Any,
        effect: ExternalEffectRecord,
        *,
        reservation_id: str,
        updated_at: str,
    ) -> None:
        actor, contract_name = self._external_effect_reservation_identity(effect)
        rows = list(
            cur.execute(
                "SELECT * FROM capability_use_reservations WHERE reservation_id = ?",
                (reservation_id,),
            )
        )
        if len(rows) != 1:
            raise ValidationError(
                "external effect recovery capability reservation is missing"
            )
        reservation = rows[0]
        if (
            reservation["reserved_by"] != actor
            or reservation["reason"]
            != f"protected operation reserved authority for {contract_name}"
            or reservation["status"] not in {"reserved", "committed"}
        ):
            raise ValidationError(
                "external effect recovery capability reservation binding changed"
            )
        if reservation["status"] == "reserved":
            changed = cur.execute(
                """
                UPDATE capability_use_reservations
                   SET status = 'committed', updated_at = ?
                 WHERE reservation_id = ? AND status = 'reserved'
                """,
                (updated_at, reservation_id),
            )
            if changed.rowcount != 1:
                raise ValidationError(
                    "external effect recovery capability reservation raced"
                )

    @staticmethod
    def _release_external_effect_resource_reservations(
        cur: Any,
        effect: ExternalEffectRecord,
        *,
        updated_at: str,
        release: bool,
    ) -> tuple[str, ...]:
        rows = list(
            cur.execute(
                "SELECT * FROM resource_usage_reservations WHERE reserved_by = ? "
                "ORDER BY reservation_id",
                (effect.effect_id,),
            )
        )
        if any(str(row["pid"]) != effect.pid for row in rows):
            raise ValidationError(
                "external effect recovery resource reservation binding changed"
            )
        if not release:
            return ()
        released: list[str] = []
        for row in rows:
            if row["status"] != ResourceUsageReservationStatus.ACTIVE.value:
                raise ValidationError(
                    "external effect recovery resource reservation is no longer active"
                )
            reservation_id = str(row["reservation_id"])
            changed = cur.execute(
                """
                UPDATE resource_usage_reservations
                   SET status = ?, settled_usage_json = ?, updated_at = ?
                 WHERE reservation_id = ? AND status = ?
                """,
                (
                    ResourceUsageReservationStatus.RELEASED.value,
                    dumps(ResourceUsage()),
                    updated_at,
                    reservation_id,
                    ResourceUsageReservationStatus.ACTIVE.value,
                ),
            )
            if changed.rowcount != 1:
                raise ValidationError(
                    "external effect recovery resource reservation raced"
                )
            released.append(reservation_id)
        return tuple(released)

    def current_effect_ledger_seq(self) -> int:
        rows = self._query(
            "SELECT value FROM runtime_counters WHERE counter_name = ?",
            ("external_effect_ledger",),
        )
        if not rows:
            raise ValidationError("external effect ledger counter is missing")
        return int(rows[0]["value"])

    def external_effect_transition_matches(
        self,
        transition_seq: int,
        effect_id: str,
        *,
        effect_state: str,
        transaction_state: str,
    ) -> bool:
        if (
            type(transition_seq) is not int
            or transition_seq <= 0
            or transition_seq > 2**63 - 1
            or not isinstance(effect_id, str)
            or not effect_id
            or not isinstance(effect_state, str)
            or not effect_state
            or not isinstance(transaction_state, str)
            or not transaction_state
        ):
            raise ValidationError("external effect transition identity is invalid")
        rows = self._query(
            "SELECT 1 FROM external_effect_transitions "
            "WHERE seq = ? AND effect_id = ? AND effect_state = ? "
            "AND transaction_state = ? LIMIT 1",
            (
                transition_seq,
                effect_id,
                effect_state,
                transaction_state,
            ),
        )
        return len(rows) == 1

    def list_external_effects_changed_after(
        self,
        effect_ledger_seq: int,
        *,
        pids: Iterable[str] | None = None,
    ) -> list[ExternalEffectRecord]:
        """Read current rows for every effect changed after one ledger sequence.

        The transition ledger may contain many entries for the same effect and
        may be arbitrarily newer than an old checkpoint.  Keep the identity
        join inside SQL so neither those duplicates nor all changed effect IDs
        become Python data or one unbounded bind list.  A transaction pins all
        PID batches and keyset pages to one consistent current-row snapshot.
        """

        if type(effect_ledger_seq) is not int or effect_ledger_seq < 0:
            raise ValidationError(
                "external effect ledger sequence must be a non-negative integer"
            )
        with self.transaction() as cur:
            if pids is None:
                rows = self._query_external_effect_changes(
                    cur,
                    effect_ledger_seq=effect_ledger_seq,
                    pid_batch=None,
                )
            else:
                rows = []
                found_pid = False
                for pid_batch in self._external_effect_pid_batches(pids):
                    found_pid = True
                    rows.extend(
                        self._query_external_effect_changes(
                            cur,
                            effect_ledger_seq=effect_ledger_seq,
                            pid_batch=pid_batch,
                        )
                    )
                if not found_pid:
                    return []
        rows.sort(key=lambda row: (str(row["created_at"]), str(row["effect_id"])))
        return [self._row_to_external_effect(row) for row in rows]

    @staticmethod
    def _external_effect_pid_batches(
        pids: Iterable[str],
    ) -> Iterator[tuple[str, ...]]:
        seen: set[str] = set()
        batch: list[str] = []
        for pid in pids:
            if not isinstance(pid, str) or not pid:
                raise ValidationError("external effect PID filters must be non-empty text")
            if pid in seen:
                continue
            seen.add(pid)
            batch.append(pid)
            if len(batch) == _EXTERNAL_EFFECT_CHANGE_QUERY_BATCH_SIZE:
                yield tuple(batch)
                batch.clear()
        if batch:
            yield tuple(batch)

    def _query_external_effect_changes(
        self,
        cur: Any,
        *,
        effect_ledger_seq: int,
        pid_batch: tuple[str, ...] | None,
    ) -> list[Any]:
        rows: list[Any] = []
        after: tuple[str, str] | None = None
        while True:
            clauses = [
                "EXISTS ("
                "SELECT 1 FROM external_effect_transitions AS effect_change "
                "WHERE effect_change.effect_id = effect.effect_id "
                "AND effect_change.seq > ?"
                ")"
            ]
            params: list[Any] = [effect_ledger_seq]
            if pid_batch is not None:
                clauses.append(
                    f"effect.pid IN ({', '.join('?' for _ in pid_batch)})"
                )
                params.extend(pid_batch)
            if after is not None:
                clauses.append("(effect.created_at, effect.effect_id) > (?, ?)")
                params.extend(after)
            params.append(_EXTERNAL_EFFECT_CHANGE_QUERY_BATCH_SIZE)
            page = list(
                cur.execute(
                    "SELECT effect.* FROM external_effects AS effect "
                    f"WHERE {' AND '.join(clauses)} "
                    "ORDER BY effect.created_at, effect.effect_id LIMIT ?",
                    params,
                )
            )
            rows.extend(page)
            if len(page) < _EXTERNAL_EFFECT_CHANGE_QUERY_BATCH_SIZE:
                return rows
            last = page[-1]
            after = (str(last["created_at"]), str(last["effect_id"]))

    def _append_external_effect_transition(
        self,
        cur: Any,
        *,
        effect_id: str,
        effect_state: str,
        transaction_state: str,
        occurred_at: str,
    ) -> int:
        updated = cur.execute(
            """
            UPDATE runtime_counters
               SET value = value + 1
             WHERE counter_name = ?
            """,
            ("external_effect_ledger",),
        )
        if updated.rowcount != 1:
            raise ValidationError("external effect ledger counter is missing")
        rows = list(
            cur.execute(
                "SELECT value FROM runtime_counters WHERE counter_name = ?",
                ("external_effect_ledger",),
            )
        )
        seq = int(rows[0]["value"])
        cur.execute(
            """
            INSERT INTO external_effect_transitions (
                seq, effect_id, effect_state, transaction_state, occurred_at
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (seq, effect_id, effect_state, transaction_state, occurred_at),
        )
        return seq

    def abandon_external_effect_intent(self, effect_id: str) -> bool:
        cursor = self._execute(
            """
            DELETE FROM external_effects
             WHERE effect_id = ?
               AND record_id IS NULL
               AND event_id IS NULL
               AND rollback_class = ?
               AND rollback_status = ?
               AND effect_state = 'pending'
            """,
            (
                effect_id,
                ExternalEffectRollbackClass.UNKNOWN.value,
                ExternalEffectRollbackStatus.UNKNOWN.value,
            ),
        )
        return cursor.rowcount == 1

    def list_external_effects(
        self,
        *,
        created_after: str | None = None,
        pid: str | None = None,
        pids: Iterable[str] | None = None,
    ) -> list[ExternalEffectRecord]:
        clauses: list[str] = []
        params: list[Any] = []
        if created_after is not None:
            clauses.append("created_at > ?")
            params.append(created_after)
        if pid is not None:
            clauses.append("pid = ?")
            params.append(pid)
        if pids is not None:
            selected_pids = list(dict.fromkeys(str(item) for item in pids))
            if not selected_pids:
                return []
            placeholders = ", ".join("?" for _ in selected_pids)
            clauses.append(f"pid IN ({placeholders})")
            params.extend(selected_pids)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        rows = self._query(
            f"SELECT * FROM external_effects{where} ORDER BY created_at, effect_id",
            params,
        )
        return [self._row_to_external_effect(row) for row in rows]

    def query_external_effect_recovery(
        self,
        query: ExternalEffectRecoveryQuery,
    ) -> ExternalEffectPage:
        hard_limit = self.config.runtime.external_effect_recovery_page_hard_limit
        if query.limit > hard_limit:
            raise ValidationError(
                "external effect recovery page limit exceeds configured hard limit: "
                f"{query.limit} > {hard_limit}"
            )
        clauses = ["effect_state = ?"]
        params: list[Any] = [query.effect_state]
        if query.transaction_states:
            placeholders = ", ".join("?" for _ in query.transaction_states)
            clauses.append(f"transaction_state IN ({placeholders})")
            params.extend(query.transaction_states)
        if query.after is not None:
            clauses.append("(created_at, effect_id) > (?, ?)")
            params.extend(
                (
                    query.after.created_at,
                    query.after.effect_id,
                )
            )
        params.append(query.limit + 1)
        rows = self._query(
            f"""
            SELECT * FROM external_effects
             WHERE {' AND '.join(clauses)}
             ORDER BY created_at, effect_id
             LIMIT ?
            """,
            params,
        )
        selected_rows = rows[: query.limit]
        records = tuple(
            self._row_to_external_effect(row) for row in selected_rows
        )
        next_cursor = None
        if len(rows) > query.limit and records:
            last = records[-1]
            next_cursor = ExternalEffectCursor(last.created_at, last.effect_id)
        return ExternalEffectPage(records=records, next_cursor=next_cursor)

    def get_external_effect_by_idempotency(
        self,
        pid: str,
        idempotency_key: str,
    ) -> ExternalEffectRecord | None:
        rows = self._query(
            """
            SELECT * FROM external_effects
             WHERE pid = ? AND idempotency_key = ?
            """,
            (pid, idempotency_key),
        )
        if len(rows) > 1:
            raise ValidationError(
                "external effect idempotency index returned duplicate rows"
            )
        return self._row_to_external_effect(rows[0]) if rows else None

    def get_external_effect(self, effect_id: str) -> ExternalEffectRecord | None:
        rows = self._query("SELECT * FROM external_effects WHERE effect_id = ?", (effect_id,))
        return self._row_to_external_effect(rows[0]) if rows else None

    def scan_external_effect_payloads_for_retention(
        self,
        *,
        older_than: str,
        after: PayloadRetentionCursor | None,
        limit: int,
    ) -> PayloadRetentionPage[ExternalEffectRecord]:
        """Read one bounded external-effect retention page by stable keyset."""

        selected_limit = self._payload_retention_limit(limit)
        if not isinstance(older_than, str) or not older_than:
            raise ValidationError("payload retention older_than must not be empty")
        clauses = [
            "effect_state = 'finalized'",
            "transaction_state IN ('committed', 'failed', 'compensated')",
            "payload_retention_tier IN ('full', 'summary')",
            "created_at <= ?",
        ]
        params: list[Any] = [older_than]
        if after is not None:
            clauses.append("(created_at, effect_id) > (?, ?)")
            params.extend((after.created_at, after.record_id))
        params.append(selected_limit + 1)
        rows = self._query(
            f"""
            SELECT source.*
              FROM external_effects AS source
              JOIN (
                    SELECT effect_id, created_at
                      FROM external_effects INDEXED BY idx_external_effects_retention_eligible
                     WHERE {' AND '.join(clauses)}
                     ORDER BY created_at, effect_id
                     LIMIT ?
                   ) AS candidates
                ON candidates.effect_id = source.effect_id
             ORDER BY candidates.created_at, candidates.effect_id
            """,
            params,
        )
        records = tuple(
            self._row_to_external_effect(row) for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = PayloadRetentionCursor(last.created_at, last.effect_id)
        return PayloadRetentionPage(records=records, next_cursor=next_cursor)

    def update_external_effect_payload_retention(
        self,
        record: ExternalEffectRecord,
        *,
        expected_payload_sha256: str,
        expected_tier: PayloadRetentionTier,
        expected_effect_state: str,
        expected_transaction_state: str,
    ) -> bool:
        """CAS-update only reducible payload columns of one terminal effect."""

        with self.transaction() as cur:
            rows = list(
                cur.execute(
                    "SELECT * FROM external_effects WHERE effect_id = ?",
                    (record.effect_id,),
                )
            )
            if len(rows) != 1:
                return False
            current = self._row_to_external_effect(rows[0])
            try:
                validate_external_effect_payload_retention_update(
                    current,
                    record,
                    expected_payload_sha256=expected_payload_sha256,
                    expected_tier=expected_tier,
                    expected_effect_state=expected_effect_state,
                    expected_transaction_state=expected_transaction_state,
                )
            except (TypeError, ValueError):
                return False
            updated = cur.execute(
                """
                UPDATE external_effects
                   SET provider_metadata_json = ?, provider_receipt_json = ?,
                       payload_retention_schema_version = ?,
                       payload_retention_tier = ?, payload_retention_sha256 = ?
                 WHERE effect_id = ?
                   AND effect_state = ?
                   AND transaction_state = ?
                   AND payload_retention_schema_version = ?
                   AND payload_retention_tier = ?
                   AND (
                        (payload_retention_sha256 IS NULL AND CAST(? AS TEXT) IS NULL)
                        OR payload_retention_sha256 = ?
                   )
                   AND provider_metadata_json = ?
                   AND provider_receipt_json = ?
                """,
                (
                    dumps(record.provider_metadata),
                    dumps(record.provider_receipt),
                    record.payload_retention_schema_version,
                    record.payload_retention_tier,
                    record.payload_retention_sha256,
                    record.effect_id,
                    expected_effect_state,
                    expected_transaction_state,
                    current.payload_retention_schema_version,
                    current.payload_retention_tier,
                    current.payload_retention_sha256,
                    current.payload_retention_sha256,
                    dumps(current.provider_metadata),
                    dumps(current.provider_receipt),
                ),
            )
            return updated.rowcount == 1

    def list_task_run_external_effects(
        self,
        run_id: str,
        linked_pids: Iterable[str] = (),
    ) -> list[ExternalEffectRecord]:
        """List only effects with both Run membership and durable link evidence."""

        with self._join_or_begin_transaction() as cur:
            pids = self._validated_task_run_pid_scope(run_id, linked_pids)
            if not pids:
                return []
            hard_limit = self.config.task_runs.recovery_page_hard_limit
            rows_by_id: dict[str, Any] = {}
            for offset in range(0, len(pids), 400):
                batch = pids[offset : offset + 400]
                rows = list(
                    cur.execute(
                        "SELECT effect.* FROM external_effects AS effect "
                        "JOIN processes AS process ON process.pid = effect.pid "
                        "WHERE process.task_run_id = ? "
                        f"AND effect.pid IN ({', '.join('?' for _ in batch)}) "
                        "AND EXISTS ("
                        "  SELECT 1 FROM task_run_links AS link "
                        "  WHERE link.run_id = ? "
                        "    AND link.evidence_type = 'external_effect' "
                        "    AND link.evidence_id = effect.effect_id"
                        ") ORDER BY effect.created_at, effect.effect_id LIMIT ?",
                        (run_id, *batch, run_id, hard_limit + 1),
                    )
                )
                for row in rows:
                    rows_by_id[str(row["effect_id"])] = row
                if len(rows_by_id) > hard_limit:
                    raise ValidationError(
                        "TaskRun external effects exceed the recovery hard cap"
                    )
        rows = sorted(
            rows_by_id.values(),
            key=lambda row: (str(row["created_at"]), str(row["effect_id"])),
        )
        return [self._row_to_external_effect(row) for row in rows]

    def redact_task_run_external_effect_payload(
        self,
        record: ExternalEffectRecord,
        *,
        run_id: str,
        expected_payload_sha256: str,
        expected_tier: str,
        expected_effect_state: str,
        expected_transaction_state: str,
    ) -> bool:
        """CAS one canonical Run-linked effect payload reduction."""

        if not isinstance(record, ExternalEffectRecord):
            return False
        try:
            source_tier = PayloadRetentionTier(expected_tier)
        except (TypeError, ValueError):
            return False
        with self._join_or_begin_transaction() as cur:
            row = self._task_run_external_effect_redaction_source(
                cur,
                run_id=run_id,
                effect_id=record.effect_id,
            )
            if row is None:
                return False
            current = self._row_to_external_effect(row)
            try:
                target_tier = validate_external_effect_payload_retention_update(
                    current,
                    record,
                    expected_payload_sha256=expected_payload_sha256,
                    expected_tier=source_tier,
                    expected_effect_state=expected_effect_state,
                    expected_transaction_state=expected_transaction_state,
                )
            except (TypeError, ValueError):
                return False
            if not self._task_run_external_effect_identity_matches(current, record):
                return False
            return self._redact_task_run_external_effect_payload_cas(
                cur,
                current=current,
                target=record,
                target_tier=target_tier,
                run_id=run_id,
                expected_effect_state=expected_effect_state,
                expected_transaction_state=expected_transaction_state,
            )

    @staticmethod
    def _task_run_external_effect_redaction_source(
        cursor: Any,
        *,
        run_id: str,
        effect_id: str,
    ) -> Any | None:
        return cursor.execute(
            """
            SELECT effect.* FROM external_effects AS effect
            JOIN processes AS process ON process.pid = effect.pid
            JOIN task_runs AS run ON run.run_id = process.task_run_id
            WHERE effect.effect_id = ? AND process.task_run_id = ?
              AND run.status IN (
                'finalizing', 'succeeded', 'failed', 'cancelled'
              )
              AND EXISTS (
                SELECT 1 FROM task_run_links AS link
                WHERE link.run_id = run.run_id
                  AND link.evidence_type = 'external_effect'
                  AND link.evidence_id = effect.effect_id
              )
            """,
            (effect_id, run_id),
        ).fetchone()

    @staticmethod
    def _task_run_external_effect_identity_matches(
        current: ExternalEffectRecord,
        target: ExternalEffectRecord,
    ) -> bool:
        return replace(
            target,
            provider_metadata=current.provider_metadata,
            provider_receipt=current.provider_receipt,
            payload_retention_schema_version=(
                current.payload_retention_schema_version
            ),
            payload_retention_tier=current.payload_retention_tier,
            payload_retention_sha256=current.payload_retention_sha256,
        ) == current

    @staticmethod
    def _redact_task_run_external_effect_payload_cas(
        cursor: Any,
        *,
        current: ExternalEffectRecord,
        target: ExternalEffectRecord,
        target_tier: PayloadRetentionTier,
        run_id: str,
        expected_effect_state: str,
        expected_transaction_state: str,
    ) -> bool:
        changed_count = cursor.execute(
            """
            UPDATE external_effects
               SET provider_metadata_json = ?, provider_receipt_json = ?,
                   payload_retention_schema_version = ?,
                   payload_retention_tier = ?, payload_retention_sha256 = ?
             WHERE effect_id = ? AND pid = ?
               AND effect_state = ? AND transaction_state = ?
               AND payload_retention_schema_version = ?
               AND payload_retention_tier = ?
               AND (
                    (payload_retention_sha256 IS NULL AND CAST(? AS TEXT) IS NULL)
                    OR payload_retention_sha256 = ?
               )
               AND provider_metadata_json = ? AND provider_receipt_json = ?
               AND EXISTS (
                    SELECT 1 FROM processes AS process
                    JOIN task_runs AS run
                      ON run.run_id = process.task_run_id
                    WHERE process.pid = external_effects.pid
                      AND process.task_run_id = ?
                      AND run.status IN (
                        'finalizing', 'succeeded', 'failed', 'cancelled'
                      )
               )
               AND EXISTS (
                    SELECT 1 FROM task_run_links AS link
                    WHERE link.run_id = ?
                      AND link.evidence_type = 'external_effect'
                      AND link.evidence_id = external_effects.effect_id
               )
            """,
            (
                dumps(target.provider_metadata),
                dumps(target.provider_receipt),
                target.payload_retention_schema_version,
                target_tier.value,
                target.payload_retention_sha256,
                current.effect_id,
                current.pid,
                expected_effect_state,
                expected_transaction_state,
                current.payload_retention_schema_version,
                current.payload_retention_tier,
                current.payload_retention_sha256,
                current.payload_retention_sha256,
                dumps(current.provider_metadata),
                dumps(current.provider_receipt),
                run_id,
                run_id,
            ),
        ).rowcount
        return changed_count == 1

    def insert_human_request(self, request: HumanRequest) -> None:
        self._execute(
            """
            INSERT INTO human_requests (
                request_id, pid, human, payload_json, status, decision_json,
                blocking, created_at, updated_at, revision
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                request.request_id,
                request.pid,
                request.human,
                dumps(request.payload),
                request.status.value,
                dumps(request.decision) if request.decision is not None else None,
                int(request.blocking),
                request.created_at,
                request.updated_at,
                request.revision,
            ),
        )

    def update_human_request(self, request: HumanRequest) -> bool:
        """Compatibility CAS for callers that mutate a freshly read object.

        New terminal paths should use :meth:`compare_and_set_human_request` so
        the expected status remains explicit.  This method still prevents a
        stale object from overwriting a winner and advances the passed
        object's revision only after the durable update succeeds.
        """

        if not isinstance(request, HumanRequest):
            raise ValidationError("human request update requires HumanRequest")
        with self._join_or_begin_transaction() as cursor:
            row = cursor.execute(
                "SELECT * FROM human_requests WHERE request_id = ?",
                (request.request_id,),
            ).fetchone()
            if row is None:
                return False
            expected = self._row_to_human_request(row)
            if expected.revision != request.revision:
                return False
            target = replace(request, revision=request.revision + 1)
            self._validate_human_request_cas(expected, target)
            changed = self._compare_and_set_human_request(
                cursor,
                expected=expected,
                target=target,
            )
            if changed:
                request.revision = target.revision
            return changed

    def compare_and_set_human_request(
        self,
        expected: HumanRequest,
        target: HumanRequest,
    ) -> bool:
        """Atomically replace one exact request revision/status snapshot."""

        self._validate_human_request_cas(expected, target)
        with self._join_or_begin_transaction() as cursor:
            return self._compare_and_set_human_request(
                cursor,
                expected=expected,
                target=target,
            )

    @staticmethod
    def _validate_human_request_cas(
        expected: HumanRequest,
        target: HumanRequest,
    ) -> None:
        if not isinstance(expected, HumanRequest) or not isinstance(target, HumanRequest):
            raise ValidationError("human request CAS requires HumanRequest values")
        immutable_fields = (
            "request_id",
            "pid",
            "human",
            "blocking",
            "created_at",
        )
        changed_identity = [
            field_name
            for field_name in immutable_fields
            if getattr(expected, field_name) != getattr(target, field_name)
        ]
        if changed_identity:
            raise ValidationError(
                "human request CAS cannot change immutable fields: "
                f"{changed_identity}"
            )
        if target.revision != expected.revision + 1:
            raise ValidationError(
                "human request CAS target revision must advance exactly once"
            )

    @staticmethod
    def _compare_and_set_human_request(
        cursor: Any,
        *,
        expected: HumanRequest,
        target: HumanRequest,
    ) -> bool:
        changed_count = cursor.execute(
            """
            UPDATE human_requests
               SET payload_json = ?, status = ?, decision_json = ?,
                   updated_at = ?, revision = ?
             WHERE request_id = ? AND pid = ? AND human = ?
               AND blocking = ? AND created_at = ?
               AND status = ? AND revision = ?
            """,
            (
                dumps(target.payload),
                target.status.value,
                dumps(target.decision) if target.decision is not None else None,
                target.updated_at,
                target.revision,
                expected.request_id,
                expected.pid,
                expected.human,
                int(expected.blocking),
                expected.created_at,
                expected.status.value,
                expected.revision,
            ),
        ).rowcount
        return changed_count == 1

    def get_human_request(self, request_id: str) -> HumanRequest | None:
        rows = self._query("SELECT * FROM human_requests WHERE request_id = ?", (request_id,))
        return self._row_to_human_request(rows[0]) if rows else None

    def list_human_requests(
        self,
        pid: str | None = None,
        *,
        human: str | None = None,
        status: HumanRequestStatus | str | None = None,
        limit: int | None = None,
        newest: bool = False,
    ) -> list[HumanRequest]:
        clauses: list[str] = []
        params: list[Any] = []
        if pid is not None:
            clauses.append("pid = ?")
            params.append(pid)
        if human is not None:
            clauses.append("human = ?")
            params.append(human)
        if status is not None:
            selected_status = status.value if isinstance(status, HumanRequestStatus) else str(status)
            clauses.append("status = ?")
            params.append(selected_status)
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        direction = "DESC" if newest else "ASC"
        sql = f"SELECT * FROM human_requests{where} ORDER BY created_at {direction}, request_id {direction}"
        if limit is not None:
            selected_limit = max(0, int(limit))
            sql += " LIMIT ?"
            params.append(selected_limit)
        rows = self._query(sql, params)
        return [self._row_to_human_request(row) for row in rows]

    def list_human_requests_for_pids(
        self,
        pids: Iterable[str],
        *,
        statuses: Iterable[HumanRequestStatus | str] | None = None,
        limit: int,
        cursor: str | tuple[str, str] | None = None,
    ) -> dict[str, Any]:
        """Return a bounded newest-first Human-request keyset page.

        The cursor is opaque on the wire (``h1``); tuple input is retained for
        repository callers that already decoded it.  PID batches keep every
        statement below backend bind limits and are merged deterministically.
        """

        selected_pids = self._validated_task_run_human_pids(pids)
        selected_limit = self._task_run_page_limit(
            limit,
            default=self.config.task_runs.list_page_size,
            hard_limit=self.config.task_runs.list_hard_limit,
            label="TaskRun Human request list",
        )
        after = self._decode_task_run_human_cursor(cursor)
        selected_statuses = self._validated_task_run_human_statuses(statuses)
        if not selected_pids or selected_statuses == ():
            return {"records": (), "next_cursor": None, "schema_version": 1}

        rows_by_id: dict[str, Any] = {}
        for offset in range(0, len(selected_pids), 400):
            batch = selected_pids[offset : offset + 400]
            for row in self._query_task_run_human_batch(
                batch,
                statuses=selected_statuses,
                after=after,
                limit=selected_limit + 1,
            ):
                rows_by_id[str(row["request_id"])] = row
        return self._task_run_human_page(rows_by_id.values(), selected_limit)

    def _validated_task_run_human_pids(
        self,
        pids: Iterable[str],
    ) -> tuple[str, ...]:
        selected = tuple(dict.fromkeys(str(pid) for pid in pids if str(pid)))
        if any(pid != pid.strip() or "\x00" in pid for pid in selected):
            raise ValidationError("TaskRun Human request PID scope is invalid")
        if len(selected) > self.config.task_runs.recovery_page_hard_limit:
            raise ValidationError("TaskRun Human request PID scope exceeds its hard cap")
        return selected

    @staticmethod
    def _validated_task_run_human_statuses(
        statuses: Iterable[HumanRequestStatus | str] | None,
    ) -> tuple[str, ...] | None:
        if statuses is None:
            return None
        try:
            return tuple(
                dict.fromkeys(HumanRequestStatus(status).value for status in statuses)
            )
        except (TypeError, ValueError) as exc:
            raise ValidationError("TaskRun Human request status is invalid") from exc

    def _query_task_run_human_batch(
        self,
        pids: tuple[str, ...],
        *,
        statuses: tuple[str, ...] | None,
        after: tuple[str, str] | None,
        limit: int,
    ) -> list[Any]:
        clauses = [f"pid IN ({', '.join('?' for _ in pids)})"]
        params: list[Any] = [*pids]
        if statuses is not None:
            clauses.append(f"status IN ({', '.join('?' for _ in statuses)})")
            params.extend(statuses)
        if after is not None:
            clauses.append(
                "(created_at COLLATE BINARY, request_id COLLATE BINARY) < (?, ?)"
            )
            params.extend(after)
        params.append(limit)
        return self._query(
            "SELECT * FROM human_requests "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at COLLATE BINARY DESC, "
            "request_id COLLATE BINARY DESC LIMIT ?",
            params,
        )

    def _task_run_human_page(
        self,
        rows: Iterable[Any],
        limit: int,
    ) -> dict[str, Any]:
        ordered = sorted(
            rows,
            key=lambda row: (str(row["created_at"]), str(row["request_id"])),
            reverse=True,
        )
        records = tuple(
            self._row_to_human_request(row) for row in ordered[:limit]
        )
        next_cursor = None
        if len(ordered) > limit and records:
            last = records[-1]
            next_cursor = self._encode_task_run_human_cursor(
                (last.created_at, last.request_id)
            )
        return {
            "records": records,
            "next_cursor": next_cursor,
            "schema_version": 1,
        }

    @staticmethod
    def _encode_task_run_human_cursor(key: tuple[str, str]) -> str:
        encoded = json.dumps(
            {"created_at": key[0], "request_id": key[1]},
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return "h1." + base64.urlsafe_b64encode(encoded).decode("ascii").rstrip("=")

    @staticmethod
    def _decode_task_run_human_cursor(
        cursor: str | tuple[str, str] | None,
    ) -> tuple[str, str] | None:
        if cursor is None or cursor == "":
            return None
        if isinstance(cursor, tuple):
            if (
                len(cursor) != 2
                or not isinstance(cursor[0], str)
                or not isinstance(cursor[1], str)
                or not cursor[1]
            ):
                raise ValidationError("TaskRun Human request cursor is invalid")
            return cursor
        if not isinstance(cursor, str) or not cursor.startswith("h1.") or len(cursor) > 1024:
            raise ValidationError("TaskRun Human request cursor is invalid")
        try:
            raw = cursor[3:]
            raw += "=" * (-len(raw) % 4)
            decoded = base64.b64decode(raw, altchars=b"-_", validate=True)
            if len(decoded) > 512:
                raise ValueError("cursor exceeds decoded bound")
            payload = json.loads(decoded.decode("utf-8"))
        except (ValueError, UnicodeError, json.JSONDecodeError) as exc:
            raise ValidationError("TaskRun Human request cursor is invalid") from exc
        if not isinstance(payload, dict) or set(payload) != {"created_at", "request_id"}:
            raise ValidationError("TaskRun Human request cursor is invalid")
        created_at = payload.get("created_at")
        request_id = payload.get("request_id")
        if (
            not isinstance(created_at, str)
            or len(created_at) > 128
            or not isinstance(request_id, str)
            or not request_id
            or len(request_id) > 256
        ):
            raise ValidationError("TaskRun Human request cursor is invalid")
        return created_at, request_id

    def list_task_run_human_requests(
        self,
        run_id: str,
        linked_pids: Iterable[str] = (),
    ) -> list[HumanRequest]:
        """List Human rows with both Run membership and durable link evidence."""

        with self._join_or_begin_transaction() as cur:
            pids = self._validated_task_run_pid_scope(run_id, linked_pids)
            if not pids:
                return []
            hard_limit = self.config.task_runs.recovery_page_hard_limit
            rows_by_id: dict[str, Any] = {}
            for offset in range(0, len(pids), 400):
                batch = pids[offset : offset + 400]
                rows = list(
                    cur.execute(
                        "SELECT request.* FROM human_requests AS request "
                        "JOIN processes AS process ON process.pid = request.pid "
                        "WHERE process.task_run_id = ? "
                        f"AND request.pid IN ({', '.join('?' for _ in batch)}) "
                        "AND EXISTS ("
                        "  SELECT 1 FROM task_run_links AS link "
                        "  WHERE link.run_id = ? "
                        "    AND link.evidence_type = 'human_request' "
                        "    AND link.evidence_id = request.request_id"
                        ") ORDER BY request.created_at, request.request_id LIMIT ?",
                        (run_id, *batch, run_id, hard_limit + 1),
                    )
                )
                for row in rows:
                    rows_by_id[str(row["request_id"])] = row
                if len(rows_by_id) > hard_limit:
                    raise ValidationError(
                        "TaskRun Human requests exceed the recovery hard cap"
                    )
        rows = sorted(
            rows_by_id.values(),
            key=lambda row: (str(row["created_at"]), str(row["request_id"])),
        )
        return [self._row_to_human_request(row) for row in rows]

    def redact_task_run_human_request_payload(
        self,
        record: HumanRequest,
        *,
        run_id: str,
        expected_payload_sha256: str,
        expected_status: str,
    ) -> bool:
        """CAS one canonical Run-linked Human payload reduction."""

        if not isinstance(record, HumanRequest):
            return False
        try:
            source_status = HumanRequestStatus(expected_status)
        except (TypeError, ValueError):
            return False
        from agent_libos.evidence.payload_retention import (
            validate_terminal_task_run_human_redaction,
        )

        with self._join_or_begin_transaction() as cur:
            row = self._task_run_human_redaction_source(
                cur,
                run_id=run_id,
                request_id=record.request_id,
            )
            if row is None:
                return False
            current = self._row_to_human_request(row)
            try:
                validate_terminal_task_run_human_redaction(
                    current,
                    record,
                    expected_payload_sha256=expected_payload_sha256,
                    expected_status=source_status,
                )
            except (TypeError, ValueError):
                return False
            if replace(record, payload=current.payload, decision=current.decision) != current:
                return False
            return self._redact_task_run_human_request_payload_cas(
                cur,
                current=current,
                target=record,
                run_id=run_id,
            )

    @staticmethod
    def _task_run_human_redaction_source(
        cursor: Any,
        *,
        run_id: str,
        request_id: str,
    ) -> Any | None:
        return cursor.execute(
            """
            SELECT request.* FROM human_requests AS request
            JOIN processes AS process ON process.pid = request.pid
            JOIN task_runs AS run ON run.run_id = process.task_run_id
            WHERE request.request_id = ? AND process.task_run_id = ?
              AND run.status IN (
                'finalizing', 'succeeded', 'failed', 'cancelled'
              )
              AND EXISTS (
                SELECT 1 FROM task_run_links AS link
                WHERE link.run_id = run.run_id
                  AND link.evidence_type = 'human_request'
                  AND link.evidence_id = request.request_id
              )
            """,
            (request_id, run_id),
        ).fetchone()

    @staticmethod
    def _redact_task_run_human_request_payload_cas(
        cursor: Any,
        *,
        current: HumanRequest,
        target: HumanRequest,
        run_id: str,
    ) -> bool:
        current_decision = (
            dumps(current.decision) if current.decision is not None else None
        )
        target_decision = (
            dumps(target.decision) if target.decision is not None else None
        )
        changed_count = cursor.execute(
            """
            UPDATE human_requests
               SET payload_json = ?, decision_json = ?, revision = revision + 1
             WHERE request_id = ? AND pid = ? AND human = ? AND status = ?
               AND blocking = ? AND created_at = ? AND updated_at = ?
               AND revision = ?
               AND payload_json = ?
               AND ((decision_json IS NULL AND CAST(? AS TEXT) IS NULL)
                    OR decision_json = ?)
               AND EXISTS (
                    SELECT 1 FROM processes AS process
                    JOIN task_runs AS run
                      ON run.run_id = process.task_run_id
                    WHERE process.pid = human_requests.pid
                      AND process.task_run_id = ?
                      AND run.status IN (
                        'finalizing', 'succeeded', 'failed', 'cancelled'
                      )
               )
               AND EXISTS (
                    SELECT 1 FROM task_run_links AS link
                    WHERE link.run_id = ?
                      AND link.evidence_type = 'human_request'
                      AND link.evidence_id = human_requests.request_id
               )
            """,
            (
                dumps(target.payload),
                target_decision,
                current.request_id,
                current.pid,
                current.human,
                current.status.value,
                int(current.blocking),
                current.created_at,
                current.updated_at,
                current.revision,
                dumps(current.payload),
                current_decision,
                current_decision,
                run_id,
                run_id,
            ),
        ).rowcount
        return changed_count == 1

    def enqueue_semantic_assessment_job(
        self,
        record: SemanticAssessmentJobRecord,
    ) -> SemanticAssessmentJobRecord:
        if not isinstance(record, SemanticAssessmentJobRecord):
            raise ValidationError(
                "semantic assessment enqueue requires a typed job record"
            )
        if (
            record.status is not SemanticAssessmentJobStatus.QUEUED
            or record.revision != 0
            or record.attempt_count != 0
        ):
            raise ValidationError("new semantic assessment job must be pristine queued state")
        with self._join_or_begin_transaction() as cursor:
            existing_row = cursor.execute(
                "SELECT * FROM semantic_assessment_jobs WHERE job_id = ?",
                (record.job_id,),
            ).fetchone()
            if existing_row is not None:
                existing = self._row_to_semantic_assessment_job(existing_row)
                if existing != record:
                    raise ValidationError(
                        "semantic assessment job id conflicts with existing content"
                    )
                return existing
            cursor.execute(
                """
                INSERT INTO semantic_assessment_jobs (
                    job_id, assessment_id, kind, status, domain, pid,
                    request_id, operation_id, effect_id, revision,
                    attempt_count, lease_owner_id, lease_id, lease_expires_at,
                    bindings_json, projection_json, projection_sha256,
                    projection_retention, projection_expires_at, error_code,
                    created_at, updated_at, completed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                self._semantic_job_row(record),
            )
        return record

    def get_semantic_assessment_job(
        self,
        job_id: str,
    ) -> SemanticAssessmentJobRecord | None:
        if not isinstance(job_id, str) or not job_id:
            raise ValidationError("semantic assessment job id is invalid")
        rows = self._query(
            "SELECT * FROM semantic_assessment_jobs WHERE job_id = ?",
            (job_id,),
        )
        return (
            self._row_to_semantic_assessment_job(rows[0])
            if rows
            else None
        )

    def get_semantic_assessment_job_for_request(
        self,
        request_id: str,
        request_revision: int,
    ) -> SemanticAssessmentJobRecord | None:
        """Resolve one exact live request capture without an unbounded scan."""

        if not isinstance(request_id, str) or not request_id:
            raise ValidationError("semantic assessment request id is invalid")
        if (
            isinstance(request_revision, bool)
            or not isinstance(request_revision, int)
            or request_revision < 0
        ):
            raise ValidationError("semantic assessment request revision is invalid")
        rows = self._query(
            "SELECT * FROM semantic_assessment_jobs "
            "WHERE request_id = ? "
            "ORDER BY created_at COLLATE BINARY, job_id COLLATE BINARY LIMIT 2",
            (request_id,),
        )
        if len(rows) > 1:
            raise ValidationError(
                "semantic assessment request capture is ambiguous"
            )
        if not rows:
            return None
        job = self._row_to_semantic_assessment_job(rows[0])
        captured_revision = job.projection.get("request_revision")
        if type(captured_revision) is not int or captured_revision != request_revision:
            return None
        return job

    def claim_next_semantic_assessment_job(
        self,
        *,
        lease_owner_id: str,
        lease_id: str,
        lease_expires_at: str,
        updated_at: str,
    ) -> SemanticAssessmentJobRecord | None:
        for label, value in (
            ("lease owner", lease_owner_id),
            ("lease id", lease_id),
            ("lease expiry", lease_expires_at),
            ("updated_at", updated_at),
        ):
            if not isinstance(value, str) or not value:
                raise ValidationError(f"semantic assessment {label} is invalid")
        selected_lease_expires_at = _canonical_semantic_timestamp(
            lease_expires_at,
            "semantic assessment lease expiry",
        )
        selected_updated_at = _canonical_semantic_timestamp(
            updated_at,
            "semantic assessment claim time",
        )
        if _parse_semantic_timestamp(
            selected_lease_expires_at,
            "semantic assessment lease expiry",
        ) <= _parse_semantic_timestamp(
            selected_updated_at,
            "semantic assessment claim time",
        ):
            raise ValidationError(
                "semantic assessment lease expiry must follow its claim time"
            )
        with self._join_or_begin_transaction() as cursor:
            row = cursor.execute(
                """
                SELECT * FROM semantic_assessment_jobs
                 WHERE status = 'queued' AND attempt_count = 0
                   AND (
                     projection_expires_at IS NULL
                     OR projection_expires_at COLLATE BINARY > ?
                   )
                 ORDER BY created_at COLLATE BINARY, job_id COLLATE BINARY
                 LIMIT 1
                """,
                (selected_updated_at,),
            ).fetchone()
            if row is None:
                return None
            expected = self._row_to_semantic_assessment_job(row)
            if (
                expected.projection_expires_at is not None
                and _parse_semantic_timestamp(
                    expected.projection_expires_at,
                    "semantic job projection expiry",
                )
                <= _parse_semantic_timestamp(
                    selected_updated_at,
                    "semantic assessment claim time",
                )
            ):
                # Defend against a noncanonical legacy/corrupt timestamp that
                # passed the raw SQL text predicate. Never claim or egress it.
                return None
            target = replace(
                expected,
                status=SemanticAssessmentJobStatus.CLAIMED,
                revision=expected.revision + 1,
                attempt_count=1,
                lease_owner_id=lease_owner_id,
                lease_id=lease_id,
                lease_expires_at=selected_lease_expires_at,
                updated_at=selected_updated_at,
            )
            changed = cursor.execute(
                """
                UPDATE semantic_assessment_jobs
                   SET status = ?, revision = ?, attempt_count = ?,
                       lease_owner_id = ?, lease_id = ?, lease_expires_at = ?,
                       updated_at = ?
                 WHERE job_id = ? AND status = 'queued' AND revision = ?
                   AND attempt_count = 0
                """,
                (
                    target.status.value,
                    target.revision,
                    target.attempt_count,
                    target.lease_owner_id,
                    target.lease_id,
                    target.lease_expires_at,
                    target.updated_at,
                    expected.job_id,
                    expected.revision,
                ),
            ).rowcount
            return target if changed == 1 else None

    def query_expired_semantic_assessment_jobs(
        self,
        *,
        expired_before: str,
        limit: int,
    ) -> tuple[SemanticAssessmentJobRecord, ...]:
        selected_limit = self._semantic_query_limit(limit, label="semantic job recovery")
        selected_expired_before = _canonical_semantic_timestamp(
            expired_before,
            "semantic job recovery boundary",
        )
        rows = self._query(
            """
            SELECT * FROM semantic_assessment_jobs
             WHERE status = 'claimed'
               AND lease_expires_at COLLATE BINARY <= ?
             ORDER BY lease_expires_at COLLATE BINARY,
                      created_at COLLATE BINARY, job_id COLLATE BINARY
             LIMIT ?
            """,
            (selected_expired_before, selected_limit),
        )
        return tuple(self._row_to_semantic_assessment_job(row) for row in rows)

    def query_semantic_assessment_jobs(
        self,
        *,
        statuses: Iterable[str],
        projection_expires_before: str | None,
        limit: int,
    ) -> tuple[SemanticAssessmentJobRecord, ...]:
        selected_limit = self._semantic_query_limit(limit, label="semantic job")
        try:
            selected_statuses = tuple(
                dict.fromkeys(SemanticAssessmentJobStatus(value).value for value in statuses)
            )
        except (TypeError, ValueError) as exc:
            raise ValidationError("semantic job status filter is invalid") from exc
        if not selected_statuses:
            return ()
        clauses = [
            f"status IN ({', '.join('?' for _ in selected_statuses)})"
        ]
        params: list[Any] = list(selected_statuses)
        if projection_expires_before is not None:
            selected_projection_boundary = _canonical_semantic_timestamp(
                projection_expires_before,
                "semantic projection expiry boundary",
            )
            clauses.append(
                "projection_expires_at IS NOT NULL "
                "AND projection_expires_at COLLATE BINARY <= ?"
            )
            params.append(selected_projection_boundary)
        params.append(selected_limit)
        rows = self._query(
            "SELECT * FROM semantic_assessment_jobs "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY created_at COLLATE BINARY, job_id COLLATE BINARY LIMIT ?",
            params,
        )
        return tuple(self._row_to_semantic_assessment_job(row) for row in rows)

    def semantic_status_aggregate(self) -> SemanticStatusAggregate:
        """Return queue and assessment counts from one database snapshot."""

        job_statuses = tuple(SemanticAssessmentJobStatus)
        assessment_statuses = tuple(SemanticAssessmentStatus)
        assessment_domains = tuple(SemanticDomain)
        shadow_outcomes = (
            "would_issue_exact_once",
            "require_human",
            "would_deny",
        )
        job_columns = ", ".join(
            f"COUNT(CASE WHEN status = ? THEN 1 END) AS job_{status.value}"
            for status in job_statuses
        )
        assessment_columns = ", ".join(
            "COUNT(CASE WHEN status = ? THEN 1 END) "
            f"AS assessment_{status.value}"
            for status in assessment_statuses
        )
        domain_columns = ", ".join(
            "COUNT(CASE WHEN domain = ? THEN 1 END) "
            f"AS domain_{domain.value}"
            for domain in assessment_domains
        )
        outcome_columns = ", ".join(
            "COUNT(CASE WHEN shadow_outcome = ? THEN 1 END) "
            f"AS outcome_{outcome}"
            for outcome in shadow_outcomes
        )
        rows = self._query(
            "WITH job_aggregate AS ("
            f" SELECT COUNT(*) AS job_total, {job_columns}"
            " FROM semantic_assessment_jobs"
            "), assessment_aggregate AS ("
            f" SELECT COUNT(*) AS assessment_total, {assessment_columns},"
            f" {domain_columns},"
            " COUNT(CASE WHEN ood = 1 THEN 1 END) AS assessment_ood_count,"
            f" {outcome_columns}"
            " FROM semantic_assessments"
            ") SELECT job_aggregate.*, assessment_aggregate.*"
            " FROM job_aggregate CROSS JOIN assessment_aggregate",
            (
                *(status.value for status in job_statuses),
                *(status.value for status in assessment_statuses),
                *(domain.value for domain in assessment_domains),
                *shadow_outcomes,
            ),
        )
        if len(rows) != 1:
            raise ValidationError("semantic status aggregate query is inconsistent")
        row = rows[0]

        def count(column: str) -> int:
            value = row[column]
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValidationError(
                    f"semantic status aggregate column {column} is invalid"
                )
            return value

        return SemanticStatusAggregate(
            job_total=count("job_total"),
            job_counts={
                status.value: count(f"job_{status.value}")
                for status in job_statuses
            },
            assessment_total=count("assessment_total"),
            assessment_status_counts={
                status.value: count(f"assessment_{status.value}")
                for status in assessment_statuses
            },
            assessment_domain_counts={
                domain.value: count(f"domain_{domain.value}")
                for domain in assessment_domains
            },
            assessment_ood_count=count("assessment_ood_count"),
            shadow_outcome_counts={
                outcome: count(f"outcome_{outcome}")
                for outcome in shadow_outcomes
            },
        )

    def terminalize_semantic_assessment_job(
        self,
        expected: SemanticAssessmentJobRecord,
        target: SemanticAssessmentJobRecord,
        assessment: SemanticAssessmentRecord,
    ) -> bool:
        self._validate_semantic_job_terminal_cas(expected, target, assessment)
        with self._join_or_begin_transaction() as cursor:
            changed = cursor.execute(
                """
                UPDATE semantic_assessment_jobs
                   SET assessment_id = ?, status = ?, revision = ?,
                       lease_owner_id = NULL, lease_id = NULL,
                       lease_expires_at = NULL, projection_json = '{}',
                       projection_retention = 'hash_only',
                       projection_expires_at = NULL, error_code = ?,
                       updated_at = ?, completed_at = ?
                 WHERE job_id = ? AND status = ? AND revision = ?
                   AND attempt_count = ?
                   AND bindings_json = ? AND projection_sha256 = ?
                   AND (
                     (lease_id IS NULL AND CAST(? AS TEXT) IS NULL)
                     OR lease_id = ?
                   )
                """,
                (
                    target.assessment_id,
                    target.status.value,
                    target.revision,
                    target.error_code,
                    target.updated_at,
                    target.completed_at,
                    expected.job_id,
                    expected.status.value,
                    expected.revision,
                    expected.attempt_count,
                    dumps(dict(expected.bindings)),
                    expected.projection_sha256,
                    expected.lease_id,
                    expected.lease_id,
                ),
            ).rowcount
            if changed != 1:
                return False
            self._append_semantic_assessment(cursor, assessment)
            return True

    @staticmethod
    def _validate_semantic_job_terminal_cas(
        expected: SemanticAssessmentJobRecord,
        target: SemanticAssessmentJobRecord,
        assessment: SemanticAssessmentRecord,
    ) -> None:
        if not all(
            (
                isinstance(expected, SemanticAssessmentJobRecord),
                isinstance(target, SemanticAssessmentJobRecord),
                isinstance(assessment, SemanticAssessmentRecord),
            )
        ):
            raise ValidationError("semantic job terminal CAS requires typed records")
        immutable_fields = (
            "job_id",
            "kind",
            "domain",
            "pid",
            "request_id",
            "operation_id",
            "effect_id",
            "bindings",
            "projection_sha256",
            "created_at",
            "attempt_count",
        )
        changed = [
            name
            for name in immutable_fields
            if getattr(expected, name) != getattr(target, name)
        ]
        if changed or target.revision != expected.revision + 1:
            raise ValidationError(
                "semantic job terminal CAS changed immutable state or revision"
            )
        if expected.status not in {
            SemanticAssessmentJobStatus.QUEUED,
            SemanticAssessmentJobStatus.CLAIMED,
        } or target.status.value not in _TERMINAL_JOB_STATUSES:
            raise ValidationError("semantic job terminal CAS status transition is invalid")
        permitted_targets = {
            SemanticAssessmentJobStatus.QUEUED: {
                SemanticAssessmentJobStatus.CANCELLED,
                SemanticAssessmentJobStatus.EXPIRED,
            },
            SemanticAssessmentJobStatus.CLAIMED: {
                SemanticAssessmentJobStatus.SUCCEEDED,
                SemanticAssessmentJobStatus.FAILED,
                SemanticAssessmentJobStatus.EGRESS_BLOCKED,
                SemanticAssessmentJobStatus.PROVIDER_OUTCOME_UNKNOWN,
                # A claimed job may discover a Host-only policy exclusion
                # before any classifier/provider call.  Its attempt_count=1
                # records the claim while skipped_policy/disabled proves that
                # no external outcome needs replay or recovery.
                SemanticAssessmentJobStatus.CANCELLED,
            },
        }
        expected_attempt_count = (
            0
            if expected.status is SemanticAssessmentJobStatus.QUEUED
            else 1
        )
        if (
            target.status not in permitted_targets[expected.status]
            or expected.attempt_count != expected_attempt_count
        ):
            raise ValidationError(
                "semantic job terminal CAS violates claim/attempt provenance"
            )
        if (
            expected.status is SemanticAssessmentJobStatus.CLAIMED
            and target.status
            is not SemanticAssessmentJobStatus.PROVIDER_OUTCOME_UNKNOWN
            and _parse_semantic_timestamp(
                target.completed_at,
                "semantic assessment job completion time",
            )
            >= _parse_semantic_timestamp(
                expected.lease_expires_at,
                "semantic assessment job lease expiry",
            )
        ):
            raise ValidationError(
                "expired semantic assessment lease can only record an unknown provider outcome"
            )
        SQLRuntimeStore._validate_semantic_assessment_provenance(
            expected,
            target,
            assessment,
        )
        compatible_statuses = {
            SemanticAssessmentJobStatus.SUCCEEDED: {"success"},
            SemanticAssessmentJobStatus.FAILED: {
                "timeout",
                "provider_error",
                "invalid_schema",
                "ood",
                "abstained",
                "stale_input",
            },
            SemanticAssessmentJobStatus.EGRESS_BLOCKED: {"egress_blocked"},
            SemanticAssessmentJobStatus.PROVIDER_OUTCOME_UNKNOWN: {
                "provider_outcome_unknown"
            },
            SemanticAssessmentJobStatus.CANCELLED: {"skipped_policy"},
            SemanticAssessmentJobStatus.EXPIRED: {"stale_input"},
        }
        if assessment.status not in compatible_statuses[target.status]:
            raise ValidationError("semantic assessment status does not match terminal job")
        failed_error_codes = {
            "timeout": "timeout",
            "provider_error": "provider_error",
            "invalid_schema": "invalid_schema",
            "ood": "out_of_distribution",
            "abstained": "abstained",
            "stale_input": "stale_input",
        }
        required_error_code = {
            SemanticAssessmentJobStatus.SUCCEEDED: None,
            SemanticAssessmentJobStatus.FAILED: failed_error_codes.get(
                assessment.status
            ),
            SemanticAssessmentJobStatus.EGRESS_BLOCKED: "egress_blocked",
            SemanticAssessmentJobStatus.PROVIDER_OUTCOME_UNKNOWN: (
                "provider_outcome_unknown"
            ),
            SemanticAssessmentJobStatus.CANCELLED: "disabled",
            SemanticAssessmentJobStatus.EXPIRED: "projection_expired",
        }[target.status]
        if target.error_code != required_error_code:
            raise ValidationError(
                "semantic job error code does not match terminal outcome"
            )

    @staticmethod
    def _validate_semantic_assessment_provenance(
        expected: SemanticAssessmentJobRecord,
        target: SemanticAssessmentJobRecord,
        assessment: SemanticAssessmentRecord,
    ) -> None:
        for name in (
            "assessment_id",
            "job_id",
            "kind",
            "domain",
            "pid",
            "request_id",
            "operation_id",
            "effect_id",
        ):
            if getattr(assessment, name) != getattr(target, name):
                raise ValidationError(
                    f"semantic assessment does not match terminal job field {name}"
                )
        for name in (
            "artifact_sha256",
            "input_sha256",
            "feature_snapshot_sha256",
            "policy_sha256",
            "manifest_sha256",
            "action_sha256",
            "resource_sha256",
            "args_sha256",
            "state_sha256",
            "source_refs_sha256",
            "data_labels_sha256",
            "sink_identity_sha256",
            "tool_schema_sha256",
            "provider_spec_sha256",
            "tenant_bucket_sha256",
        ):
            if expected.bindings.get(name) != getattr(assessment, name):
                raise ValidationError(
                    f"semantic assessment digest does not match frozen job {name}"
                )
        if expected.projection_sha256 != assessment.projection_sha256:
            raise ValidationError(
                "semantic assessment digest does not match frozen job projection_sha256"
            )
        if expected.projection.get("action_id") != assessment.action_id:
            raise ValidationError(
                "semantic assessment action does not match frozen job projection"
            )
        if assessment.created_at != expected.created_at:
            raise ValidationError(
                "semantic assessment creation does not match frozen job"
            )
        if assessment.completed_at != target.completed_at:
            raise ValidationError(
                "semantic assessment completion does not match terminal job"
            )

    def append_semantic_assessment(
        self,
        record: SemanticAssessmentRecord,
    ) -> SemanticAssessmentRecord:
        if not isinstance(record, SemanticAssessmentRecord):
            raise ValidationError("semantic assessment append requires a typed record")
        with self._join_or_begin_transaction() as cursor:
            return self._append_semantic_assessment(cursor, record)

    def _append_semantic_assessment(
        self,
        cursor: Any,
        record: SemanticAssessmentRecord,
    ) -> SemanticAssessmentRecord:
        rows = list(
            cursor.execute(
                "SELECT * FROM semantic_assessments "
                "WHERE assessment_id = ? OR job_id = ?",
                (record.assessment_id, record.job_id),
            )
        )
        if rows:
            if len(rows) != 1:
                raise ValidationError("semantic assessment identity is inconsistent")
            existing = self._row_to_semantic_assessment(rows[0])
            if existing != record:
                raise ValidationError(
                    "semantic assessment identity conflicts with existing evidence"
                )
            return existing
        cursor.execute(
            """
            INSERT INTO semantic_assessments (
                assessment_id, job_id, kind, status, domain, action_id,
                tenant_bucket_sha256, pid,
                request_id, operation_id, effect_id, shadow_outcome,
                ood, record_json, created_at, completed_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                record.assessment_id,
                record.job_id,
                record.kind,
                record.status,
                record.domain,
                record.action_id,
                record.tenant_bucket_sha256,
                record.pid,
                record.request_id,
                record.operation_id,
                record.effect_id,
                record.shadow_outcome,
                int(record.ood),
                dumps(record.to_dict()),
                record.created_at,
                record.completed_at,
            ),
        )
        return record

    def get_semantic_assessment(
        self,
        assessment_id: str,
    ) -> SemanticAssessmentRecord | None:
        if not isinstance(assessment_id, str) or not assessment_id:
            raise ValidationError("semantic assessment id is invalid")
        rows = self._query(
            "SELECT * FROM semantic_assessments WHERE assessment_id = ?",
            (assessment_id,),
        )
        return self._row_to_semantic_assessment(rows[0]) if rows else None

    def query_semantic_assessments(
        self,
        *,
        after: SemanticAssessmentCursor | None,
        limit: int,
        pid: str | None = None,
        request_id: str | None = None,
        operation_id: str | None = None,
        kind: str | None = None,
        status: str | None = None,
        domain: str | None = None,
        action_id: str | None = None,
        tenant_bucket_sha256: str | None = None,
    ) -> SemanticAssessmentPage:
        selected_limit = self._semantic_query_limit(limit, label="semantic assessment")
        if after is not None and not isinstance(after, SemanticAssessmentCursor):
            raise ValidationError("semantic assessment cursor is invalid")
        clauses: list[str] = []
        params: list[Any] = []
        for column, value in (
            ("pid", pid),
            ("request_id", request_id),
            ("operation_id", operation_id),
            ("kind", kind),
            ("status", status),
            ("domain", domain),
            ("action_id", action_id),
            ("tenant_bucket_sha256", tenant_bucket_sha256),
        ):
            if value is not None:
                if not isinstance(value, str) or not value or len(value) > 512:
                    raise ValidationError(f"semantic assessment {column} filter is invalid")
                clauses.append(f"{column} = ?")
                params.append(value)
        if after is not None:
            clauses.append(
                "(created_at COLLATE BINARY, assessment_id COLLATE BINARY) > (?, ?)"
            )
            params.extend((after.created_at, after.assessment_id))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(selected_limit + 1)
        rows = self._query(
            "SELECT * FROM semantic_assessments"
            f"{where} ORDER BY created_at COLLATE BINARY, "
            "assessment_id COLLATE BINARY LIMIT ?",
            params,
        )
        records = tuple(
            self._row_to_semantic_assessment(row)
            for row in rows[:selected_limit]
        )
        next_cursor = None
        if len(rows) > selected_limit and records:
            last = records[-1]
            next_cursor = SemanticAssessmentCursor(
                created_at=last.created_at,
                assessment_id=last.assessment_id,
            )
        return SemanticAssessmentPage(records=records, next_cursor=next_cursor)

    @staticmethod
    def _semantic_query_limit(limit: int, *, label: str) -> int:
        if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
            raise ValidationError(f"{label} query limit must be positive")
        if limit > SEMANTIC_QUERY_HARD_LIMIT:
            raise ValidationError(
                f"{label} query limit exceeds hard cap {SEMANTIC_QUERY_HARD_LIMIT}"
            )
        return limit

    @staticmethod
    def _semantic_job_row(record: SemanticAssessmentJobRecord) -> tuple[Any, ...]:
        return (
            record.job_id,
            record.assessment_id,
            record.kind,
            record.status.value,
            record.domain,
            record.pid,
            record.request_id,
            record.operation_id,
            record.effect_id,
            record.revision,
            record.attempt_count,
            record.lease_owner_id,
            record.lease_id,
            record.lease_expires_at,
            dumps(dict(record.bindings)),
            dumps(dict(record.projection)),
            record.projection_sha256,
            record.projection_retention.value,
            record.projection_expires_at,
            record.error_code,
            record.created_at,
            record.updated_at,
            record.completed_at,
        )

    def _row_to_semantic_assessment_job(
        self,
        row: Any,
    ) -> SemanticAssessmentJobRecord:
        with _persisted_model_decode(f"semantic assessment job {row['job_id']}"):
            bindings = bounded_json_loads(
                row["bindings_json"],
                max_bytes=8 * 1024,
            )
            projection = bounded_json_loads(
                row["projection_json"],
                max_bytes=16 * 1024,
            )
            return SemanticAssessmentJobRecord(
                job_id=row["job_id"],
                assessment_id=row["assessment_id"],
                kind=row["kind"],
                status=SemanticAssessmentJobStatus(row["status"]),
                domain=row["domain"],
                pid=row["pid"],
                request_id=row["request_id"],
                operation_id=row["operation_id"],
                effect_id=row["effect_id"],
                revision=row["revision"],
                attempt_count=row["attempt_count"],
                lease_owner_id=row["lease_owner_id"],
                lease_id=row["lease_id"],
                lease_expires_at=row["lease_expires_at"],
                bindings=bindings,
                projection=projection,
                projection_sha256=row["projection_sha256"],
                projection_retention=SemanticProjectionRetention(
                    row["projection_retention"]
                ),
                projection_expires_at=row["projection_expires_at"],
                error_code=row["error_code"],
                created_at=row["created_at"],
                updated_at=row["updated_at"],
                completed_at=row["completed_at"],
            )

    def _row_to_semantic_assessment(
        self,
        row: Any,
    ) -> SemanticAssessmentRecord:
        with _persisted_model_decode(f"semantic assessment {row['assessment_id']}"):
            value = bounded_json_loads(
                row["record_json"],
                max_bytes=256 * 1024,
            )
            record = SemanticAssessmentRecord.from_dict(value)
            column_projection = (
                record.assessment_id,
                record.job_id,
                record.kind,
                record.status,
                record.domain,
                record.action_id,
                record.tenant_bucket_sha256,
                record.pid,
                record.request_id,
                record.operation_id,
                record.effect_id,
                record.shadow_outcome,
                int(record.ood),
                record.created_at,
                record.completed_at,
            )
            persisted_projection = (
                row["assessment_id"],
                row["job_id"],
                row["kind"],
                row["status"],
                row["domain"],
                row["action_id"],
                row["tenant_bucket_sha256"],
                row["pid"],
                row["request_id"],
                row["operation_id"],
                row["effect_id"],
                row["shadow_outcome"],
                row["ood"],
                row["created_at"],
                row["completed_at"],
            )
            if column_projection != persisted_projection:
                raise ValidationError(
                    "semantic assessment indexed columns disagree with record"
                )
            return record

    # Schema-v6 semantic flow, policy, settlement and rollout evidence.  Every
    # append joins an existing UnitOfWork transaction and is idempotent only
    # when the complete typed record is identical.

    def append_semantic_flow_bundle(
        self,
        *,
        entities: tuple[SemanticFlowEntityRecord, ...] = (),
        activities: tuple[SemanticFlowActivityRecord, ...] = (),
        edges: tuple[SemanticFlowEdgeRecord, ...] = (),
        assertions: tuple[SemanticFlowLabelAssertionRecord, ...] = (),
    ) -> SemanticFlowBundle:
        for values, record_type, label in (
            (entities, SemanticFlowEntityRecord, "flow entities"),
            (activities, SemanticFlowActivityRecord, "flow activities"),
            (edges, SemanticFlowEdgeRecord, "flow edges"),
            (assertions, SemanticFlowLabelAssertionRecord, "flow assertions"),
        ):
            if not isinstance(values, tuple) or any(
                not isinstance(value, record_type) for value in values
            ):
                raise ValidationError(f"semantic {label} must be a typed tuple")
        with self._join_or_begin_transaction() as cursor:
            selected_entities = tuple(
                self._append_semantic_flow_entity(cursor, value)
                for value in entities
            )
            selected_activities = tuple(
                self._append_semantic_flow_activity(cursor, value)
                for value in activities
            )
            for value in edges:
                self._validate_semantic_flow_edge_scope(cursor, value)
            selected_edges = tuple(
                self._append_semantic_flow_edge(cursor, value) for value in edges
            )
            for value in assertions:
                if cursor.execute(
                    "SELECT 1 FROM semantic_flow_entities WHERE entity_id = ?",
                    (value.entity_id,),
                ).fetchone() is None:
                    raise ValidationError(
                        "semantic flow assertion references an unknown entity"
                    )
            selected_assertions = tuple(
                self._append_semantic_flow_assertion(cursor, value)
                for value in assertions
            )
        return SemanticFlowBundle(
            entities=selected_entities,
            activities=selected_activities,
            edges=selected_edges,
            assertions=selected_assertions,
        )

    @staticmethod
    def _validate_semantic_flow_edge_scope(
        cursor: Any,
        record: SemanticFlowEdgeRecord,
    ) -> None:
        endpoints: list[tuple[str, str]] = []
        for node_type, node_id in (
            (record.source_node_type, record.source_node_id),
            (record.target_node_type, record.target_node_id),
        ):
            if node_type == "entity":
                row = cursor.execute(
                    "SELECT pid, tenant_bucket_sha256 FROM semantic_flow_entities "
                    "WHERE entity_id = ?",
                    (node_id,),
                ).fetchone()
            else:
                row = cursor.execute(
                    "SELECT pid, tenant_bucket_sha256 FROM semantic_flow_activities "
                    "WHERE activity_id = ?",
                    (node_id,),
                ).fetchone()
            if row is None:
                raise ValidationError("semantic flow edge references an unknown node")
            endpoint_pid = row["pid"]
            if endpoint_pid is None or str(endpoint_pid) != record.pid:
                raise ValidationError("semantic flow edge PID scope is inconsistent")
            endpoints.append((str(endpoint_pid), str(row["tenant_bucket_sha256"])))
        if endpoints[0][1] != endpoints[1][1]:
            raise ValidationError("semantic flow edge cannot cross tenant buckets")

    def _append_semantic_flow_entity(
        self, cursor: Any, record: SemanticFlowEntityRecord
    ) -> SemanticFlowEntityRecord:
        return self._append_v6_exact(
            cursor,
            table="semantic_flow_entities",
            id_column="entity_id",
            identity=record.entity_id,
            record=record,
            decoder=self._row_to_semantic_flow_entity,
            columns=(
                "entity_id", "kind", "pid", "tenant_bucket_sha256",
                "content_sha256", "version_sha256", "provenance_sha256",
                "baseline_labels_json", "identity_present", "identity_mixed",
                "coverage", "created_at", "schema_version",
            ),
            values=(
                record.entity_id, record.kind, record.pid,
                record.tenant_bucket_sha256, record.content_sha256,
                record.version_sha256, record.provenance_sha256,
                canonical_flow_labels_json(record.baseline_labels),
                int(record.identity_present), int(record.identity_mixed),
                record.coverage, record.created_at, record.schema_version,
            ),
        )

    def _append_semantic_flow_activity(
        self, cursor: Any, record: SemanticFlowActivityRecord
    ) -> SemanticFlowActivityRecord:
        return self._append_v6_exact(
            cursor,
            table="semantic_flow_activities",
            id_column="activity_id",
            identity=record.activity_id,
            record=record,
            decoder=self._row_to_semantic_flow_activity,
            columns=(
                "activity_id", "kind", "pid", "action_id", "effect_id",
                "state_sha256", "provider_spec_sha256", "tool_schema_sha256",
                "model_artifact_sha256", "tenant_bucket_sha256", "created_at",
                "schema_version",
            ),
            values=(
                record.activity_id, record.kind, record.pid, record.action_id,
                record.effect_id, record.state_sha256, record.provider_spec_sha256,
                record.tool_schema_sha256, record.model_artifact_sha256,
                record.tenant_bucket_sha256, record.created_at,
                record.schema_version,
            ),
        )

    def _append_semantic_flow_edge(
        self, cursor: Any, record: SemanticFlowEdgeRecord
    ) -> SemanticFlowEdgeRecord:
        return self._append_v6_exact(
            cursor,
            table="semantic_flow_edges",
            id_column="edge_id",
            identity=record.edge_id,
            record=record,
            decoder=self._row_to_semantic_flow_edge,
            columns=(
                "edge_id", "relation", "source_node_id", "source_node_type",
                "target_node_id", "target_node_type", "pid",
                "provenance_sha256", "created_at", "schema_version",
            ),
            values=(
                record.edge_id, record.relation, record.source_node_id,
                record.source_node_type, record.target_node_id,
                record.target_node_type, record.pid, record.provenance_sha256,
                record.created_at, record.schema_version,
            ),
        )

    def _append_semantic_flow_assertion(
        self, cursor: Any, record: SemanticFlowLabelAssertionRecord
    ) -> SemanticFlowLabelAssertionRecord:
        return self._append_v6_exact(
            cursor,
            table="semantic_flow_label_assertions",
            id_column="assertion_id",
            identity=record.assertion_id,
            record=record,
            decoder=self._row_to_semantic_flow_assertion,
            columns=(
                "assertion_id", "entity_id", "source", "sensitivity_floor",
                "integrity_ceiling", "trust_ceiling", "evidence_sha256",
                "assessment_id", "locator_sha256", "locator_kind",
                "path_sha256s_json", "value_sha256", "ordinal",
                "offset_start", "offset_end", "category", "coverage",
                "created_at", "schema_version",
            ),
            values=(
                record.assertion_id, record.entity_id, record.source,
                record.sensitivity_floor, record.integrity_ceiling,
                record.trust_ceiling, record.evidence_sha256,
                record.assessment_id, record.locator_sha256,
                record.locator_kind,
                canonical_flow_path_sha256s_json(record.path_sha256s),
                record.value_sha256, record.ordinal, record.offset_start,
                record.offset_end, record.category, record.coverage,
                record.created_at, record.schema_version,
            ),
        )

    @staticmethod
    def _append_v6_exact(
        cursor: Any,
        *,
        table: str,
        id_column: str,
        identity: str,
        record: Any,
        decoder: Callable[[Any], Any],
        columns: tuple[str, ...],
        values: tuple[Any, ...],
    ) -> Any:
        rows = list(cursor.execute(
            f"SELECT * FROM {table} WHERE {id_column} = ?", (identity,)
        ))
        if rows:
            existing = decoder(rows[0])
            if existing != record:
                raise ValidationError(
                    f"append-only {table} identity conflicts with existing evidence"
                )
            return existing
        placeholders = ", ".join("?" for _ in columns)
        cursor.execute(
            f"INSERT INTO {table} ({', '.join(columns)}) VALUES ({placeholders})",
            values,
        )
        return record

