    def get_jsonrpc_endpoint(self, endpoint_id: str) -> tuple[JsonRpcEndpointSpec, dict[str, Any]] | None:
        rows = self._query("SELECT * FROM jsonrpc_endpoints WHERE endpoint_id = ?", (endpoint_id,))
        if not rows:
            return None
        row = rows[0]
        return self._dict_to_jsonrpc_endpoint(loads(row["spec_json"], {})), self._jsonrpc_endpoint_row_metadata(row)

    def list_jsonrpc_endpoints(self, text: str | None = None, limit: int | None = None) -> list[tuple[JsonRpcEndpointSpec, dict[str, Any]]]:
        params: list[Any] = []
        sql = "SELECT * FROM jsonrpc_endpoints"
        if text:
            needle = f"%{text.lower()}%"
            sql += " WHERE lower(endpoint_id) LIKE ? OR lower(spec_json) LIKE ?"
            params.extend([needle, needle])
        sql += " ORDER BY endpoint_id"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(limit)
        return [
            (self._dict_to_jsonrpc_endpoint(loads(row["spec_json"], {})), self._jsonrpc_endpoint_row_metadata(row))
            for row in self._query(sql, params)
        ]

    def delete_jsonrpc_endpoint(self, endpoint_id: str) -> None:
        with self.transaction() as cur:
            deleted = cur.execute(
                "DELETE FROM jsonrpc_endpoints WHERE endpoint_id = ?",
                (endpoint_id,),
            )
            if deleted.rowcount == 1:
                self._advance_provider_registry_generation(
                    cur,
                    "jsonrpc_registry_generation",
                )

    def get_jsonrpc_registry_binding(self, endpoint_id: str) -> dict[str, Any]:
        return self._provider_registry_binding(
            table="jsonrpc_endpoints",
            id_column="endpoint_id",
            item_id=endpoint_id,
            counter_name="jsonrpc_registry_generation",
            registry="jsonrpc",
        )

    def upsert_mcp_server(self, server: McpServerSpec, *, registered_by: str, created_at: str) -> None:
        spec_json = self._canonical_provider_registry_spec_json(
            "mcp",
            server,
        )
        with self.transaction() as cur:
            self._fence_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )
            cur.execute(
                """
                INSERT INTO mcp_servers (
                    server_id, spec_json, registered_by, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(server_id) DO UPDATE SET
                    spec_json = excluded.spec_json,
                    registered_by = excluded.registered_by,
                    updated_at = excluded.updated_at
                """,
                (
                    server.server_id,
                    spec_json,
                    registered_by,
                    created_at,
                    created_at,
                ),
            )
            self._advance_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )

    def upsert_mcp_v3_server(
        self,
        server: Any,
        *,
        registered_by: str,
        created_at: str,
    ) -> None:
        """Persist an exact Manifest-v3 server without reinterpreting v1/v2."""

        from agent_libos.mcp.manifest import (
            McpServerManifestV3,
            canonical_mcp_v3_manifest_json,
        )

        if not isinstance(server, McpServerManifestV3):
            raise ValidationError("MCP v3 registry write requires a typed Manifest v3")
        spec_json = canonical_mcp_v3_manifest_json(server)
        with self.transaction() as cur:
            self._fence_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )
            cur.execute(
                """
                INSERT INTO mcp_servers (
                    server_id, spec_json, registered_by, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(server_id) DO UPDATE SET
                    spec_json = excluded.spec_json,
                    registered_by = excluded.registered_by,
                    updated_at = excluded.updated_at
                """,
                (
                    server.server_id,
                    spec_json,
                    registered_by,
                    created_at,
                    created_at,
                ),
            )
            self._advance_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )

    def compare_and_swap_mcp_v3_server(
        self,
        server: Any,
        *,
        expected_current_sha256: str | None,
        registered_by: str,
        created_at: str,
    ) -> bool:
        """Atomically replace one registry row only from an exact digest.

        The registry-generation row is the write fence for *all* MCP registry
        mutations.  A no-op update acquires the SQLite writer lease or the
        PostgreSQL row lock before reading the current manifest, so a second
        Runtime cannot pass a stale import-plan comparison.
        """

        from agent_libos.mcp.manifest import (
            McpServerManifestV3,
            canonical_mcp_v3_manifest_json,
        )

        if not isinstance(server, McpServerManifestV3):
            raise ValidationError("MCP v3 registry CAS requires a typed Manifest v3")
        if expected_current_sha256 is not None and (
            type(expected_current_sha256) is not str
            or re.fullmatch(r"[0-9a-f]{64}", expected_current_sha256) is None
        ):
            raise ValidationError(
                "MCP v3 registry expected_current_sha256 must be a lowercase SHA-256"
            )
        spec_json = canonical_mcp_v3_manifest_json(server)
        with self.transaction() as cur:
            self._fence_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )
            row = cur.execute(
                "SELECT spec_json FROM mcp_servers WHERE server_id = ?",
                (server.server_id,),
            ).fetchone()
            current_sha256 = (
                None
                if row is None
                else hashlib.sha256(
                    self._canonical_provider_registry_spec_json(
                        "mcp",
                        str(row["spec_json"]),
                    ).encode("utf-8")
                ).hexdigest()
            )
            if current_sha256 != expected_current_sha256:
                return False
            cur.execute(
                """
                INSERT INTO mcp_servers (
                    server_id, spec_json, registered_by, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(server_id) DO UPDATE SET
                    spec_json = excluded.spec_json,
                    registered_by = excluded.registered_by,
                    updated_at = excluded.updated_at
                """,
                (
                    server.server_id,
                    spec_json,
                    registered_by,
                    created_at,
                    created_at,
                ),
            )
            self._advance_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )
            return True

    def get_mcp_server(self, server_id: str) -> tuple[McpServerSpec, dict[str, Any]] | None:
        rows = self._query("SELECT * FROM mcp_servers WHERE server_id = ?", (server_id,))
        if not rows:
            return None
        row = rows[0]
        payload = loads(row["spec_json"], {})
        if isinstance(payload, dict) and payload.get("schema_version") == 3:
            return None
        return self._dict_to_mcp_server(payload), self._mcp_server_row_metadata(row)

    def get_mcp_v3_server(self, server_id: str) -> tuple[Any, dict[str, Any]] | None:
        rows = self._query("SELECT * FROM mcp_servers WHERE server_id = ?", (server_id,))
        if not rows:
            return None
        row = rows[0]
        payload = loads(row["spec_json"], {})
        if not isinstance(payload, dict) or payload.get("schema_version") != 3:
            return None
        manifest = self._decode_mcp_v3_registry_spec(str(row["spec_json"]))
        return manifest, self._mcp_server_row_metadata(row)

    def get_mcp_server_manifest(self, server_id: str) -> tuple[Any, dict[str, Any]] | None:
        """Return a typed v1/v2/v3 registry union for modern Host callers."""

        rows = self._query("SELECT * FROM mcp_servers WHERE server_id = ?", (server_id,))
        if not rows:
            return None
        row = rows[0]
        payload = loads(row["spec_json"], {})
        if isinstance(payload, dict) and payload.get("schema_version") == 3:
            selected = self._decode_mcp_v3_registry_spec(str(row["spec_json"]))
        else:
            selected = self._dict_to_mcp_server(payload)
        return selected, self._mcp_server_row_metadata(row)

    def list_mcp_servers(self, text: str | None = None, limit: int | None = None) -> list[tuple[McpServerSpec, dict[str, Any]]]:
        selected: list[tuple[McpServerSpec, dict[str, Any]]] = []
        for row in self._mcp_registry_rows(text=text, limit=limit):
            payload = loads(row["spec_json"], {})
            if isinstance(payload, dict) and payload.get("schema_version") == 3:
                continue
            selected.append(
                (
                    self._dict_to_mcp_server(payload),
                    self._mcp_server_row_metadata(row),
                )
            )
        return selected

    def list_mcp_v3_servers(
        self,
        text: str | None = None,
        limit: int | None = None,
    ) -> list[tuple[Any, dict[str, Any]]]:
        rows = self._mcp_registry_rows(text=text, limit=limit)
        selected: list[tuple[Any, dict[str, Any]]] = []
        for row in rows:
            payload = loads(row["spec_json"], {})
            if not isinstance(payload, dict) or payload.get("schema_version") != 3:
                continue
            selected.append(
                (
                    self._decode_mcp_v3_registry_spec(str(row["spec_json"])),
                    self._mcp_server_row_metadata(row),
                )
            )
        return selected

    def list_mcp_server_manifests(
        self,
        text: str | None = None,
        limit: int | None = None,
    ) -> list[tuple[Any, dict[str, Any]]]:
        rows = self._mcp_registry_rows(text=text, limit=limit)
        selected: list[tuple[Any, dict[str, Any]]] = []
        for row in rows:
            payload = loads(row["spec_json"], {})
            if isinstance(payload, dict) and payload.get("schema_version") == 3:
                manifest = self._decode_mcp_v3_registry_spec(str(row["spec_json"]))
            else:
                manifest = self._dict_to_mcp_server(payload)
            selected.append((manifest, self._mcp_server_row_metadata(row)))
        return selected

    def _mcp_registry_rows(
        self,
        *,
        text: str | None,
        limit: int | None,
    ) -> list[Any]:
        params: list[Any] = []
        sql = "SELECT * FROM mcp_servers"
        if text:
            needle = (
                text.lower().replace("+", "++").replace("%", "+%").replace("_", "+_")
            )
            sql += " WHERE lower(server_id) LIKE ? ESCAPE '+'"
            params.append(f"%{needle}%")
        sql += " ORDER BY server_id"
        if limit is not None:
            if type(limit) is not int or limit < 0:
                raise ValidationError("MCP registry limit must be non-negative")
            sql += " LIMIT ?"
            params.append(limit)
        return self._query(sql, params)

    @staticmethod
    def _decode_mcp_v3_registry_spec(spec_json: str) -> Any:
        from agent_libos.mcp.manifest import (
            canonical_mcp_v3_manifest_json,
            parse_mcp_v3_manifest_mapping,
        )

        payload = loads(spec_json, {})
        if not isinstance(payload, dict) or payload.get("schema_version") != 3:
            raise ValidationError("persisted MCP registry row is not Manifest v3")
        manifest = parse_mcp_v3_manifest_mapping(payload)
        if canonical_mcp_v3_manifest_json(manifest) != spec_json:
            raise ValidationError("persisted MCP Manifest v3 is not canonical")
        return manifest

    def delete_mcp_server(self, server_id: str) -> None:
        with self.transaction() as cur:
            self._fence_provider_registry_generation(
                cur,
                "mcp_registry_generation",
            )
            deleted = cur.execute(
                "DELETE FROM mcp_servers WHERE server_id = ?",
                (server_id,),
            )
            if deleted.rowcount == 1:
                self._advance_provider_registry_generation(
                    cur,
                    "mcp_registry_generation",
                )

    def get_mcp_registry_binding(self, server_id: str) -> dict[str, Any]:
        return self._provider_registry_binding(
            table="mcp_servers",
            id_column="server_id",
            item_id=server_id,
            counter_name="mcp_registry_generation",
            registry="mcp",
        )

    @staticmethod
    def _fence_provider_registry_generation(cur: Any, counter_name: str) -> None:
        fenced = cur.execute(
            "UPDATE runtime_counters SET value = value WHERE counter_name = ?",
            (counter_name,),
        )
        if fenced.rowcount != 1:
            raise ValidationError(
                f"provider registry generation counter is missing: {counter_name}"
            )

    @staticmethod
    def _advance_provider_registry_generation(cur: Any, counter_name: str) -> int:
        updated = cur.execute(
            """
            UPDATE runtime_counters
               SET value = value + 1
             WHERE counter_name = ?
            """,
            (counter_name,),
        )
        if updated.rowcount != 1:
            raise ValidationError(
                f"provider registry generation counter is missing: {counter_name}"
            )
        row = cur.execute(
            "SELECT value FROM runtime_counters WHERE counter_name = ?",
            (counter_name,),
        ).fetchone()
        if row is None or isinstance(row["value"], bool) or int(row["value"]) < 0:
            raise ValidationError(
                f"provider registry generation counter is invalid: {counter_name}"
            )
        return int(row["value"])

    def _provider_registry_binding(
        self,
        *,
        table: str,
        id_column: str,
        item_id: str,
        counter_name: str,
        registry: str,
    ) -> dict[str, Any]:
        # Table and column names are fixed internal constants selected by the
        # two public wrappers above; caller-provided identifiers remain values.
        rows = self._query(
            f"""
            SELECT counter.value AS registry_generation,
                   item.spec_json AS spec_json
              FROM runtime_counters AS counter
              LEFT JOIN {table} AS item ON item.{id_column} = ?
             WHERE counter.counter_name = ?
            """,
            (item_id, counter_name),
        )
        if len(rows) != 1:
            raise ValidationError(
                f"provider registry generation counter is missing: {counter_name}"
            )
        generation = rows[0]["registry_generation"]
        if isinstance(generation, bool) or not isinstance(generation, int) or generation < 0:
            raise ValidationError(
                f"provider registry generation counter is invalid: {counter_name}"
            )
        spec_json = rows[0]["spec_json"]
        digest_input = (
            self._canonical_provider_registry_spec_json(registry, str(spec_json))
            if spec_json is not None
            else dumps(
                {
                    "registry": registry,
                    "item_id": item_id,
                    "state": "absent",
                }
            )
        )
        return {
            "registry_generation": generation,
            "registry_spec_sha256": hashlib.sha256(
                digest_input.encode("utf-8")
            ).hexdigest(),
        }

    def _canonical_provider_registry_spec_json(
        self,
        registry: str,
        value: JsonRpcEndpointSpec | McpServerSpec | Any | str,
    ) -> str:
        """Return the one durable/hash representation for provider specs.

        Existing databases may contain semantically valid numeric spellings
        such as ``timeout_s: 1`` while typed reads intentionally expose a
        float.  Decode and re-encode through the typed storage model so new
        writes, legacy raw rows, live comparisons, and reopen all bind the
        same complete spec without weakening the registry generation fence.
        """

        if registry == "mcp" and isinstance(value, McpServerSpec):
            if value.schema_version == 1 and value.protocol_mode is not None:
                raise ValidationError(
                    "MCP manifest v1 must omit protocol_mode"
                )
            if value.schema_version == 2 and not isinstance(
                value.protocol_mode,
                McpProtocolMode,
            ):
                raise ValidationError(
                    "MCP manifest v2 requires an explicit protocol_mode"
                )
            payload = mcp_server_spec_to_jsonable(value)
        elif registry == "mcp":
            from agent_libos.mcp.manifest import (
                McpServerManifestV3,
                canonical_mcp_v3_manifest_json,
            )

            if isinstance(value, McpServerManifestV3):
                return canonical_mcp_v3_manifest_json(value)
            payload = loads(value) if isinstance(value, str) else loads(dumps(value))
        else:
            payload = loads(value) if isinstance(value, str) else loads(dumps(value))
        if not isinstance(payload, dict):
            raise ValidationError(f"{registry} registry spec must encode an object")
        if registry == "jsonrpc":
            return dumps(self._dict_to_jsonrpc_endpoint(payload))
        if registry == "mcp":
            if payload.get("schema_version") == 3:
                from agent_libos.mcp.manifest import (
                    canonical_mcp_v3_manifest_json,
                    parse_mcp_v3_manifest_mapping,
                )

                canonical = canonical_mcp_v3_manifest_json(
                    parse_mcp_v3_manifest_mapping(payload)
                )
                if isinstance(value, str) and value != canonical:
                    raise ValidationError(
                        "persisted MCP Manifest v3 is not canonical"
                    )
                return canonical
            return canonical_mcp_server_spec_json(
                self._dict_to_mcp_server(payload)
            )
        raise ValidationError(f"unknown provider registry: {registry}")

    def upsert_image(
        self,
        image: AgentImage,
        *,
        registered_by: str,
        source: str | None,
        created_at: str,
    ) -> None:
        self._execute(
            """
            INSERT INTO images (
                image_id, manifest_json, registered_by, source, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(image_id) DO UPDATE SET
                manifest_json = excluded.manifest_json,
                registered_by = excluded.registered_by,
                source = excluded.source,
                updated_at = excluded.updated_at
            """,
            (
                image.image_id,
                dumps(image),
                registered_by,
                source,
                created_at,
                created_at,
            ),
        )

    def get_image(self, image_id: str) -> tuple[AgentImage, dict[str, Any]] | None:
        rows = self._query("SELECT * FROM images WHERE image_id = ?", (image_id,))
        if not rows:
            return None
        row = rows[0]
        return self._dict_to_agent_image(loads(row["manifest_json"], {})), self._image_row_metadata(row)

    def list_images(self, limit: int | None = None) -> list[tuple[AgentImage, dict[str, Any]]]:
        params: list[Any] = []
        sql = "SELECT * FROM images ORDER BY image_id"
        if limit is not None:
            sql += " LIMIT ?"
            params.append(max(0, int(limit)))
        return [
            (self._dict_to_agent_image(loads(row["manifest_json"], {})), self._image_row_metadata(row))
            for row in self._query(sql, params)
        ]

    def delete_image(self, image_id: str, *, registered_by: str | None = None) -> None:
        if registered_by is None:
            self._execute("DELETE FROM images WHERE image_id = ?", (image_id,))
            return
        self._execute("DELETE FROM images WHERE image_id = ? AND registered_by = ?", (image_id, registered_by))

